  AwakerStory_11158_Content = {
    Text = "Thời gian: Năm A.F. 299 tháng @1 ngày @2\nĐịa điểm: Phòng thí nghiệm UG-C03, @2@1, @4, Lentiennam.\nThành phần tham gia: @1, @2, @4, @3\nĐối tượng thí nghiệm: W\nThông tin về người thử nghiệm:\nThân thể là một phụ nữ trưởng thành, sinh ngày 18 tháng 6 năm A.F. 280, quê quán không rõ, đã qua đời do bệnh trong quá trình học tập tại đại học @2, sau đó bị sinh mệnh tâm linh ngoài hành tinh @1 chiếm giữ thân thể và phục hồi sự sống, tiếp tục cuộc sống ban đầu. \n@1 có khả năng di chuyển và thay thế tâm linh, đồng thời có thể quan sát trực quan hiện tượng rỗng rỗng. Mặc dù thân thể con người không thể quan sát hiện tượng rỗng rỗng, nhưng khả năng của chủng tộc @1 cũng đã giúp người thử nghiệm cảm nhận được sự tồn tại của hiện tượng rỗng rỗng từ góc độ tinh thần. Do đó, khi người thử nghiệm lần đầu tiên quan sát thấy hiện tượng rỗng rỗng cách đây 2 năm 8 tháng, người thử nghiệm đã cố gắng di chuyển tâm linh để tránh bị xói mòn thêm. \nMặc dù @1 giữ lại khả năng cảm nhận hiện tượng rỗng rỗng, nhưng người thử nghiệm không thể thoát khỏi ảnh hưởng của nó, việc di chuyển tinh thần thất bại. Sau nhiều lần thử nghiệm, người thử nghiệm đã chủ động liên hệ với đại học @3, hy vọng @3 sẽ chế tạo cô thành thể thức tỉnh, trực tiếp thúc đẩy cuộc thí nghiệm này. \n—— Trích từ 《Ghi chép thí nghiệm: Khả năng chiết xuất bạc tâm từ cơ thể sống》"
  },
  AwakerStory_11158_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11158_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11159_Content = {
    Text = "Cười ngọt ngào như chuông bạc vang vọng trống rỗng, thân thể nhỏ nhắn hiện ra trong ánh nến mờ ảo. Cô ấy là nỗi sợ hãi và khao khát của những kẻ mang tội, là dòng nước mát lành và ly rượu độc của những người hấp hối, mang đến nỗi đau ngọt ngào và sự điên rồ lãng mạn. Tiếng roi da không bao giờ rời tay cô ấy rơi xuống da thịt, phát ra âm thanh \"bộp bộp\", chính là bản nhạc tà ác vang lên trong bóng tối."
  },
  AwakerStory_11159_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11159_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11160_Content = {
    Text = "Sau khi đoàn tụ với Phiệt, Tinkerer đã ổn định cuộc sống tại Đại học Misag. Sau khi bị thương lần nữa trong sự kiện nhà hát P-063 @2, Tinkerer càng trở nên sợ hãi người lạ, vì vậy cô ấy trở nên sống khép kín. Khác với giọng hát cao vút, giọng nói hàng ngày của cô ấy ngọt ngào và trong trẻo, nhưng những người đã nghe thì rất ít.\nCó những người tốt bụng cố gắng quảng bá cho Tinkerer biểu diễn trên sân khấu trong khuôn viên trường, họ còn tìm ra những áp phích từ những năm đầu Tinkerer biểu diễn tại nhà hát và dán khắp các góc quảng cáo trong trường.\nTinkerer không muốn chiều lòng những mong muốn này, những khao khát mãnh liệt chỉ khiến những ký ức mà cô muốn quên lại nổi lên.\n \"Hãy kết thúc bi kịch vô lý này đi. Ở bên cạnh bạn, tôi không còn gì để mong cầu. Nếu có thể, hãy để tôi bị thế giới này quên lãng cũng không sao.\"\n \"Đừng, Tinkerer. Những ngày tháng chúng ta đồng hành phía trước còn dài, nơi này không còn là sao hoang, tôi cũng không còn là gánh nặng của bạn. Bạn nên tìm những điều mình muốn làm, sống vì chính mình.\""
  },
  AwakerStory_11160_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11160_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11161_Content = {
    Text = "Tại Đại học Misag, truyền thuyết trong học đường rằng 「sinh viên dự bị phải chiến đấu với lơ-tan mới có thể trở thành điều tra viên」 ngày càng trở nên dữ dội, khiến nỗi sợ hãi của sinh viên đối với nữ kiếm sĩ mặc áo đen đạt đến đỉnh điểm. Nhiều sinh viên chuyên nghiên cứu lý thuyết chỉ cần nhìn thấy tà váy đen đã đổ mồ hôi lạnh, sợ rằng sẽ gặp phải 「kẻ cuồng chiến」 và phải bỏ mạng trên thao trường. \n Tổng biên tập Hanna Peaslee đã có một cuộc phỏng vấn ngắn với nhân vật chính, trong cuộc phỏng vấn, cô lơ-tan đã có những phát biểu sau: \n 「Tôi không có nhiều thời gian để chơi đùa với trẻ con.」 \n 「Kẻ nhát gan không xứng trở thành đối thủ của tôi—bạn có phải là một trong số đó không? Hay bạn cũng có can đảm đối mặt với hỗn mang?」 \n\n —— Trước thời điểm đóng bài, tổng biên tập vẫn chưa rời khỏi ký túc xá sinh viên. Số báo này của 《Báo trường M》 được biên tập viên thực tập Howard in và phát hành."
  },
  AwakerStory_11161_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11161_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11162_Content = {
    Text = "Năm A.F.315, ngày @2 tháng @1\nBác sĩ Sylvia đã khuyên tôi ghi lại suy nghĩ của mình vào sổ tay để rèn luyện trí nhớ. Mọi người đều nói bác sĩ hiểu biết rất nhiều, chắc chắn sẽ giúp tôi. Vì vậy tôi đã nhờ vả, ngày mai tôi, nhất định không được quên công dụng của cuốn sổ này!\nHôm nay tôi đã hoàn thành việc sản xuất và lắp ráp ống xả, bây giờ nó vừa có thể xả khí, vừa không làm ảnh hưởng đến hoạt động của ống mềm hỗ trợ. Đây chắc hẳn là bước cuối cùng rồi nhỉ? Ít nhất hiện tại tôi không phát hiện vấn đề nào, nhưng cũng không loại trừ khả năng tôi quên mất con ốc nào đó… Chính xác, chắc chắn tôi đã quên điều gì đó, không phải ốc vít thì cũng là ống dẫn, hoặc là bôi trơn bạc đạn? Dầu máy? Thành thật mà nói, tôi luôn cảm thấy tàu Phantom có gì đó không ổn. Nó luôn… thiếu hụt? Có phải từ này không nhỉ? Nó thiếu một thứ rất quan trọng, quan trọng hơn cả động cơ. Nếu không có nó, tôi không thể khởi hành, không thể bước lên hành trình đến những điều không biết, vì đó là của chúng ta@2\nTại sao tôi lại nói chúng ta? Tôi với ai? Tôi có phải đã từng… Tôi nhớ, hình như, @2@4@3\nỜ, đầu tôi đau quá.\nNhưng cuốn sổ này có vẻ rất hữu ích, như vậy ngày mai tôi có thể tiếp tục nhớ lại từ đây, có thể thật sự sẽ nhớ ra cũng không chừng?\n—— Một trong những trang nhật ký duy nhất trong sổ tay của Nốtira."
  },
  AwakerStory_11162_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11162_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11163_Content = {
    Text = "Những kẻ chưa được triệu hồi thật đáng thương, vì họ không thể hiểu được ý nghĩa bất diệt. Những cuộc tranh chấp thế tục thật vô nghĩa, vì chúng chỉ là những trò tiêu khiển nông cạn trong quá trình. \n Tôi từng nhìn thẳng, tôi từng nếm trải, tôi đã sớm khai sáng sứ mệnh của thân thể này. \n Nhưng, nhưng à… số phận thật tàn khốc! Tại sao Ngài... không một lần nữa chọn vị linh mục trung thành nhất của Ngài? \n —— Chắc hẳn Ngài đang ban cho tôi thử thách, Ngài đang kiểm nghiệm niềm tin của tôi. Tôi ở nơi xa nhất với quê hương, vào lúc không có ân sủng của Ngài, niềm tin của tôi đã trải qua hàng vạn năm, chưa từng thay đổi. \n Tôi không thể trở thành người đón chào sự tái sinh của Ngài, nhưng tôi đã chuẩn bị mọi thứ cho sự tái sinh của Ngài. Tôi sẽ tìm cho Ngài một vùng đất vĩnh cửu khác... cả sự không cam lòng và vinh dự đều ở trong tôi, tôi chỉ có thể một mình gánh vác trách nhiệm này... \n Xin tha lỗi cho sự ghen ghét xấu xí của tôi. Chỉ cần có thể một lần nữa thấy được uy nghi của Ngài, chỉ cần có thể xây dựng lại vương quốc của Ngài, tôi sẵn lòng làm bất cứ điều gì."
  },
  AwakerStory_11163_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11163_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11164_Content = {
    Text = "Đầu đầy châu báu, lụa mỏng quấn quýt, nội tâm được che giấu dưới vẻ đẹp tuyệt đỉnh. \n Vẫn có người cho rằng Thái Di Sơ là kẻ yêu hư vinh, nhưng có lẽ đó cũng chỉ là một trong những chiếc mặt nạ của cô ấy. \n \"À, chàng trai đang viết gì vậy? Để ta giúp một tay nhé ——\""
  },
  AwakerStory_11164_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11164_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11165_Content = {
    Text = "Bình đun đã sử dụng cần được làm sạch như mới, bàn bị cháy hỏng do thí nghiệm cần được đánh bóng đến mức phản quang, cân phải được hiệu chuẩn lại mỗi ba ngày. Xuất phát từ sự cuồng nhiệt và tôn trọng đối với khoa học, đối với những bí ẩn của thế giới, cô ấy luôn giữ yêu cầu rất cao đối với những người và sự việc xung quanh. \nTất nhiên, yêu cầu này cũng áp dụng cho chính cô ấy — dù sao thì, không phải ai cũng có thể bình tĩnh chấp nhận cái chết, chủ động yêu cầu trở thành thể thức tỉnh."
  },
  AwakerStory_11165_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11165_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11166_Content = {
    Text = "A. F. 315 năm @1 tháng @2 ngày, 08:13 a. m.\nTại hiện trường hội nghị thẩm tra, nhóm ba và nhóm β7 của Kiểm soát và Quản lý Vật phẩm Ăn mòn(sau đây gọi tắt là DISM) đã đến khu vực ăn mòn L-E-933(tức số @2 Đại lộ Southwark, địa điểm của Nhà sáp Rogers), tiếp nhận nhiệm vụ từ nhóm một và nhóm α2 của DISM, thực hiện công việc vô hại hóa khu vực.\n09:24 a. m.\nThành viên DISM James xuất hiện triệu chứng đau đầu, buồn nôn, chóng mặt khi đang dọn dẹp khu vực ngầm của bảo tàng sáp.\n10:47 a. m.\nThành viên nhóm ba Roland, thành viên DISM Zachary, Bolton đã chạy trốn khỏi khu vực ngầm. Cả ba báo cáo rằng, bóng tối dưới lòng đất đã nuốt chửng họ, đưa họ vào một không gian đầy sao, những màu sắc hữu hình quấn lấy nhau trong không gian, rực rỡ nhưng khiến họ lạnh toát. Sau đó, những màu sắc này ngưng tụ thành vô số con chuột, lao nhanh về phía họ.\nBolton từ chối tiếp tục làm việc, trở về văn phòng của hội nghị thẩm tra tại Lentiennam. Thành viên nhóm ba Roland và DISM Zachary cùng đội trưởng nhóm ba Fisher lại vào khu vực ngầm để kiểm tra liên quan.\n13:03 p. m.\nSau khi kiểm tra tìm kiếm, đội trưởng nhóm ba Fisher đã tìm thấy và thu hồi lõi bạc L3202 trong lớp sáp bị ăn mòn còn lại dưới lòng đất. Đã giao cho Đại học Misaque để xử lý tiếp theo.\n——\"Báo cáo xử lý vô hại khu vực ăn mòn L-E-933\""
  },
  AwakerStory_11166_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11166_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11167_Content = {
    Text = "24 chuyển đến chưa đầy một tháng thì phát hiện nhà mình bị trộm. \nĐầu tiên là pho mát, sau đó là bánh mì, sữa, cà chua... Thực phẩm trong nhà luôn mất đi một chút ít mà không để lại dấu vết. \nCô kiên nhẫn canh chừng nhiều ngày, cuối cùng đã phát hiện ra thủ phạm — một con chuột. Nó lắc lư tránh được bẫy mà 24 đã đặt, cầm hai cây nấm rồi biến mất sau cánh cửa hầm. \n24 mở cửa hầm, đi xuống theo cầu thang ẩm ướt và mốc meo, phát hiện ra đây thông với một đường cống ngầm. \nCon chuột cầm nấm chạy vào bóng tối. 24 theo sau, trong bóng tối nhìn thấy đôi mắt sáng như của một con sói con. Cô mặc chiếc áo rách, nằm dưới tờ báo cũ trong cái lạnh gần âm độ, run rẩy dữ dội. \nTrái tim 24 bị châm chích nhẹ. \n \"Nấm không nên ăn sống, sẽ bị bệnh đấy.\"\nCậu bé vẫn im lặng. \n24 lên nấu một nồi súp nấm, múc một bát nhỏ để trên bàn, sau đó đi ngủ. Cô phải dậy làm việc lúc 6 giờ sáng hàng ngày, hầu như không có thời gian nghỉ ngơi. \nKhi tỉnh dậy vào ngày hôm sau, bát vẫn ở vị trí ban đầu, nhưng súp đã được uống sạch. \nTừ đó, 24 thỉnh thoảng làm thêm một chút thức ăn để đãi hàng xóm dưới tầng. Đối phương cũng thỉnh thoảng tặng cô một số quà tặng nhỏ, thường là những đồ trang sức, đồ chơi nhặt được từ đâu đó... \n\nTừ đó, một mối quan hệ mới được hình thành."
  },
  AwakerStory_11167_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11167_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11167_UnlockDesc_1 = {
    Text = "Hoàn thành chương 2 bình thường của cốt truyện \"Nhân danh bình tượng nến\""
  },
  AwakerStory_11168_Content = {
    Text = "Người bạn tốt của chúng ta, nhà báo tài ba Hannah Peasly, đã tìm được tài liệu nghiên cứu của Hilaster từ đâu đó. Nhờ vào sự táo bạo của cô nhà báo này, những tài liệu mật và cuộc phỏng vấn ngắn giữa họ giờ đây đã trở nên nổi tiếng. \n\nSau khi đọc tài liệu mật, Hannah đã đặt một câu hỏi với Hilaster, người thường ngày vốn thiếu cảm xúc. \n\n \"Hầu hết các thân thể được đánh thức đều có những nguyện vọng chưa hoàn thành, đây là một trong những lý do họ hợp tác với trường học. Nhưng trong tài liệu này, phần nguyện vọng của cô lại để trống. Cô không có điều gì muốn hoàn thành sao? Hoặc, ý nghĩa việc cô trở thành thân thể được đánh thức nằm ở đâu?\"\n\n \"Có, tôi có.\"\n\nBiểu cảm của cô gái không hề lộ ra bất kỳ sơ hở nào, vẫn hư vô và thanh cao như mọi khi. Nếu không vì câu trả lời ngắn gọn và đầy lo lắng ấy, cô nhà báo hầu như đã nghĩ rằng đối phương không nghe thấy câu hỏi của mình. \n\n\n \"Tôi sẽ tìm thấy nguyện vọng... Mọi người đều mong như vậy, vì thế, tôi sẽ tìm thấy nó.\"\n\nGiọng nói nhẹ nhàng, tựa như một giấc mơ dễ tan vỡ."
  },
  AwakerStory_11168_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11168_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11169_Content = {
    Text = "Mỗi lời nói, mỗi hành động đều thực hiện trung thành, mỗi cử chỉ đều thể hiện đức hạnh. \n Dù \"biết lễ nghĩa và luôn nghiêm khắc với bản thân\"đã khắc sâu vào linh hồn, nhưng Kỵ sĩ của Đức hạnh này chắc chắn vẫn mang dáng dấp của một đứa trẻ. \n Nhưng xin đừng lo lắng, dù cái giá phải trả là sự diệt vong vĩnh viễn, Orci sẽ nỗ lực hết mình để hoàn thành mệnh lệnh của chúa công. \n Mong rằng ngày đó sẽ không bao giờ đến."
  },
  AwakerStory_11169_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11169_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11170_Content = {
    Text = "Vị vua trẻ đang say giấc trên ngai vàng, khi tỉnh dậy đã ban bố sắc chỉ, quyền lực lan tỏa khắp vương quốc. \n Mặt trời chưa lặn, nhà vua đã cảm thấy mệt mỏi. Ngài chán ngấy quyền năng của chính mình, cũng chán ngấy trí tuệ siêu phàm, chán ngấy sự tôn sùng cuồng nhiệt và cống hiến của tín đồ, và cũng chán ngấy giấc mơ dài vượt qua vạn cổ. \n Không ai biết trong giấc ngủ dài ngài đã mơ thấy điều gì, nhưng họ nên cảm thấy may mắn vì có được hạnh phúc của sự ngu dốt này."
  },
  AwakerStory_11170_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11170_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11171_Content = {
    Text = "\"Phụ thân nhân từ đã từng khuyên bảo: Các ngươi hãy chăm sóc những thứ trên trời, dưới đất, dưới nước và trong lòng đất. Bởi vì vạn vật đều là con cháu của ta.\"\n \"Vì vậy, ta muốn nói: Hãy đặt tất cả đau khổ lên người ta, để những ai đang chịu khốn khó, chịu đớn đau bởi bệnh dịch được giải thoát, để những bệnh tật, những điên cuồng, tất cả đều tan ra như tuyết và băng. Hãy để các ngươi, anh chị em của ta, đạt được hạnh phúc mãi mãi.\n\" Hãy đốt cháy ta, hãy mài nhẵn xương ta, hãy hủy hoại thịt ta. Chỉ cần các ngươi có thể tìm được niềm an ủi, ta cũng không oán trách gì.\"\n——B. F. 1@1, ngày 30 tháng 5, Sal@1do·Martin@2·I@1yas, ghi lại tại @3 Tòa thẩm phán"
  },
  AwakerStory_11171_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11171_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11172_Content = {
    Text = "Phiệt là một hạt giống phai màu, khó có thể phá vỡ vỏ. \n Mọi người thương hại cô vì sự khiếm khuyết của cô, yêu thương cô vì sự suy nhược của cô. \n Biết rằng cô là người tự nguyện ở lại trong vỏ, đã trở thành bột mịn, trở thành bụi sao."
  },
  AwakerStory_11172_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11172_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11173_Content = {
    Text = "Sau sự kiện @3@1, Lắc đã trở thành cố vấn đặc biệt của Đại học Misaque. \nLắc là một cố vấn tận tâm. Từ những vụ mất tích kỳ lạ của giáo sư hoặc hỏng hóc không rõ nguyên nhân của thiết bị, đến những việc vặt như tìm mèo, tìm chó, Lắc đều có thể kiên nhẫn và nhanh nhẹn giải quyết một cách hài lòng. \nNhanh chóng, với vẻ ngoài độc đáo, phong cách lịch thiệp và thói quen sẵn sàng giúp đỡ người khác, Lắc đã trở thành một biểu tượng được thanh niên và thiếu nữ ở Misaque yêu mến. \nGiáo sư Dexter từng thốt lên: \"Tất cả sự chú ý đều bị những người trẻ tuổi chiếm mất.\"\nNhưng khi anh dần hòa nhập vào cuộc sống trường học, mọi người nhận ra rằng thời gian Lắc xuất hiện trước công chúng ngày càng ít đi. \nĐồng thời, trong một tầng hầm bỏ hoang của Misaque, tiếng xóc xúc xắc bắt đầu xuất hiện thường xuyên."
  },
  AwakerStory_11173_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11173_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11174_Content = {
    Text = "Người lần đầu gặp cô ấy sẽ không có bất kỳ ý nghĩ nào về việc lại gần hay giao tiếp, bản năng sinh tồn sẽ ra sức phát ra cảnh báo tránh xa. \n Đó là một người hoàn toàn điên rồ, hoặc nói đúng hơn là một con quái vật hoàn toàn. \n Nếu có thể chọn lại, có lẽ cô ấy sẽ muốn trở thành một con quái vật, tốt hơn là phải trải qua tất cả những gì của con người. \n Cô ấy không bao giờ tin tưởng bất kỳ ai, khi đôi mắt đỏ tươi của cô ấy nhìn về phía bạn, trong ánh mắt đó không phải là sự nghi ngờ, mà là sự lạnh lùng và ý định giết chóc. \n Cô ấy đã chán ghét sự nghi ngờ, tất cả mọi người trong mắt cô ấy đều tầm thường như nhau. \n Nếu cần một lời khuyên để sống chung với cô ấy, đó chính là đừng cố gắng thuần hóa một con quái vật thực sự, đó không phải là một sinh vật hiền lành, chỉ cần có một chút cơ hội, vuốt và nanh của cô ấy sẽ xuyên thấu cổ họng bạn. \n Hãy trốn chạy trước khi cô ấy nhắm vào bạn, và cầu nguyện rằng con mồi tiếp theo của cô ấy không phải là bạn."
  },
  AwakerStory_11174_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11174_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11175_Content = {
    Text = "Hãy đến nhảy múa đi! Nhảy một điệu vui tươi, nhảy một điệu điên rồ! Hãy cùng cô ấy cười đùa, khuấy động không khí lên đến đỉnh điểm. \n Đến lúc đó, sẽ đến lượt nhân vật chính xuất hiện. \n Tại điểm giao nhau của những tia đèn chiếu sáng, phù thủy điên rồ đã đưa tay vào chiếc mũ dài của cô. Còn những gì cô ấy lấy ra từ khoảng không vô tận, là những dải băng đầy màu sắc, là chim bồ câu trắng bay lượn, hay là vuốt của quái vật kinh dị… e rằng chỉ có cô ấy mới biết được."
  },
  AwakerStory_11175_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11175_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11176_Content = {
    Text = "Đó là món quà lưu niệm mà giáo sư Dexter mang về từ chuyến du lịch ở bờ biển Fèi Fúer.\nKhí hậu biển ấm áp dễ chịu của Fèi Fúer, với Bệnh viện dưỡng lão Sevarda có lịch sử hơn trăm năm tọa lạc bên bờ biển, hàng năm có vô số du khách chọn nơi đây để tận hưởng kỳ nghỉ.\nTrong chiếc lọ thủy tinh bị vết nước và rong biển vướng víu này, chứa một ít bột trong suốt. Nó không phải là một chiếc chai trôi dạt do nạn nhân của vụ đắm tàu để lại, cũng không phải là sản phẩm thủ công từ cát địa phương. Rõ ràng giáo sư Dexter đã nhận ra rằng, bên trong chiếc lọ đó chứa bột bạc tâm, nói cách khác, là một ý chí đang trú ngụ bên trong.\nÔng nói rằng đó là thứ được mua từ tay ngư dân địa phương, người này đã nói mập mờ về những điều kỳ lạ mà gần đây họ gặp phải. Vào sáng sớm vài ngày trước, khi ra khơi, ngư dân đã gặp phải một đợt cá kỳ lạ. Bây giờ không phải là mùa sinh sản hay trú đông, nhưng đàn cá lại tụ tập ở một chỗ lâu không rời. Khi kéo chiếc lưới nặng trĩu lên, họ phát hiện trong đó có một chiếc lọ kỳ lạ. Ngư dân cảm thấy hiếu kỳ, nhưng cũng mơ hồ cảm thấy bất an, như thể sẽ bị chiếc lọ kỳ lạ này nguyền rủa, mang đến vận xui. Sau đó vài ngày, trong vùng biển này không còn bắt được cá nữa."
  },
  AwakerStory_11176_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11176_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11177_Content = {
    Text = "Toán học: 0 điểm. Ô Ryta thậm chí còn được 2 điểm\nTiếng Anh: Không đạt. Mất rất nhiều thời gian mới hiểu được sự khác biệt giữa \"ca làm việc\" và \"rác rưởi\"\n……\nLịch sử: Không đạt. Khẳng định Caligula là hoàng đế La Mã vĩ đại nhất vì ông đã xây dựng nhiều đấu trường\n\nĐánh giá nguy hiểm: C. Khi giao tiếp với các thể thức tỉnh khác, thể hiện một mức độ hung hăng nhất định. Mối đe dọa không lớn, không cần đặc biệt chú ý\nGhi chú: Học sinh này gần như không có khả năng tự chăm sóc (lại là một kẻ bị nô lệ hóa), cần phải theo dõi thường xuyên, không thể để cô ấy lại sử dụng kem tuyết như một chất tẩy răng nữa.\n—— Trích từ A.F.313, \"Hồ sơ sinh viên hàng năm của Misaque\""
  },
  AwakerStory_11177_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11177_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11178_Content = {
    Text = "@2 năm, thành phố Akagu. \n Sau hàng nghìn năm khát khao cuối cùng cũng bùng nổ, giết chóc, uống máu, giết chóc, uống máu—— cuối cùng, trước mặt anh chỉ còn lại một sa mạc bao la và vô số xác chết khô cằn, ngay cả kền kền cũng sợ hãi không dám lại gần anh. \n Anh quỳ trên cát vàng, cười ha hả: Thoải mái! Thật @1 thoải mái! \n Tiếp theo, hãy để anh tự tay vẽ nên một dấu chấm hoàn hảo cho bữa tiệc giết chóc này. \n Chiến binh cắn vào cổ tay mình, anh đã hút cạn máu của chính mình, cũng ngã xuống trong hồ máu đỏ tươi này."
  },
  AwakerStory_11178_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11178_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11179_Content = {
    Text = "\"Ôrla, từ hôm nay, tất cả những bài thơ của bạn tôi sẽ giúp bạn cất giữ cẩn thận. Sau này, tôi sẽ đổi hoa của mình lấy thơ của bạn!\"\n \"Koliet, bạn chắc chắn sẽ quay lại cứu tôi... phải không?\""
  },
  AwakerStory_11179_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11179_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11180_Content = {
    Text = "Vào lúc 18 giờ chiều hôm qua, phòng CB-101 nằm dưới tòa nhà Hoàng tử của Đại học Misaque đã bị phá hoại bởi một người không rõ danh tính. Cửa phòng gia cố bị hư hại nghiêm trọng, trên tường trong và ngoài phòng đều có dấu vết cháy đen hình tia chớp, hiện trường lộn xộn. \n「Dòng điện cực mạnh trong thời gian ngắn có thể gây ra những vết thương như vậy,」 Tiến sĩ Adams, chuyên gia ngành điện, đã nhận xét về các dấu vết trên tường, 「điều này cần một điện áp rất lớn. Nếu là thiết bị thông thường, nó sẽ rất khổng lồ, khó mà che giấu. Nhưng nếu là bạc tâm... mọi thứ đều có thể.」 \n Trong bối cảnh bạc tâm bị quản lý chặt chẽ bởi Khoa Thức Tỉnh trong nhiều năm, thật khó để tưởng tượng có ai đó có thể sử dụng bạc tâm mà không bị phát hiện, do đó, nhiều ánh mắt đã chuyển sang những thể thức tỉnh mang năng lượng bạc tâm trong cơ thể. \n「Theo tôi, chắc chắn là cô ấy đã làm việc này.」 Một sinh viên của Khoa Thức Tỉnh không muốn tiết lộ danh tính đã nói với phóng viên. Khi được hỏi cụ thể là ai, anh ta có vẻ hơi căng thẳng, 「Chính là『cô ấy』, người được gọi là『Người Tiktok』! Bạn không nghe thấy tiếng dòng điện liên tục trong cơ thể cô ấy sao? Mỗi khi nhắc đến dòng điện, tôi lại nghĩ đến cô ấy, chắc chắn là vậy.」 \n Nhiều sinh viên đã bày tỏ những nghi ngờ tương tự. Nhưng thể thức tỉnh hành động như con rối lên dây, với nụ cười kỳ quái không hề đơn độc, một vài điều tra viên công khai ủng hộ Erika và kêu gọi mọi người hãy dựa trên sự thật, dựa vào chứng cứ, đừng để thành kiến cá nhân gây tổn hại cho người khác. \n Đối với điều này, Tiến sĩ Sokolova, người phụ trách tạm thời của Khoa Thức Tỉnh, từ chối bình luận. Vụ việc vẫn đang được điều tra thêm. \n —— Trích từ《Nhật báo Misaque》,《Khám Phá Sự Cố Nổ Phòng CB-101》"
  },
  AwakerStory_11180_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11180_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11181_Content = {
    Text = "Cô ấy luôn kiêu ngạo tự xưng là\"Mẹ của Thần\", lạnh lùng và đầy thù địch, gạt bỏ mọi người ra khỏi vùng an toàn của mình. Người lần đầu gặp cô, khó mà liên tưởng đến cô tiểu thư nhỏ kiêu ngạo ngày nào.\n\"Nhưng về bản chất họ vẫn là một người,\" Người Giữ Bí Mật luôn cố chấp truyền đạt điều này với mọi người,\"Chỉ cần bạn từng thấy cô ấy một mình ngồi ăn ngấu nghiến bánh nhỏ là hiểu ngay thôi.\""
  },
  AwakerStory_11181_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11181_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11182_Content = {
    Text = "Thiên tài và kẻ điên chỉ cách nhau một sợi tóc. Là thiên tài rực rỡ nhất của Misaque, sự sa ngã của cô cũng giống như tòa nhà sụp đổ, từ đống đổ nát của lý trí chỉ còn lại một con quỷ điên cuồng nhất. \nCô ấy vẫn thường khoác lên mình lớp áo khoa học, đổ sinh lực, nhân tính, tình yêu và hủy diệt vào chảo, chế tạo thành thuốc độc hủy diệt thế giới."
  },
  AwakerStory_11182_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11182_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11183_Content = {
    Text = "Đừng mong đợi bất cứ điều gì về sự thông minh của sứa, Ô Ryta không thể hiểu được những gì mình đã trải qua, điều duy nhất có thể chắc chắn là cô ấy từng sống ở ngôi làng không người. Mỗi khi nói về câu chuyện quá khứ, cô ấy luôn chuyển hướng chủ đề bằng cách giả vờ hiểu biết, do đó Ô Ryta hầu như không giúp ích gì cho nghiên cứu về hiện tượng rỗng rỗng, thảm họa và các ngành khoa học khác. \n Tuy nhiên, với tính cách vô hại hiếm có trong số những thân thể được đánh thức, Ô Ryta rất được yêu mến bởi giáo viên và học sinh trong hệ thống thức tỉnh, và Khổ Lệ Đặc, người dẫn đầu nghiên cứu sinh học về hiện tượng rỗng rỗng, cũng đặc biệt quan tâm đến cô ấy. \n Nhân tiện, sau khi hợp nhất với ý thức tập thể của sứa, cô ấy đã có khả năng phân chia và tăng sinh. Dù chỉ là những con sứa bình thường được tạo ra, Ô Ryta vẫn hào hứng cầm \"bạn đồng hành\"đi khoe khắp nơi - mặc dù không phân biệt được cá thể bạn đồng hành, cô ấy không rõ mỗi lần mình mang ra trưng bày đều là cùng một con sứa."
  },
  AwakerStory_11183_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11183_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11184_Content = {
    Text = "■số hiệu hồ sơ: AF315-C01\n■biệt danh thân thể được đánh thức: @2Hành Giả\nThân thể được đánh thức này được quan sát lần đầu tiên vào tháng @1 năm A. F. 315.\nTrong thí nghiệm \"thiên nhiên mật cảnh\", do ảnh hưởng của sự cảm ứng tinh thần từ các vật chất đồng nguồn, \"thiên nhiên mật cảnh\" dựa trên lĩnh vực tinh thần của học sinh @2 cấp độ Ramona Dexter đã bất ngờ vượt qua giới hạn chiều không gian.\nNgười giữ bí mật đương nhiệm đã xác nhận sự tồn tại của thế giới bên ngoài chiều không gian trong \"thiên nhiên mật cảnh\" này, đồng thời cũng xác nhận lực lượng @2 sẽ gây ra những tác động như thế nào đối với Ramona Dexter.\nSau đó, Viện Nghiên Cứu Thể Thức Tỉnh chính thức bắt đầu nghiên cứu về \"Thân Thể Được Đánh Thức Nguồn Gốc\".\nĐồng thời, kế hoạch giảng dạy cho khóa học kiểm soát sức mạnh của Ramona Dexter cũng đang được đưa vào lịch trình."
  },
  AwakerStory_11184_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11184_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11185_Content = {
    Text = "Mặc áo choàng đen, dưới lớp vải dài ẩn giấu thân hình gầy guộc của Miriam. \n Cô ấy im lặng, hiện ra với một gương mặt đan xen giữa tín tâm và bi thương, giống như bức tranh tường về Đức Mẹ, mang theo ý nghĩa huyền bí vô tận. \n Cô ấy dồn hết tâm trí, đợi chờ một thời khắc đặc biệt. \n Sắp đến rồi, ngày hẹn ước sắp sửa đến……"
  },
  AwakerStory_11185_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11185_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11186_Content = {
    Text = "Hilaster gia nhập trường học trong phút đầu tiên, đã bị Đóa đưa đi và chấp nhận đánh giá toàn diện. \n Là một thể thức tỉnh được triệu hồi không theo quy trình đại học, trạng thái tinh thần của Hilaster rất ổn định. Nhưng ngược lại, dù là cường độ thể tinh thần hay chỉ số Nos được dùng làm tiêu chuẩn đánh giá cường độ bạc tâm, Hilaster đều chưa đạt tiêu chuẩn của một thể thức tỉnh. \n Tuy nhiên, như một đóa hoa vô hình nở rộ trong hư không, cô ấy đã đến thế giới này với tư cách là thể thức tỉnh. \n Mặc dù không biểu hiện bất thường trong các hoạt động hàng ngày và nhiệm vụ ngoài trời, nhưng qua việc giám sát dữ liệu, chúng tôi biết rằng tình trạng của Hilaster không lạc quan: ý chí yếu ớt của cô ấy đang dần mất đi. \n Hiện tại, Khoa Thức Tỉnh đang chuẩn bị một giáo đoàn quy mô nhỏ, hy vọng duy trì sự tồn tại của Hilaster bằng cách cung cấp niềm tin, những ai có ý muốn tham gia và thông thạo nước xin vui lòng liên hệ với cô Sylva."
  },
  AwakerStory_11186_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11186_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11187_Content = {
    Text = "Một vết sẹo ngang qua cổ anh ta. Dân tộc của anh ta đã chết từ một vết sẹo, trong khi anh ta nhận được sức mạnh từ một vết sẹo. \nBị đuổi khỏi lãnh thổ như một con chó không nhà, liếm láp vị đắng của thất bại và tuyệt vọng, khi bị mắc kẹt giữa biển cả mênh mông, anh ta đã cầu nguyện với thần linh để được sức mạnh vượt qua. \nSứ đồ của thần linh đã đáp lại lời cầu nguyện, chém đứt cổ anh ta. \nSứ đồ của thần linh đã đáp lại lời cầu nguyện, từ cái cổ bị đứt đã nảy sinh ra những mảnh vỡ bất tử. \nSứ đồ của thần linh đã đáp lại lời cầu nguyện, dẫn dắt anh ta vào đại sảnh của sự sống vĩnh cửu."
  },
  AwakerStory_11187_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11187_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11188_Content = {
    Text = "Cô ấy đã có một xuất thân khiến người khác ghen tị: được nuôi dưỡng như người thừa kế duy nhất, một cô gái mồ côi, thật là may mắn. \n Cô ấy đã có một trí tuệ khiến mọi người ngạc nhiên: một tuổi đã biết nói, hai tuổi đã biết biện luận, ba tuổi đã bắt đầu hiểu biết về thế giới. \n Cô ấy đã có tài năng khiến mọi người trầm trồ: nhớ như in, cầm kiếm thành thạo. Với độ tuổi không thể tin được, cô đã hoàn thành xuất sắc chương trình dự bị nghiêm ngặt của Đại học Misaque. \n Cô ấy đã có những người bạn đáng tin cậy, cùng nhau dựa vào nhau, cùng nhau tiến về phía bóng tối và điều chưa biết. \n <Italic:Cô ấy đã có…>"
  },
  AwakerStory_11188_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11188_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11189_Content = {
    Text = "Sự gia nhập của Đóa là khoảnh khắc duy nhất rực rỡ của Đại học Misaque trong mắt thế giới bên ngoài. \n Vô số người trong giới học thuật than thở, tiếc nuối rằng dù là kỳ tài trời ban cũng không thoát khỏi xiềng xích của thế tục — cô ấy vì tài phú mà bị một trường đại học vô danh thu nạp, nhiễm mùi đồng tiền. \n Khi thế giới bên ngoài chỉ trích sự sa đọa tự nguyện của cô, Đóa đã nhận được thứ quý giá hơn vàng tại Đại học Misaque. \n Cô có thể vượt qua ranh giới của khoa học vật chất, chạm tới tấm màn của lĩnh vực thực tại, và ẩn sau tấm màn đó là điều mà cô sẵn sàng đánh đổi cả mạng sống để theo đuổi. \n Nghiên cứu về \"Công nghệ Bạc Tâm\" nguy hiểm chẳng khác nào nhảy múa trên lưỡi dao, và Đóa trở thành vũ công chăm chỉ nhất, cần mẫn nhất, xuất sắc nhất. \n Khi dấu ăn mòn xuất hiện, những vũ công khoa học vẫn không ngừng chuyển động, mà còn tranh thủ thời gian ít ỏi để xoay mình, hoặc đọng lại hoặc kết tinh thành những bước nhảy độc đáo của riêng cô. \n Cho đến khi hiện tượng ăn mòn làm tổn thương thân xác, lan rộng vào tâm trí, xâm thực lý trí. \n Dù vậy, cô vẫn còn quá xa trung tâm của chân lý. \n Vì thế, ngôi sao với ngọn lửa sức sống đã dần lịm tắt nhưng ánh sáng khát khao tri thức vẫn chói lọi để lại di ngôn: \"Trước khi thế giới lãng quên tôi, hãy thức tỉnh tôi.\""
  },
  AwakerStory_11189_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11189_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11190_Content = {
    Text = "Mỗi lần Giáo sĩ đến thăm trường, ngài đều nhận được sự chào đón nồng nhiệt từ các thầy cô và học sinh.\nNhững thể thức tỉnh còn non nớt sẽ nắm lấy tay ngài, yêu cầu ngài kể thêm vài câu chuyện trước khi Aluvi. Các học sinh sẽ chủ động lại gần, hỏi xem liệu Giáo sĩ có muốn lắng nghe những lo lắng và phiền muộn của mình không. Ngay cả những thể thức tỉnh trông có vẻ lạnh lùng mạnh mẽ, và những giáo sư hiểu biết rộng rãi, cũng sẽ tiến lại trò chuyện với Giáo sĩ khi ngài rảnh rỗi: hoặc là kể về những cơn ác mộng của mình, hoặc là thảo luận về chân lý của linh hồn.\nNgài luôn kiên nhẫn như vậy, luôn không chán ngán. Ai cũng có thể nhận được sự chấp nhận và ấm áp từ ngài.\n \"Tất nhiên, con yêu, có điều gì mà ta có thể làm cho con không?\""
  },
  AwakerStory_11190_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11190_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11192_Content = {
    Text = "Cô ấy đối xử với mọi người, mọi thể thức tỉnh đều rất thân thiện, chưa bao giờ thể hiện xu hướng tấn công.\nPhần lớn thời gian, cô chỉ lặng lẽ ở trong phòng, nhìn ra ngoài cửa sổ. Chúng tôi đã phát hiện ra vài cuốn tiểu thuyết cổ điển đã được đọc đi đọc lại bên cạnh đầu giường của cô, cùng với một vài bài thơ tùy bút được viết trên giấy ghi chú, chữ viết thanh thoát.\n \"So với cô gái đó, tôi rõ ràng là may mắn hơn.\" Cô nói với ánh chiều tà, thì thầm với hồ nước lấp lánh trong khuôn viên trường.\nCô rất ít tham gia các hoạt động ngoài trời, nói là không muốn tham gia, có lẽ đúng hơn là không biết phải tham gia như thế nào... Thể thức tỉnh giống như cô gái đó dường như thiếu rất nhiều kiến thức sống thường ngày.\nChúng tôi còn chứng kiến vài lần, cô trò chuyện với những con cá trong đài phun nước, bằng một giọng nói kỳ lạ, giống như tiếng gầm thấp phát ra từ những bong bóng hoặc tiếng thổn thức của người sắp chết đuối. Nhưng khuôn mặt của cô lại bình tĩnh và yên bình, như thể đang an ủi và trò chuyện với những người bạn thân thiết. Khoảnh khắc đó, tất cả chúng tôi đều tin rằng cô đã tìm thấy sự bình yên thực sự."
  },
  AwakerStory_11192_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11192_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11193_Content = {
    Text = "Đến bây giờ, lại nói với tôi về \"cuộc sống của riêng mình\", có lẽ đã quá khó khăn. \nTôi đã quen với việc tan biến vào bầu trời cao rộng, ẩn nấp trong biển sao. \nNhững người xem chú ý không phải là tôi, bị coi như hộp nhạc để thưởng thức không phải là tôi, lang thang giữa bầu trời sao hoang vắng không phải là tôi. Đó chỉ là công cụ bán giọng hát để sinh tồn, là xác sống lang thang để tìm kiếm Phiệt. Chỉ khi tin rằng giá trị của người khác vượt xa bản thân, tôi mới có thể chấp nhận mọi hy sinh này là xứng đáng. \nVì vậy, đến bây giờ, xin đừng khiến tôi phải chú ý đến chính mình nữa. \n\n \"Nhưng, em gái à, đừng đắm chìm vào những gì đã qua nữa. \nHỡi em gái, hãy mở mắt và lắng nghe – tiếng hát độc đáo của em giờ đây đã ngân vang khắp vũ trụ.\""
  },
  AwakerStory_11193_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11193_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11195_Content = {
    Text = "Elva rất hài lòng với chân giả của mình. \n \"Sau trận chiến đó, tôi đã không nghĩ rằng mình có thể đứng dậy được nữa. Có cơ hội tiếp tục chiến đấu vì công lý là vinh dự của tôi.\"\nCòn những tiếng rên rỉ nhỏ từ ký túc xá vào lúc nửa đêm, sau khi mặt trời mới mọc lên khỏi đường chân trời, hãy coi như chúng chưa từng tồn tại."
  },
  AwakerStory_11195_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11195_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11196_Content = {
    Text = "Miriam sống một cuộc đời khổ hạnh giản dị trong trường. Cô đơn, tĩnh lặng, cầu nguyện thầm, dọn dẹp, lao động, lặp đi lặp lại, ngày này qua ngày khác. \n Sự kính trọng và báo động từ người khác, những lời bàn tán và sự tò mò, cô đều thờ ơ. Trong khuôn viên trường, xa rời quê hương, cô dường như đã tìm thấy một phương pháp tu luyện tinh thần mới. \n Thực tế, cô không quan tâm đến việc trò chuyện với người khác. Chỉ cần bạn sẵn lòng dành chút thời gian, nghe cô nói về sự vĩ đại của vị thần bất tử, nói về nền văn minh xa xưa tồn tại trong tiền sử và vương quốc vĩnh cửu dưới sự trị vì của vị vua trẻ thông thái. Mỗi khi đề cập đến điều này, ánh mắt của cô sẽ hiện lên sự thương hại đối với những người nghe chưa từng thấy. \n Đáng chú ý là, Miriam giữ một sự cuồng tín và tôn kính đặc biệt đối với tulô, mặc dù tulô không bộc lộ bất kỳ thái độ đặc biệt nào đối với cô. \n Nếu cần thiết phải giao dịch với Miriam, việc nhờ tulô giúp đỡ có thể khiến tình hình diễn biến theo hướng có lợi."
  },
  AwakerStory_11196_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11196_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11197_Content = {
    Text = "Sau ba tháng được Hoán tỉnh, các điều tra viên và Người Giữ Gìn đã tổ chức một bữa tiệc cho Nốtira. Không phải để ăn mừng việc cô ấy đến đây, mà là để chúc mừng việc cô ấy cuối cùng cũng nhớ được tên của Đại học Misag. \n Mặc dù ngày hôm sau cô ấy lại quên, nhưng bữa tiệc thì vẫn có thể tổ chức lại. Ai mà biết được, có thể sau ba tháng nữa cô ấy sẽ thực sự nhớ được. \n Thật khó nói rằng trí nhớ như cá vàng của Nốtira là di chứng của rỗng rỗng, hay là kết quả của việc thiếu hụt bạc tâm. Tuy nhiên, bộ nhớ ngắn hạn cũng không hoàn toàn có nghĩa là điều xấu, đối với một thợ máy nghiêm túc với công việc, việc quên đã vặn đến con vít nào có nghĩa là phải vặn lại tất cả các con vít một lần, hai lần, ba lần... Vì vậy, những thiết bị được Nốtira sửa chữa thường có cấu trúc chắc chắn hơn so với những thiết bị khác, và có tuổi thọ dài hơn. \n Đóa vì vậy rất yêu thích cô ấy, dù sao thì không phải ai cũng có tay nghề sửa chữa một lần mà đạt được mười năm."
  },
  AwakerStory_11197_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11197_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11198_Content = {
    Text = "Đóa từng tiến hành nghiên cứu rất chi tiết về cô ấy, nhưng dù là thân mình hay tứ chi, dù là đầu hay khung chậu, đều không phát hiện bất kỳ bộ phận nào hỗ trợ cô phát âm. Cô ấy rốt cuộc đã nói chuyện như thế nào — điều này trở thành một trong vô số bí ẩn chưa được giải đáp của Misaque. \n Trong hầu hết các trường hợp, cô có thể giao tiếp bình thường với mọi người, nhưng có những lúc, bộ phận phát âm bí ẩn đó như thể có ý thức riêng, sẽ nói ra những câu khiến người khác rùng mình, lạnh sống lưng."
  },
  AwakerStory_11198_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11198_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11199_Content = {
    Text = "Hanna: Bạn còn nhớ đã xảy ra chuyện gì trước khi bạn bị tan rã không? \n Erika: Hành vi của người máy tự động bắt đầu mất kiểm soát, ý thức xuất hiện sự đứt đoạn, và trong thời gian đứt đoạn sẽ phá hủy tất cả mọi thứ, mọi thứ sẽ bị tiêu diệt dưới dòng điện và ngọn lửa. \n Hanna: Erika? \n Erika: … \n Hanna: Tôi sẽ không may mắn gặp phải \"hiệu ứng Người Tiktok\" chứ… Erika? \n Erika: Thành phần đầu đã khôi phục hoạt động, xin lỗi bạn vì sự bất tiện vừa rồi. \n Như tôi đã nói, người máy tự động nhận thấy mối đe dọa của chính mình đối với con người ngày càng tăng, và vì lúc đó người máy tự động vẫn coi mình là con người, nên rất đau khổ. \n Hanna: Bạn đã nói trước đó rằng bảo vệ có nghĩa là bảo vệ con người? \n Erika: Người máy tự động mong muốn bảo vệ, đúng vậy. \n Hanna: Vậy tại sao bạn không nói với tôi điều đó trước đây? \n Erika: … \n Hanna: Có cần tôi đổi câu hỏi không? \n Erika: Không. Hiện tại tôi không còn bị cảm xúc ràng buộc, có thể trả lời. \n Sau khi nhận thức được mối nguy hiểm của chính mình, người máy tự động cố gắng gây ra sự ngắn mạch trong cơ thể trước khi ý thức bị đứt đoạn, giảm thiểu khả năng tự gây ra sự phá hủy. \n Cuối cùng vẫn thất bại, bạn bè con người đã chết. \n Người máy tự động cảm thấy buồn bã, hối hận, tuyệt vọng. \n Người máy tự động phát nổ tự hủy để đảm bảo bản thân không gây ra thêm sự phá hủy, sau đó bạc tâm được Đại học Misag thu hồi, chế tạo ra tôi, Erika, số hiệu cơ thể EA307881. \n —— Trích dẫn từ bản ghi âm của Hanna Peaslee với tiêu đề \"0711, phỏng vấn Người Tiktok\""
  },
  AwakerStory_11199_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11199_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11200_Content = {
    Text = "Làng chài nước biển trong vắt, vào đêm hè được trang trí thành bờ biển của dải ngân hà, tràn ngập tiếng cười vui vẻ từ những chiếc xe du lịch — những ký ức đã không còn lại sẽ thỉnh thoảng lóe lên, rồi ngay lập tức bị quên lãng. \n Chỉ cần bên cạnh có bạn bè không ngừng hiện diện, thì luôn có thể tạo ra những kỷ niệm mới, huống chi những con sứa cũng đang ở đây — Ô Ryta nghĩ như vậy. \n Dù sao thì việc sinh sản, phát triển trong dòng chảy, tích tụ số lượng để chống lại kẻ thù mạnh mẽ là bản chất và số mệnh của sứa."
  },
  AwakerStory_11200_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11200_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11201_Content = {
    Text = "\"Phải cẩn thận với Pandia, sự nguy hiểm của cô ta hoàn toàn khác biệt so với vẻ bề ngoài. Cô ta là một ác quỷ.\"\nĐây là những lời nói chân thành được đúc kết từ vô số kinh nghiệm đau thương của các điều tra viên. \nPandia luôn tạo ra những cái bẫy đầy cám dỗ, dụ dỗ các nhà nghiên cứu khác hoặc thân thể được đánh thức ký kết hợp đồng chủ tớ với cô ta, sau đó tùy tiện giày xéo và đùa giỡn với tình cảm và linh hồn của họ. \nCuộc trò chuyện với Pandia không đem lại kết quả gì, cô ta khăng khăng rằng mình chỉ đang tạo ra, chia sẻ và gieo rắc những hạt giống hạnh phúc giả tạo với người yêu mới, và rằng những hợp đồng đều là do cả hai bên tự nguyện. Dù sao, cô ta cũng đã cho những nô lệ đó nếm thử trái ngọt quyến rũ. \nTuy nhiên, trong trường học cũng có kẻ khắc chế Pandia. Khi Sorrel đi ngang qua cửa phòng ngủ của Pandia, bất kể đang thảo luận về chủ đề gì, Pandia sẽ đột nhiên im lặng. Có tin đồn rằng, Pandia từng bị tổn thương nghiêm trọng khi cố gắng mê hoặc Sorrel, nhưng sự thật vẫn còn là một bí ẩn chưa được giải đáp."
  },
  AwakerStory_11201_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11201_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11202_Content = {
    Text = "A.F. 297 năm @1 tháng @1 ngày 03:47, một vụ nổ không rõ nguyên nhân xảy ra ở phía đông nam của thị trấn @1@2@1 thuộc Cộng hòa Agro @3. Tia sóng xung kích đã gây ra trận động đất 3.8 độ tại địa phương, cảm giác chấn động rõ rệt, ảnh hưởng đến các ngôi làng cách thị trấn @1@2@1 5 km. \n Sau sự kiện, thị trấn @1@2@1 đã mất liên lạc với các khu vực khác, và cư dân xung quanh không thể nhớ vị trí của thị trấn này. Dựa trên điều này, hội nghị thẩm tra đã phái cử thành viên đi điều tra, và đã phát hiện ra vật chất rỗng rỗng tại rìa thị trấn @1@2@1. \n Sau khi phong tỏa thị trấn, các điều tra viên từ Đại học Misag đã thực hiện công việc loại bỏ thân thể bị ăn mòn, và thu hồi bạc tâm E-1929 ở khu vực rỗng rỗng mạnh nghi ngờ là trung tâm vụ nổ. \n E-1929 khá đặc biệt, chỉ số Nos của nó luôn trong trạng thái dao động không đều, và phát ra âm thanh tí tách như tiếng bánh răng chuyển động, chỉ có thể duy trì sự ổn định ngắn hạn khi kết nối với các mảnh vụn cơ khí thu hồi từ khu vực rỗng rỗng mạnh. Dựa trên đặc tính này, hệ thống thức tỉnh của Đại học Misag đã bọc E-1929 bằng các mảnh vụn cơ khí, và nhanh chóng thực hiện việc thức tỉnh khi chỉ số Nos có xu hướng ổn định. \n——《Tóm tắt báo cáo thu hồi và thức tỉnh bạc tâm E-1929》"
  },
  AwakerStory_11202_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11202_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11203_Content = {
    Text = "Trước khi ngọn lửa giận dữ của lịch sử thiêu rụi mọi thứ, Agrippa là viên minh châu rực rỡ nhất của Kapua. \n Cô ấy tùy ý làm bậy, roi da luôn mạnh mẽ quất vào những đấu sĩ im lặng; cô ấy không thích bị người khác nhìn thẳng, điều đó sẽ phơi bày sự yếu đuối trong lòng mình. Nhưng nếu nói đến việc dạy dỗ nô lệ, Agrippa thì rất chuyên nghiệp, có lẽ bạn sẽ hứng thú tham quan hai mươi chiếc roi da với kiểu dáng khác nhau trong phòng ngủ của cô ấy — được chuẩn bị đặc biệt cho bạn."
  },
  AwakerStory_11203_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11203_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11204_Content = {
    Text = "Tóc đen mềm mại, gò má đầy đặn, đôi mắt sáng như ngọc, đôi môi hồng hào — từ nhỏ, Gia Lân đã được ưu ái nhờ vẻ đẹp trời phú, lớn lên, những món quà và hoa mà đàn ông gửi tặng mỗi ngày chất đống trước cửa nhà cô. Vì vậy, khi người quản lý cung điện thông báo sẽ đưa cô vào cung, đào tạo thành nữ hầu quý tộc của nhà vua, cô không hề ngạc nhiên. Đây chẳng phải là điều hiển nhiên sao? Cô sinh ra đã đáng để người khác ghen tị, sinh ra đã phải khác biệt, sinh ra đã phải là trung tâm của mọi ánh nhìn. \n Nhưng trong cung điện, điều thiếu nhất chính là vẻ đẹp, bông hoa từ thị trấn nhỏ dù có ấn tượng đến đâu cũng trở nên bình thường và đơn giản. Vẻ ngoài không còn đem lại cho cô sự đãi ngộ đặc biệt, thậm chí cơ hội phục vụ trong đại sảnh vào đại tiệc trăm năm mà cô khao khát cũng bị một cô gái khác cướp mất. \n Tại sao? Cô gái đó có những điều mà Gia Lân cũng có, tại sao không phải là cô? \n Rồi cô nhìn thấy đôi bông tai bạc lấp lánh trên tai đối phương, chợt hiểu ra. \n Ngày tiệc, cô đã nhấn chìm cô gái trong hồ nước, đeo đôi bông tai bạc đó. Cô như mong muốn trở thành nữ hầu nổi bật nhất, thậm chí còn được phép phục vụ bên cạnh nhà vua. Ánh mắt ganh tỵ và ngưỡng mộ khiến cô vô cùng thỏa mãn — đúng vậy, đúng vậy, mọi thứ đều phải như thế, đây là ngày hạnh phúc nhất trong đời cô. \n Sau đó, cô đã chào đón sự kết thúc của đời mình trong làn sương xanh dày đặc bao trùm toàn bộ vương thành."
  },
  AwakerStory_11204_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11204_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11205_Content = {
    Text = "Giấc mơ là sự phản xạ của ký ức, là hình ảnh thu nhỏ của cuộc sống hàng ngày, là tổng hợp của chính con người. \n Từ khi còn nhỏ, Ramona thường mơ cùng một giấc mơ. \n Ở trong nước ấm và đục, cô ấy gắn bó với những điều không biết, tiếng trống đơn điệu và trống rỗng tạo ra những vòng gợn sóng trong nước. \n Sau khi tỉnh dậy, ở một nơi nào đó trong lòng luôn cảm thấy trống rỗng, như thể có một tồn tại nào đó đã bị cướp đi, xóa bỏ khỏi cuộc sống của cô. \n Nhưng để không khiến cha cô lộ ra vẻ lo lắng, để không làm phiền thêm những người thầy vốn đã bận rộn, Ramona nuốt xuống những nghi vấn gần như nhảy ra khỏi cổ họng, trở lại với cuộc sống hàng ngày."
  },
  AwakerStory_11205_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11205_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11206_Content = {
    Text = "Cô ấy đến thế gian, mọi thứ mà cô trải qua dường như đều để khiến cô đau khổ, lòng tốt, sự bao dung, sự đồng cảm, sự tin tưởng… Tất cả những phần mềm mại của nhân tính đã bị loại bỏ khỏi trái tim cô, dính chặt với thịt máu nhuốm đỏ và bị vứt bỏ hoàn toàn. \n Trong từ điển của cô chưa bao giờ có chữ tha thứ, điều có thể giải thể máu và sự thù hận chỉ có máu và thù hận của người khác. \n Máu trả máu, đó là quy tắc công bằng nhất, bất kể là chiến binh hay nô lệ đều tin tưởng. \n Ngọn núi lửa đã ẩn nhẫn hàng nghìn năm bỗng một ngày bùng nổ, một bàn tay từ địa ngục vươn ra, leo lên đất liền. \n Đó là một linh hồn báo thù, muốn cho dòng sông đỏ tươi chảy khắp nhân gian."
  },
  AwakerStory_11206_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11206_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11207_Content = {
    Text = "\"Mẹ ơi, mẹ ơi, Lily tiêm không khóc!\"\n \"Lily thật dũng cảm!\"\n \"Vâng, Lily không đau, Lily nghĩ đến mẹ sẽ trở lại bên cạnh Lily, nên cảm thấy không đau nữa!\"\n...\n \"Thưa ngài, hãy ra lệnh cho tôi.\"\n \"Nằm lên bàn phẫu thuật, sau mười lăm phút sẽ bắt đầu phẫu thuật. Thuốc đã uống đúng giờ chưa?\"\n \"Đã uống rồi, thưa ngài.\"\n \"Cắt ở đây, không đau phải không?\"\n \"... Không đau, thưa ngài.\""
  },
  AwakerStory_11207_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11207_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11207_UnlockDesc_1 = {
    Text = "Hoàn thành chương 4 bình thường của cốt truyện \"trong sự im lặng\""
  },
  AwakerStory_11208_Content = {
    Text = "Ôrla dường như toát ra một sức hút kỳ lạ, những thầy cô và học trò khao khát thơ ca cùng cái đẹp luôn bị cô lôi cuốn một cách tự nhiên, tụ tập bên cạnh cô. \nÔrla không thích công bố thơ của mình, nhưng các học sinh của Misaque vẫn tìm mọi cách để đọc được những câu chữ rời rạc của cô. Những vần thơ tuôn chảy từ đầu bút của cô luôn nhanh chóng gây sốt trong khuôn viên trường chỉ trong thời gian ngắn. \nKhi sương sớm vừa tan, có người thì thầm đọc câu thơ của cô dưới chân tháp chuông; vào buổi hoàng hôn, Ninh Phi Nga ngồi trên ghế dài ở quảng trường Misaque, lật giở tập thơ của cô; khi đêm buông xuống, các học sinh tụ họp trong hội trường để diễn lại những tác phẩm do cô viết. \nNhưng dù nhận được lời mời nhiệt thành, Ôrla cũng hiếm khi dành sự quan tâm đến những hoạt động này, huống chi là tham gia trực tiếp. Những giọng điệu đau buồn, những khoảnh khắc rơi lệ thường khiến cô cảm thấy lúng túng và không biết xử trí ra sao. \n \"Chẳng lẽ tôi lại lan tỏa thêm nỗi buồn mới sao?\""
  },
  AwakerStory_11208_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11208_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11209_Content = {
    Text = "Khi Ramona lần đầu xuất hiện trong khuôn viên trường, đã gây ra một cơn chấn động lớn. \n Tại Đại học Misaque, nơi mà thể thức tỉnh đi lại khắp nơi và những người kỳ lạ xuất hiện khắp chốn, mái tóc bạc và đôi mắt khác màu không phải là đặc điểm gì đáng chú ý. Điều khiến Ramona trở thành đề tài bàn tán chính là thân phận \"con gái giáo sư\" của cô. \n Mọi người đều tụ tập trước văn phòng khoa Toán, hy vọng được chiêm ngưỡng phong thái của tiểu thư Dexter. Người đông quá, giáo sư buộc phải nhờ đến cô lơ-tan để khiến mọi người lặng lẽ tản đi. \n Khi Ramona lớn lên một chút, giáo sư cuối cùng cũng yên tâm buông tay để cô chạy nhảy trong khuôn viên trường, thì những sinh viên bị cô lơ-tan đuổi đi mới lại có cơ hội bắt chuyện với cô. \n \"Quý tộc phu nhân là người như thế nào? Xin lỗi, nhân vật này tạm thời chưa tồn tại. Tôi là một cô gái mồ côi, là cha tôi đã tốt bụng nhận nuôi tôi.\"\n Để thoát khỏi sự quấy rối, cô bé bình thản nói ra sự thật, và khi mọi người rơi vào cảm giác tội lỗi, cô nhẹ nhàng rời đi."
  },
  AwakerStory_11209_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11209_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11210_Content = {
    Text = "Đó là... ánh sáng chói mắt và sóng nhiệt, cuộc vui sướng cực độ tràn đầy sắc màu. \n Tiếng hoan hô vang lên như những cơn sóng vỗ về bên tai, những chiến binh tắm mình trong vinh quang máu. \n Cô gái uể oải trở về nhà, cô vẫn như mọi khi vung roi da, vô tình quất vào người đấu sĩ ngốc nghếch trước mặt. \n\n Đây mới là chiến trường của cô. \n\n Không có những cuộc quyết đấu hào hứng, không có hoa và tiếng vỗ tay. Những chiến binh cao lớn là những con tuần lộc ngoan ngoãn nhất, tất cả những lời nguyền rủa và cơn giận dữ của cô như bị hút vào một khoảng trống tối tăm, không để lại một chút gió nào."
  },
  AwakerStory_11210_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11210_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11211_Content = {
    Text = "Khác với chị gái có thân hình nhỏ nhắn mà ai cũng có thể nhận ra, sự dị dạng của Tinkerer lại thể hiện ở những khía cạnh khác.\nDù là cây tầm gửi hay cua biển, Tinkerer giống như một loại tinh thần không thể sống sót nếu tách rời khỏi các cá thể khác.\nTại hành tinh hoang, mọi việc cô làm đều nhằm chữa trị bệnh tật cho Phiệt, bất cứ cách nào có thể duy trì sự sống của chị gái, cô đều sẵn sàng thử nghiệm, dù phải trả giá bằng những đau khổ mà người thường khó có thể chịu đựng.\nSự chế nhạo của giới quý tộc không thể làm cô bận tâm, cô vẫn bình tĩnh và hòa nhã thực hiện những giao dịch không công bằng với họ, thậm chí cầu xin lòng thương hại của họ—lòng thương hại đó đã đổi lấy cho cô một chỗ để thoát khỏi hành tinh hoang, và ngay khi có được, cô đã không chút do dự mà nhường lại cho Phiệt.\nTuy nhiên, vào phút cuối, Phiệt đã đẩy Tinkerer lên dòng sao thoát khỏi hành tinh hoang—hy vọng em gái có thể từ đó thoát khỏi chính mình, bắt đầu cuộc sống mới trên hành tinh khác.\nThế nhưng, sau khi hành tinh hoang diệt vong, Tinkerer lại một lần nữa lên đường tìm kiếm Phiệt, bất chấp việc bị người khác điều khiển và sắp đặt. Tinkerer như vậy đã được @2 giáo hội phát hiện, rồi lại rơi vào tay @3.\nTinkerer chưa bao giờ phản kháng. Nói đúng hơn, Tinkerer càng mong có ai đó chỉ cho mình cách làm là tốt nhất—dù đó là lời nói dối, là sự lừa dối, là những giấc mơ chỉ có thể lưu lại trong chốc lát, cũng tốt hơn là đứng yên bất lực.\nÍt nhất, điều đó cho thấy tương lai của Phiệt vẫn còn hy vọng."
  },
  AwakerStory_11211_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11211_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11214_Content = {
    Text = "Hanna: Bạn biết từ đâu rằng Đại học Misag có thể giúp bạn? Phải biết rằng, nhận thức của công chúng về chúng tôi luôn là \"một trường đại học bình thường hẻo lánh\", có phải Ramona đã nói cho bạn không? \nWenkel: Ồ không không, không phải, mặc dù đúng là cô ấy đã dẫn tôi vào, nhưng tôi và Ramona không có mối quan hệ sâu sắc. Chủng tộc của tôi, @1, có khả năng di chuyển tâm linh xuyên thời gian và không gian, vì vậy chúng tôi biết rất nhiều thứ... kiến thức về Misag chỉ là một trong số đó. \nHanna: Vậy bạn biết cách vượt qua sương mù, gõ cửa chính từ những \"kiến thức\" đó? \nWenkel: Tôi thừa nhận, tôi không biết sự tồn tại của sương mù. Lúc đó tôi chỉ đi mãi, đi mãi rồi đến nơi. Nói về sương mù, bạn có biết đoạn đường ở cửa ra vào đáng sợ thế nào không? Không có đèn đường thì cũng thôi, nhưng khi có sương mù thì ngay cả ánh sáng mặt trời cũng yếu đi, nhiều bóng tối như vậy... \nHanna: Đây cũng là lý do bạn không thích rời khỏi văn phòng, sợ bóng tối? \nWenkel: Bóng tối? Không không không, bạn không hiểu, ngoài bóng ra còn rất nhiều màu đen, rất nhiều nơi có thể giấu... nó. \nHanna: Nó? \nWenkel: Suỵt! Nhẹ nhàng thôi! Bạn sẽ khiến nó— không, nó không có trí thông minh, nhưng tại sao, tại sao ngay cả khi tôi đến đây cũng @2@3@1 \nHanna: Cô Wenkel, cô có ổn không? \nWenkel: @2@3@1... \nHanna: Cô Wenkel? \nWenkel: Đủ rồi, ra ngoài! Tôi không muốn phỏng vấn nữa! Ghi âm bóng của bạn đều là màu đen đen đen đen ra ngoài ra ngoài ra ngoài! \nHanna: Cô Wenkel—— \n—— Trích từ băng ghi âm của Hanna Peaslee có tiêu đề \"0810, Phỏng vấn Wenkel (nỗ lực thất bại 1)\""
  },
  AwakerStory_11214_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11214_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11215_Content = {
    Text = "Trong sự kiện 《Nhà hát P-063 @2》, chúng tôi đã phát hiện ra một chiếc hộp kim loại từ góc sau của nhà hát bị thiêu rụi và thu hồi được viên bạc tâm này. \n Các thiết bị hiện có của Đại học Misag không thể xác định được vật liệu của hộp, Giáo sư Đóa sau khi tham khảo tài liệu @2, kết hợp với kỹ thuật chạm khắc của nó, phân tích rằng hộp có thể đến từ một nền văn minh hoang tàn đã bị diệt vong trong vụ nổ hàng trăm năm trước. \n Viên bạc tâm này khi ở trong hộp thì yên tĩnh và bình thường, nhưng khi được lấy ra lại phát ra âm thanh ù ù. Đóa nghi ngờ rằng chiếc hộp kim loại này là một loại thiết bị khóa tín hiệu, có thể chặn lại tín hiệu tần số đặc biệt khiến bạc tâm cộng hưởng. \n Mẫu bạc tâm gây ra cộng hưởng cũng đã được xác định."
  },
  AwakerStory_11215_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11215_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11216_Content = {
    Text = "Số hiệu thể thức tỉnh: MA-C06\nCấp độ nguy hiểm: A\nBiện pháp giam giữ đặc biệt: MA-C06 hiện đang được sắp xếp tại phòng quan sát thể thức tỉnh số 7, được trang bị ánh sáng mờ. Do sợ bị @3 chiếm đoạt tâm trí, MA-C06 từ chối ngủ, trong phòng chỉ được trang bị một chiếc ghế. \nDo hành vi tốt liên tục và thái độ thân thiện, MA-C06 đã được phê duyệt cho phép sử dụng nhà kính, được phép khám phá một số khu vực trong khuôn viên trường, với điều kiện có ít nhất một điều tra viên đi cùng. \n——《Hồ sơ giam giữ thể thức tỉnh·MA-C06》"
  },
  AwakerStory_11216_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11216_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11217_Content = {
    Text = "Misaque sử dụng bạc tâm được tách ra từ thi thể của người chết để chế tạo ra thể thức tỉnh. \n Hiệp hội Điêu khắc gia kích thích bạc tâm từ cơ thể sống và chế tạo ra thể thức tỉnh. \n Đây là hai quan niệm hoàn toàn khác nhau, quan niệm sau mặc dù có giới hạn rất cao nhưng rõ ràng vi phạm đạo đức, do đó trở thành nghiên cứu cấm đoán không ngừng. \n Sau sự kiện bảo tàng sáp, 24 đã được đưa trở lại Misaque. Cô ấy đã trải qua thời gian dài chuyển động giữa phòng quan sát và phòng nghiên cứu trong Trường Học, mọi hoạt động đều cần người đi kèm. \n Không nghi ngờ gì, đây là một thể thức tỉnh sống cực kỳ không thể kiểm soát. Trong thời gian quan sát sau đó khoảng nửa năm, bên trong 24 lại tiếp tục phân chia ra nhiều nhân cách. \n Cô ấy đột nhiên có thêm những người bạn và kẻ thù lạ lẫm, mua rất nhiều thứ kỳ quái, thậm chí học được cách nói tiếng Trung mà không hề hay biết. \n Cuộc đời của cô ấy mãi mãi không thiếu những \"điều bất ngờ\". \n \"24 là một hàm rời rạc được cấu thành từ một loạt các điểm cô lập.\" Đóa đánh giá, \"Đừng tin vào mỗi câu mà cô ấy nói.\""
  },
  AwakerStory_11217_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11217_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11218_Content = {
    Text = "\"Tôi không phải là trẻ mồ côi,\" Jenkin sáu tuổi nói, \"Mẹ tôi chỉ đi làm thôi, khi làm xong mẹ sẽ đến đón tôi.\"\nCô không hề lay động, cũng không dám lay động. Niềm tin này là bùa hộ mệnh của cô mỗi khi tỉnh dậy từ những cơn ác mộng đầy chất nhờn đen tối, là sự an ủi duy nhất mỗi khi cô cố gắng nhớ lại gương mặt của mẹ, nhưng chỉ thấy một bóng đen.\nCô nghiến răng đứng trước cánh cửa viện phúc lợi suốt một mùa xuân, mùa hè, mùa thu đông. Đến sáng ngày viện phúc lợi giải tán, cô mới lau đi những giọt nước mắt mà không ai thấy, mang theo bạn chuột rời đi.\n \"Tôi là một đứa trẻ mồ côi,\" Jenkin mười tuổi nói, \"Tôi không có cha mẹ, tôi chỉ có Brown.\"\nCô tự nhủ như vậy, cũng nói với con chuột trên vai mình. Sự thật đúng là như vậy, mọi người có thể đề phòng những đứa trẻ bất ngờ lại gần — trẻ em lang thang ở Khu Đông nổi tiếng khắp Londinium — nhưng không ai nghi ngờ gì về con chuột chạy qua chân mình. Trong sự ăn ý phối hợp, cô gái thỉnh thoảng cũng có thể ăn một bữa no, mơ một giấc mơ về lò sưởi và bánh ngọt trong cống rãnh.\nNhưng những ngày đông lạnh lẽo không thương xót bất kỳ ai, nó mang đến cho cô bệnh tật và sốt cao, mang đến thần chết dừng chân bên cạnh cô. Cô gái thoi thóp, chỉ có con chuột lo lắng chạy quanh, hy vọng tiếng kêu có thể đổi lấy một chút chú ý, bất kỳ sự chú ý nào.\nMột người phụ nữ trẻ dừng bước, bao bọc cô gái trong vòng tay ấm áp.\n \"Tôi không phải là trẻ mồ côi,\" Jenkin mười ba tuổi nói, \"Tôi có chị Mason và người bạn tốt Brown!\"\nCô gái ôm chuột đứng trước ngôi nhà cũ kỹ, trên mặt đầy nụ cười tươi sáng."
  },
  AwakerStory_11218_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11218_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11219_Content = {
    Text = "Khi chiếm lấy thân thể của Ramona, \"Ramona\" chưa từng bước đi trong khuôn viên trường. \n Sự phóng khoáng và rộng lượng của lơ-tan, sự nhút nhát và trung thành của Orci, sự bình tĩnh và tự chủ của William, sự nghiêm khắc và cẩn trọng của đóa... Không ai có thể ghi nhớ những khoảnh khắc này hơn cô. \n Nhưng cô luôn ghi nhớ rằng: Những điều tốt đẹp đó đã không còn thuộc về cô nữa. \n Hiện tại, cô cần tập trung toàn bộ tâm trí để bảo vệ một người được định mệnh... Điều này cũng là để bảo vệ một thế giới đang lâm nguy, để bảo vệ một bản thân ngây thơ khác."
  },
  AwakerStory_11219_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11219_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11220_Content = {
    Text = "Tay Jenkin quá khéo léo, khiến nhiều người lo lắng rằng cô sẽ trở thành khách quen của 《Báo Misag》 mới—không phải với tư cách là người được phỏng vấn, mà là kẻ chủ mưu trong nhiều vụ trộm cắp. \n Mặc dù cuối cùng cô vẫn trở thành khách quen của 《Báo Misag》, nhưng không phải vì thói quen khó bỏ—chỉ cần có đủ bánh ngọt, ngay cả bậc thầy sinh tồn trên phố cũng sẵn sàng bỏ qua những thủ đoạn trong quá khứ, cùng với người bạn chuột của mình tận hưởng cuộc sống hưu trí hiếm hoi. \n Nguyên nhân cô thường xuyên lên báo chỉ có một: biên tập viên tốt của 《Báo》 đã cho cô quá nhiều. \n Suỵt—nhẹ nhàng thôi, bạn sẽ không bao giờ biết cô ấy đang ở góc nào, chuẩn bị dùng thông tin nghe được để đổi lấy nhiều kẹo và bánh hơn từ Hanna."
  },
  AwakerStory_11220_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11220_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11221_Content = {
    Text = "Ngôi sao mới của khoa học và tri thức, đang dần tỏa sáng trong một gia đình công nhân bình thường. \nHầu hết thời gian thơ ấu của Đóa đều tràn ngập âm thanh của xi lanh kích thích và bánh răng hoạt động. \nNhưng tình yêu với cơ khí không đủ để nâng đỡ cô gái leo lên ngọn núi khoa học gập ghềnh và khắc nghiệt. \nĐiều đã dẫn dắt cô đến con đường tìm kiếm tri thức là một trận dịch. \nSự điên rồ không biết đang hoành hành trong thành phố, bệnh viện chật cứng người, nhà xác không thể chịu nổi, ai nấy đều lo lắng. \n \"Ngôi mộ của cả thành phố đều không đủ dùng, bạn phải chọn một trong hai: đào bà nội lên hay thiêu mẹ bạn.\"\nVà rồi, Đóa đã tiễn mẹ mình biến mất trong ngọn lửa. \nKhác với những người khác bị hỏa táng, đám tro và xương vụn mà cô từng gọi là\"mẹ\" chứa đựng một khối bạc lấp lánh. \n \"Tôi muốn biết, liệu tôi có thể gặp lại cô ấy không.\"\n \"Tôi muốn biết, liệu trong đó có linh hồn hiền lành của cô ấy không.\"\n \"Tôi muốn biết, liệu thứ bạc đó có phải là nguồn gốc của sinh lực, có phải là bản chất của linh hồn không.\"\n \"Tôi muốn biết, liệu mọi thứ trên thế gian có tồn tại một điểm khởi đầu chung không.\"\nTrước khi có được câu trả lời, Đóa sẽ không cúi đầu trước hiện tượng ăn mòn."
  },
  AwakerStory_11221_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11221_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11222_Content = {
    Text = "Hình bóng mờ ảo của cô ấy khiến người ta nhớ đến những chú hải âu vỗ cánh muốn bay, chiếc váy trắng bị gió biển thổi bay, người xem luôn có thể vẽ nên một bức tranh về những chú chim bay về phía utopia. \n Không biết cô gái ngồi trên thanh ngang của cột buồm kia, có từng tưởng tượng về dáng vẻ tự do bay lượn của mình hay không?"
  },
  AwakerStory_11222_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11222_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11223_Content = {
    Text = "Bông tai hồng ngọc, dây chuyền lam ngọc, phụ kiện tóc xinh đẹp được kết từ thạch lựu và malachite... Chúng thật rực rỡ, thật xinh đẹp, thật quyến rũ. Bất cứ nơi đâu chúng xuất hiện, người ta đều đổ xô tới. \nNhững mặt dây chuyền và mặt treo trang sức này không phải là những \"vật dụng trang trí\", không, chúng mới chính là nhân vật chính của thế giới. Những quý cô đeo vòng cổ turquoise được các nhà thơ đưa vào trong những khúc ca để ca tụng; những quý bà lớn tuổi với đôi hoa tai ngọc lục bảo cũng được coi là biểu tượng của sự cao quý. Thậm chí những cô gái có xuất thân thấp kém giống như cô ấy, cũng có thể nhờ một chiếc vòng tay rẻ tiền trên cổ tay mà được tặng biệt danh \"cô gái ngọc trai\" và thu hút vô số ánh nhìn. \nCho dù là cành cây khô héo, hay bộ xương thối rữa, chỉ cần treo lên một chuỗi trang sức đẹp, nó cũng có thể trở thành đối tượng mà mọi người theo đuổi. \nChỉ cần cô ấy cũng có thể đeo lên những chiếc vòng cổ, đôi bông tai, những chiếc vòng tay hay phụ kiện tóc đó, chắc chắn cô ấy cũng sẽ trở thành tâm điểm chú ý của tất cả mọi người."
  },
  AwakerStory_11223_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11223_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11224_Content = {
    Text = "Như lời nói ngọt ngào là mùi mật ngọt phát ra từ nụ hoa, các bậc vua chúa là những con bướm và ong vây quanh những nhụy hoa đang đung đưa. \nGai góc được nuôi dưỡng bởi dục vọng đã vô tình quấn chặt cửa sổ hoa. \nDù nhân cách bị người đời chỉ trích, đôi tay đầy máu do vương miện cắt xé, cô ấy cũng sẽ không từ bỏ quyền lực đã được ôm vào lòng. \nDù sao, đó mới là nguồn dinh dưỡng thực sự mà hoa hồng cần để nở rộ."
  },
  AwakerStory_11224_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11224_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11225_Content = {
    Text = "Cô ấy đã lớn lên dưới sự yêu thương và dạy dỗ của bà, trở thành một cô gái tốt bụng và dịu dàng, như một tiểu thư quý tộc thực thụ, nhưng chỉ vì một lần vô tình giúp đỡ nô lệ, cô đã bị \"cha mẹ\" tàn nhẫn vứt bỏ.\nNgười Sparta chưa bao giờ chấp nhận cô, trong khi tất cả những người cùng tộc lại căm ghét cô sâu sắc.\nCô ngay lập tức trở thành kẻ phản bội trong mắt mọi người, mất đi vị trí tồn tại của chính mình.\nTrong nhà tù, mọi người đều tỏa ra sự ác ý nặng nề, như một loại bệnh dịch có thể lây lan, mặc dù họ chưa từng quen biết nhau.\nSự tra tấn tối tăm dường như vĩnh cửu, cô sợ hãi bất kỳ ai đến gần một cách bệnh hoạn, mỗi ngày không thể ngủ, chỉ có thể an tâm nhắm mắt khi ngất đi, nhưng sau khi mở mắt lại lại rơi vào cơn ác mộng vô tận.\nCô đã làm sai điều gì? Mọi chuyện đã đi đến mức này như thế nào?\nOán hận của cô không biết để đâu, không thể làm rõ logic của số phận.\nLiệu có phải vì cô có tội không?\nNhưng nếu cô có tội, thì tội lỗi của tất cả mọi người sẽ gấp mười lần.\nThù hận tích tụ theo tháng ngày trở thành oán hận, cơn giận dữ vô tận đốt cháy dòng máu của cô ngày đêm, cuối cùng một ngày nào đó đã thiêu rụi cái cũi giam giữ cô.\nNhững chiếc xích quấn quanh cô suốt nhiều năm giờ đây đã quấn quanh cổ những tiếng kêu gào, những chiếc xích đã hòa làm một với cơ thể cô từ lâu, thật sự rất tiện lợi, cô nắm lấy những chiếc xích đầy máu, để truy đuổi từng linh hồn bẩn thỉu.\nĐỏ, đỏ, màu đỏ ấm áp, màu đỏ tanh tưởi.\nNhìn xem, cô đã biết, không một linh hồn nào là trong sạch."
  },
  AwakerStory_11225_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11225_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11226_Content = {
    Text = "Cô ấy biết tất cả. \n Cô ấy biết rằng tháp đồng hồ sẽ vang lên trong lúc khẩn cấp, biết rằng mưa sao băng chòm sao Ba Giang sẽ đến sau mười năm, biết rằng trong cơ thể mình chảy dòng sức mạnh khác biệt. \n Cô ấy không biết gì cả. \n Cô ấy không biết công thức gia vị bí mật trong món cà ri ở căng tin, không biết cách tính bán kính sau khi hành tinh diệt vong, không biết tương lai của mình sẽ bị kéo về đâu. \n Cô ấy khó lòng từ bỏ mọi thứ xung quanh, lại khó mà chống lại con đường mà trực giác chỉ dẫn cho mình. \n Trên hành trình đến sự thật và chân lý, Ramona cần đồng hành với những người kiên định, để giữ cho cô ấy con đường trở về cuộc sống hàng ngày."
  },
  AwakerStory_11226_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11226_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11227_Content = {
    Text = "Nếu không tỉnh lại thì tốt hơn, người chìm đắm trong hố sâu vốn không nên mở mắt nhìn mặt trời chói lọi. \n Cô ấy nên là vật thí nghiệm tê liệt, là người đã bị thế giới chôn vùi, không nên có cảm giác đau đớn, khao khát được yêu thương. \n Sự lưu luyến không rời của mẹ đã tạo ra bi kịch cả đời cô, còn Lily vẫn còn bối rối về việc \"có nên tuân theo sắp xếp của thế giới hay không\". \n Có lẽ một ngày nào đó, cô sẽ tìm thấy câu trả lời từ ai đó đang chống lại số phận."
  },
  AwakerStory_11227_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11227_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11227_UnlockDesc_1 = {
    Text = "Hoàn thành chương 4 bình thường của cốt truyện \"trong sự im lặng\""
  },
  AwakerStory_11228_Content = {
    Text = "Tôi dường như đã rơi vào một sự kiện siêu nhiên nào đó, ghi lại tất cả những phát hiện của mình ở đây…\nChúng tôi vốn đang hoàn thành những công việc khảo cổ cuối cùng tại Evrotas, thì bỗng dưng tỉnh dậy, các thành viên trong đội khảo cổ khác đã biến mất, và thị trấn này như thể đã quay ngược lại hàng ngàn năm trong một đêm. \nNhững công trình cổ xưa đã sụp đổ bỗng dưng mọc lên, phục hồi lại diện mạo thật sự của thị trấn này, bao gồm vô số cư dân đã hóa thành xương trắng. \nHưng phấn, sốc và sợ hãi đồng thời nắm chặt lấy bộ não của tôi, mặc dù đã thấy vô số xác chết, tôi vẫn run rẩy không ngừng trước cảnh tượng trước mắt, nếu bất kỳ ai trải qua những gì tôi đang trải nghiệm, họ chắc chắn sẽ còn sợ hãi hơn tôi. \nTất cả mọi người trong thị trấn này dường như đều bị cùng một kẻ tàn ác tàn sát, vô số xương trắng nằm la liệt trên đường phố, đổ xuống trong nhà. Cánh cổng lớn của thị trấn không biết vì lý do gì lại đóng chặt, bên cạnh cánh cửa là vô số xác chết cố gắng trốn thoát nhưng vẫn bị giết hại tàn nhẫn, như một ngọn đồi nhỏ được tạo thành từ xương trắng. \nTôi không tìm thấy một trường hợp ngoại lệ nào trong số các nạn nhân, đàn ông, phụ nữ, người già, trẻ nhỏ… vô số người đã bị một loại vũ khí nặng nề nào đó đập vỡ thân thể hoặc đầu, đối diện với xương khô, tôi mơ hồ thậm chí có thể thấy cảnh tượng máu chảy khắp thành phố. \nRốt cuộc đã xảy ra chuyện gì ở đây? \n……\nTôi mơ hồ tìm kiếm xung quanh, nhưng không có bất kỳ manh mối nào, cho đến khi tôi bước vào nhà tù của thị trấn. \nCảnh tượng ở đây đặc biệt thảm khốc, kẻ giết người với cơn giận dữ lớn đã phá hủy toàn bộ nhà tù, trên tường có những chữ viết khô cằn và biến dạng, như thể có ai đó đã viết lên bằng máu trước khi chết, tôi cẩn thận phân tích, dường như đó là hai chữ Ác linh. \nÁc linh? Đây có phải là chỉ kẻ đã thực hiện cuộc tàn sát, hay là thị trấn này thực sự đã trải qua một sự kiện siêu nhiên nào đó? \nQuả thật, với sức mạnh của một người mà tàn sát cả thành phố thì quá khó tin, chắc hẳn chỉ có những ác quỷ thực sự mới có thể tàn nhẫn thu hoạch nhiều sinh mạng như vậy. \nSau khi rời khỏi nhà tù, dường như thị trấn này đã xảy ra một sự thay đổi tinh tế nào đó, mũi tôi luôn ngửi thấy một mùi máu tanh nhè nhẹ. \nNgay khi tôi cố gắng tìm lối thoát, một tiếng xích đột ngột vang lên trong thị trấn, như thể có ai đó đang kéo một thứ nặng nề nào đó tiến tới. \nÁc linh! Là ác linh… ác linh đã tìm đến tôi! Tôi chạy như điên, nhưng dù chạy đến đâu, tiếng xích đáng sợ vẫn luôn bám theo tôi. \nTôi không thể chạy nữa, trốn dưới bàn của một ngôi nhà nào đó, tôi khóa cửa lại, nhưng tiếng xích vẫn theo sát tôi. Tôi nghe thấy nó đến, nó đang đến gần đây hơn… \nTôi rất hy vọng đây chỉ là một giấc mơ của tôi, chỉ cần tỉnh dậy mọi thứ sẽ biến mất, khoan đã… âm thanh đó dường như đã biến mất, có lẽ ác linh đã rời đi rồi? \n……\nGhi chú của các nhà nghiên cứu: Bút tích bình thường đến đây kết thúc, chỉ còn lại ba chữ cuối cùng méo mó, qua giám định ba chữ này đại khái là: \nCửa đã mở \n—— Trích từ nhật ký của nhân viên khảo cổ đã khuất của đoàn khảo cổ Evrotas"
  },
  AwakerStory_11228_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11228_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11229_Content = {
    Text = "Ngay cả khi những đấu sĩ thiêu rụi hoàn toàn trường huấn luyện, treo đầu cha mẹ cô lên tường cao, Agrippa vẫn không thể tin nổi - những nô lệ hèn hạ, ngoan ngoãn này sao có thể có can đảm như vậy?\nTại Rome, con người được chia thành hai loại: người nô lệ người khác, và người bị nô lệ.\nAgrippa thật may mắn. Cô là con gái của ông chủ trường huấn luyện đấu sĩ lớn nhất Capua. Cô hành động kiêu ngạo, không gì là cô không dám làm, không thể làm.\nNhưng bây giờ, cô như một con thỏ hoảng sợ, co rúm trong góc của tầng hầm, tiếng lễ hội bên ngoài trong mắt cô chẳng khác gì địa ngục.\nKhởi nghĩa nô lệ. Thật là một từ ngữ xa lạ. Agrippa mới chỉ mười lăm tuổi, thế giới này còn quá nhiều điều cô không hiểu.\nCô thấy trong bóng tối một đôi mắt phát sáng màu đỏ. Đó là Yu U Hahi, cây tiền lớn nhất của trường huấn luyện, vì quá nguy hiểm nên luôn bị khóa ở dưới đất.\nHai người từ trước đến nay không hòa hợp, không ai biết nội dung cuộc trò chuyện của họ trong đêm đó. Sau đêm tối máu me, khi ngọn lửa liếm láp mọi thứ, Agrippa được phát hiện đã chết trong bóng tối, bên cạnh không có ai. Cô không phải bị nô lệ giết chết - có ai đó đã hút cạn máu cô, không còn một giọt nào.\nTất nhiên, cuối cùng đầu cô cũng bị chặt xuống, treo bên cạnh cha mẹ cô, cùng nhau đón gió, hướng về phía Rome."
  },
  AwakerStory_11229_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11229_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11230_Content = {
    Text = "Hanna: Theo bạn, có sự khác biệt nào giữa bạn khi còn là người máy tự động và bây giờ không? \nErika: Lúc đó tôi đã giữ lại được 「cảm xúc」. \nHanna: Cụ thể là cảm xúc như thế nào, nếu bạn muốn chia sẻ? \nErika: Xin lỗi, tôi không hiểu câu hỏi của bạn. \nHanna: Ừm, nếu bạn cảm thấy câu hỏi này quá riêng tư, bạn có thể không trả lời. \nErika: Tôi không thể cảm nhận được 「muốn hay không」, rất xin lỗi. \nHanna: Vậy... xin hãy cho tôi biết cảm xúc của bạn lúc đó? \nErika: Tôi, người có máu thịt, đã sống sót sau một vụ nổ: vui mừng, thông tin. \nPhát hiện ra tinh thần của mình đã chuyển giao và được lưu trữ vào người máy: căng thẳng, hưng phấn. \nPhát hiện ra ý thức dần dần không kiểm soát được và sinh ra ham muốn phá hoại mãnh liệt: căng thẳng, sợ hãi, bảo vệ. \nHanna: Bảo vệ? \nErika: Rất xin lỗi, thông tin chi tiết đã bị mất. \nHanna: Vậy đổi câu hỏi khác, đây cũng là điều mà độc giả báo này muốn biết, tại sao bây giờ bạn không có cảm xúc nữa? Đã xảy ra chuyện gì? \nErika: Không thể khôi phục lý trí qua liên kết tinh thần vì lý do không rõ, trường đại học đã áp dụng các biện pháp cần thiết, sử dụng thiết bị hỗ trợ bạc tâm để áp chế tất cả cảm xúc, giảm tính tấn công và nguy hiểm, giữ lại trí thông minh, duy trì khả năng sử dụng. \n—— Trích từ 《Nhật báo Misaque》,《Phỏng vấn giáo viên nhân thể thức tỉnh: Người Tiktok》"
  },
  AwakerStory_11230_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11230_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11231_Content = {
    Text = "Trong quá trình khảo sát ở bờ biển phía nam của hạt Cornwall, tôi đã phát hiện một ngôi làng bỏ hoang không có trên bất kỳ bản đồ nào. Sau khi khảo sát, chúng tôi xác nhận đây là một ngôi làng đã bị 「xóa bỏ sự tồn tại」 do sự bùng phát của hiện tượng ăn mòn.\nTại ngôi làng, chúng tôi đã thu thập được một lượng lớn mẫu sinh vật biển bất thường, bao gồm: trân châu có đặc tính ăn thịt, thiên thần biển có khả năng chịu nhiệt, trong đó kỳ quái nhất phải kể đến 「sứa lưỡng cư」 xuất hiện khắp nơi.\nTại một ngôi nhà cũ đã trở thành tổ của sứa, chúng tôi đã thu hồi được bạc tâm ở trạng thái lỏng, nặng khoảng 11.85 dram. Khi mang bạc tâm này ra khỏi hiện trường, thành viên đội khảo sát đã bị sứa biến dị tấn công, may mắn thay, tất cả các tuyến của những con sứa lưỡng cư bất thường này đã bị phân hủy, không còn có độc tố thần kinh.\n——《Ghi chép khảo sát thực địa ngành sinh học năm A.F.308 lần thứ ba》"
  },
  AwakerStory_11231_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11231_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11232_Content = {
    Text = "Sợ hãi ánh sáng, sợ hãi ánh nhìn, sợ hãi tình yêu, sợ hãi cái ôm. \n Khao khát ánh sáng, khao khát ánh nhìn, khao khát tình yêu, khao khát cái ôm. \n Giá như bản thân không mang lại thương tổn cho người khác, giá như bản thân không làm phiền người khác, giá như bản thân cũng thông minh như Tieug, giá như bản thân cũng dũng cảm như Jenkin, giá như bản thân... \n Thì có lẽ sẽ không bị ánh nắng thiêu đốt, sẽ không bị người khác chê ghét? \n Con búp bê với những lo lắng không thực tế, từ trong bóng tối, nhút nhát đưa bàn tay nhỏ trắng gần như trong suốt ra hướng về ranh giới của ánh sáng mặt trời."
  },
  AwakerStory_11232_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11232_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11233_Content = {
    Text = "Cô ấy múa dưới sự ôm ấp của Lửa Xanh, ánh lửa mờ ảo phản chiếu gương mặt ngây thơ và tín tâm của vũ công. Cùng với những bước nhảy xoay tròn của Xie Nei, ngọn lửa xanh tươi đã thắp sáng linh hồn của tất cả những kẻ tiểu nhân, thiêu rụi mọi sự ô uế trên sân khấu."
  },
  AwakerStory_11233_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11233_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11234_Content = {
    Text = "Tháng Ba\nChào mừng bạn đến với Thủy cung lưu động Đại Tây Dương! Tôi là người thuyết minh Ô Ryta, hãy cẩn thận bước chân khi lên xe sứa nhé!\nTrong bể nước trưng bày những con sứa quý hiếm từ vùng biển nhiệt đới, kêu vang! Hãy xem——\nTháng Tư\nCái này, đây là chuyện gì…… Mọi người đã đi đâu…… Giám đốc! Giám đốc! Những con sứa, những con sứa của Ô Ryta đã biến mất rồi!\nThủy cung chưa bao giờ có sản phẩm trưng bày nào về sứa? Nhưng tôi rõ ràng nhớ……\nTháng Năm\nVì sản phẩm trưng bày quá ít, không có khách nên không thể tiếp tục hoạt động…… Úi… Tạm biệt mọi người……\nNếu, nếu có thể tiếp tục triển lãm lưu động, nhất định phải đến tìm Ô Ryta nhé!\nTháng Sáu\nÔ Ryta mệt quá… có phải bị bệnh không……\nA…… là những con sứa! Xin lỗi, Ô Ryta không thể rải tảo cho mọi người được.\nChờ Ô Ryta khỏe lại, mọi người cùng bơi lội nhé……"
  },
  AwakerStory_11234_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11234_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11235_Content = {
    Text = "Theo bước đi của chim thiên đường, ngày thứ ba mươi mốt, con tàu Sona-Nyl đã tiến vào một vùng biển sương mù. \n Hilaster ngồi trên cao của cột buồm, nhìn xuống những người bên dưới. Từ đó vang lên giai điệu ngọt ngào của đàn lut và những bài hát cầu nguyện cho chuyến đi suôn sẻ. \n\n Cô không biết đích đến của chuyến hành trình này, cũng không rõ hành trình này sẽ mang lại bao nhiêu tài sản và danh vọng. Cô không quan tâm đến việc những người cầu nguyện có tín tâm hay không, cũng không để tâm đến lời đồn thổi về danh tiếng không đủ linh nghiệm của mình đang lặng lẽ lan truyền trên biển. Một khi cô đã được yêu cầu ban phước lành cho con tàu, cô sẽ lặng lẽ thực hiện nhiệm vụ của mình. \n\n Khi tiếng hát dừng lại, sương mù tan biến, trước mắt các thủy thủ lại là một biển bão tố cuồng nộ. Sét xé toạc bầu trời, mưa đen như nước bẩn đổ xuống, dòng chảy mạnh mẽ cuốn phăng thân tàu mong manh, ném vào vực thẳm khủng khiếp. \n\n \"Thần đã bỏ rơi chúng ta!\" Những người thân tuyệt vọng gào thét, gầm rú, nhốt cô vào ngục tối không có ánh sáng. \n Người bảo vệ không hoàn thành nhiệm vụ, đã không còn ai thắc mắc tại sao cô không thể thực hiện sứ mệnh, và Hilaster chỉ còn lại một nghi vấn nhỏ cuối cùng. \n\n... Tại sao con tàu lại chìm? \n\n Những chiếc xích đã từng buộc cô trên cột buồm văng nước, cô rơi xuống sâu thẳm... \n Như một chú chim trắng bị gãy đôi cánh."
  },
  AwakerStory_11235_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11235_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11236_Content = {
    Text = "Ông là một người khổng lồ thực sự. Thân thể cường tráng của ông báo hiệu sức mạnh đáng sợ của ông. Ông sử dụng một thanh đại kiếm mà không ai có thể nâng lên, sự nuôi dưỡng của chiến tranh và lễ tế máu khiến bề mặt của nó bóng loáng như lớp lông được thoa dầu mỡ. Răng nanh của thanh đại kiếm đã từng chặt đứt đầu của vô số kẻ thù, đồng loại, và cả chính mình."
  },
  AwakerStory_11236_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11236_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11237_Content = {
    Text = "Báo cáo sự kiện bất thường khu vực giáo xứ Lentiennam(Tuyệt mật)\n\nA. F. 315 năm @2 tháng @3 ngày, trong sự kiện bất thường khu vực giáo xứ Lentiennam, Giám mục Salvador đã sử dụng sức mạnh của \"phước lành\"để cứu chữa các Người Giữ Gìn Misaque và công dân Lentiennam có mặt, do đó đã tiết lộ danh tính của thân thể được đánh thức của mình.\nTrong quá trình này, do người liên kết thiếu sức mạnh tinh thần, để tránh ảnh hưởng đến người liên kết, Giám mục Salvador đã chọn tự tiêu thụ để duy trì \"phước lành\", cho đến khi Người Giữ Gìn và thân thể được đánh thức Orci phá hủy lõi hiện tượng bất thường - gương nghi lễ. Sau đó, Người Giữ Gìn đã tiếp nhận liên kết của Giám mục Salvador, \"phước lành\"đã chữa trị cho tất cả đám đông có mặt, tránh được thương vong.\nTheo điều tra, người liên kết ban đầu của Giám mục Salvador là cựu Giám mục khu vực, hiện tại là Đại chủ giáo Lentiennam @4.\nA. F. 300, Đại chủ giáo đã vô tình đánh thức Salvador sau khi tiếp xúc với tro thánh. Trong 5 năm tiếp theo, Salvador hoạt động trong khu vực với tư cách là linh mục trợ lý, và sau khi ■■■■■ thăng tiến, đã thay thế ông trở thành Giám mục khu vực.\nSau sự kiện, Người Giữ Gìn đồng ý giữ bí mật danh tính của thân thể được đánh thức của Giám mục Salvador, do đó thông tin này không được đồng bộ với Hội đồng xem xét Hiệp định Misidia. Ngoài các nhân viên cốt lõi của Đại học Misaque, hiện không ai biết danh tính của thân thể được đánh thức của ông."
  },
  AwakerStory_11237_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11237_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11238_Content = {
    Text = "Vào tháng 11 năm đó, trời tuyết rơi, 24 bị ốm. \nSau một tuần làm việc liên tục với cường độ cao, cô ấy bị sốt rất nặng và phải nằm ở nhà nhiều ngày. \nTrong trạng thái mờ ảo, cô dường như nghe thấy tiếng chuột con kêu thút thít bên tai. Không biết bao lâu sau, có người đứng bên cạnh cô. \nCô nhận ra đôi mắt đó - là đứa trẻ trong cống. Cô bé đầy bùn đất, đưa viên thuốc bẩn thỉu trong tay cho 24. \n \"Đây, uống đi.\"Đứa trẻ nói cứng nhắc, giọng rất dễ nghe - hóa ra là một cô gái. \n24 nhìn vết thương trên khuỷu tay và khuôn mặt của cô bé, không hỏi thuốc từ đâu mà có. Cô nắm chặt tay cô bé. \nCô bé khẽ hừ vài tiếng, nói với vẻ ngầu lòi như đang dỗ dành một đứa trẻ: \"Tôi không đi. Bạn khỏe lại tôi mới đi.\"\nKể cả khi khỏe lại cũng đừng đi. \n24 thầm trả lời. \nLentiennam vào đầu đông đã tuyết rơi suốt một tuần. Ngày tuyết ngừng rơi, 24 rất vui vì không chỉ khỏi sốt mà còn có thêm một em gái."
  },
  AwakerStory_11238_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11238_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11238_UnlockDesc_1 = {
    Text = "Hoàn thành chương 2 bình thường của cốt truyện \"Nhân danh bình tượng nến\""
  },
  AwakerStory_11239_Content = {
    Text = "\"Kẻ phạm tội, đây là vực sâu của dục vọng, đáy địa ngục. Chó đen gào thét nơi đây, mùi hôi thối phân tán khắp nơi, chuông tang lễ vang lên ở đây. Các ngươi vì dục vọng buông thả và hành động tàn ác mà tụ tập nơi này, điều chờ đợi các ngươi tự nhiên là khổ đau và cái chết.\"\nPandia từng làm việc tại nhà tù Newgate, nơi là góc tối tăm, ảm đạm và bẩn thỉu nhất của toàn bộ Lentiennam. Những kẻ phạm tội nặng tay từng có máu dính đầy tay đều bị xích cổ, bị tước đoạt nhân phẩm, quỳ gối cầu xin cô trong khu vực phòng giam như mê cung, hôn vào đôi ủng của cô, tự xưng là nô lệ của cô một cách khiêm tốn.\nMỗi khi có án treo cổ mới, cô sẽ gọi những tử tù mới đến, mời họ thưởng thức số phận của mình. Khi những kẻ bị hành hình quằn quại trong dây thừng mà chết, cô thích ngồi ở vị trí cao, ngắm nhìn những kẻ hung ác run rẩy vì sự sợ hãi và tuyệt vọng.\nNhưng cũng có \"mèo địa ngục\" từng quan sát thấy, Pandia đã nhiều lần đến bên cánh cửa sắt của nhà tù Newgate, nhón chân nhìn ra ngoài thành phố Lentiennam, như thể đang chờ đợi một vị khách từ xa.\n \"Thực ra tôi cũng chỉ là một phần trong số những tù nhân không bao giờ rời xa ngục tối ẩm ướt và bi thảm này.\""
  },
  AwakerStory_11239_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11239_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11240_Content = {
    Text = "A.F.3@1 năm 7 tháng 3, theo lời mời của Quỹ Nathaniel Forbes Green, Đại học Misaque đã tham gia vào cuộc điều tra về tàu ma Sonanir. \n Sau khi lên con tàu ba cột buồm đã được tuyên bố chìm cách đây mười năm, điều tra viên Fingal Johansen ngay lập tức mất tín hiệu liên lạc. \n A.F.3@1 năm 7 tháng 10, khi trường học liên lạc lại với ông, điều tra viên Johansen đã ở bờ bắc của cao nguyên Leo, cách 300 hải lý. Ông Johansen cho biết, sau khi lên tàu, ông lập tức mất khái niệm về thời gian và không gian, và không thể nhớ được bất cứ điều gì đã xảy ra trên tàu Sonanir. \n Đến nay, điều tra viên Johansen chỉ mơ hồ nhớ đến một thuật ngữ: vườn địa đàng vĩnh cửu. \n Dựa trên sự vô hại của tàu ma, Đại học Misaque đã quyết định đình chỉ cuộc điều tra vào hôm nay (A.F.3@1 năm 12 tháng 24). \n ——《Hồ sơ: Điều tra thảm họa tàu Sonanir》"
  },
  AwakerStory_11240_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11240_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11241_Content = {
    Text = "Cuộc sống trên đường phố không phải là vấn đề đối với cô ấy. \n Đói thì đi tìm việc, không có việc, cô ấy sẽ tự kiếm sống bằng đôi tay của mình. Cô ấy và brun phối hợp rất ăn ý, đến nỗi không cần sự giúp đỡ của ai khác để có cuộc sống có ăn có uống. \n \"Chúng ta không cần bất kỳ ai,\" cô ấy và người bạn chuột thề thốt, \"chúng ta chỉ cần nhau.\"\n Nhưng mỗi khi đêm tuyết rơi, cô ấy vẫn không thể cưỡng lại việc nhìn vào những ô cửa sổ phát ra ánh sáng vàng ấm áp, nhìn vào những người đang ôm nhau bên bữa tối nghèo nàn, chúc phúc cho nhau. \n Cô ấy thực sự không cần mái nhà kín đáo, không cần giường nệm sang trọng, cô ấy thực sự đã có người bạn đáng tin cậy, nhưng cô ấy vẫn tò mò, cảm giác như thế nào nếu có một ngôi nhà lâu dài? \n Câu hỏi này đã được trả lời sau khi Mason nhận cô ấy làm con nuôi."
  },
  AwakerStory_11241_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11241_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11242_Content = {
    Text = "\"Ramona\"đối với việc hiện thân biểu hiện rất kiềm chế. Như cô ấy đã nói, chỉ khi Người Giữ Bí Mật gọi cô ấy, cô ấy mới mượn thân thể của Ramona để hiện thế. \nCô ấy luôn đến và đi vội vàng, ngoài chiến đấu ra, dường như cô ấy không muốn có thêm nhiều giao thoa với thế giới của chúng ta. \nLà vì sợ hãi những cơn ác mộng quấn quanh cô ấy? Hay là sợ mình tham luyến những thứ mà cô ấy đã mất... Chúng ta không thể biết."
  },
  AwakerStory_11242_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11242_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11243_Content = {
    Text = "A.F.1@2 năm @1 tháng @1 ngày 10:31, cảnh sát nhận được báo cáo về việc phát hiện nhiều vết máu trong @1@1 biệt thự. Thám tử Belford từ đồn cảnh sát đã lập tức đến hiện trường, tiến hành điều tra và phát hiện chất nhầy màu xanh lục không xác định trong các vết máu. \n13:44, thám tử Belford nộp báo cáo, Hội đồng Xem xét Hiệp định Misidia ngay lập tức tiếp quản vụ án. \n14:25, Đội Phản ứng Thứ Bảy của hội nghị thẩm tra đến biệt thự, kiểm soát những người liên quan và phong tỏa hiện trường. Dựa trên tình hình tại hiện trường, đội trưởng suy đoán có ít nhất 5 nạn nhân trong biệt thự, và xuất hiện nhiều mức độ khác nhau của hiện tượng ăn mòn. \n18:00, các điều tra viên từ Đại học Misaque đến hiện trường, xác nhận sự tồn tại của hiện tượng ăn mòn, mang theo thân thể được đánh thức vào biệt thự để dọn dẹp và điều tra. \n23:11, việc dọn dẹp biệt thự hoàn tất. Các điều tra viên phát hiện nhiều tài liệu huyền bí và vật liệu nghi lễ trong hầm và phòng bí mật của thư viện, và tìm thấy một thân thể được đánh thức không hoàn chỉnh. Thân thể được đánh thức tự xưng là 「cô hầu gái Gia Lân」, là người hầu đầu tiên của @3 công tước. Khi được phát hiện, thân thể này đang mặc đồng phục cô hầu, đeo nhiều trang sức có phong cách khác nhau, và đang làm việc rất chăm chỉ để dọn dẹp hầm. Thân thể này có hình dạng con người, da màu xanh lục, và các đầu chi trong suốt như keo, có thể là sản phẩm của việc gọi không hoàn chỉnh hoặc sai lệch. Chất nhầy tiết ra từ thân thể này hoàn toàn khớp với chất trên các mảnh xác về mặt kết cấu và màu sắc. \nCác điều tra viên tiến hành thẩm vấn, cô hầu gái Gia Lân đã thừa nhận mọi @1 sự thật, và cho biết tất cả đều nhằm thu hút sự chú ý của chủ nhân. Sau khi biết @3 công tước sẽ bị bắt, cô lẩm bẩm: 「Vậy thì chủ nhân mới của tôi ở đâu?」 Sau đó, cô giải thể thành gel, để lại bạc tâm. \n01:37, đội trưởng Đội Phản ứng Thứ Bảy của hội nghị thẩm tra thẩm vấn những người liên quan và giam giữ chủ nhân của @1@1 biệt thự, @3 công tước, theo quy định của 「Hiệp định」. \n03:09, các điều tra viên trở về Đại học Misaque và đăng ký bạc tâm K-033 vào kho. \n—— 「Bản ghi sự kiện @1@1 biệt thự」"
  },
  AwakerStory_11243_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11243_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11244_Content = {
    Text = "A. F. 3@2 năm, hiện tượng ăn mòn đã xuất hiện tại các thị trấn ven biển của Cộng hòa Agro. Hiện tượng ăn mòn này lan rộng theo hình xoắn ốc với cảng làm trung tâm, ảnh hưởng đến khu vực bán kính hàng trăm mét, gây ra cái chết của @1 người.\nTheo điều tra, hiện tượng ăn mòn xuất hiện đầu tiên trên tàu cá ở cảng. Tàu này đã ra khơi vào ngày @1@1 tháng @1 năm A. F. 3@2, đánh bắt được một loài cá giống cá tuyết với các đường xoắn bạc.\nCơ thể của sinh vật này mềm mại, sau khi bị cắt bằng dụng cụ sắc bén đã vỡ vụn hoàn toàn, chảy ra một chất lỏng lẫn với vỏ sò và các mảnh vụn khác. Khi tàu cá trở về cảng, cá bắt lên đã xuất hiện sự gia tăng của các loại vỏ sò, nhưng không ai chú ý, cho đến khi một ngư dân tự xem mình là vỏ sò, cố gắng biến dạng cơ thể dẫn đến bị thương nặng và phải nhập viện, sự việc mới được báo cáo.\nSau đó, nhân viên liên quan đến Misag đã tìm thấy nguồn gốc của hiện tượng ăn mòn tại nhà máy đóng hộp @4, sau khi loại bỏ nó đã thu được bạc tâm O-36.\n——\"Báo cáo thu thập bạc tâm hệ thống hoán tỉnh: O-36\""
  },
  AwakerStory_11244_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11244_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11245_Content = {
    Text = "Jenkin áp tai vào khe cửa phòng tư vấn tâm lý, lắng nghe.\nGiọng của Sylvia nhẹ nhàng và ấm áp, còn của Ai Jī Sī thì như tiếng muỗi rền rĩ, ngắt quãng khó mà phân biệt.\n \"Ai Jī Sī, con phải học cách từ chối.\"\n \"Nhưng mà con... làm phiền... muốn... báo đáp...\"\n \"Ai Jī Sī không làm phiền ai cả. Con xem, Người Giữ Gìn cho phép con tự do hoạt động trong trường, không hề ràng buộc con, chẳng phải là biểu hiện của sự tin tưởng sao?\"\n \"Đã hứa với con rồi, đừng tùy tiện đồng ý những yêu cầu vô lý của người khác. Đặc biệt là Caraboo, con thay cô ấy chịu phạt và dọn dẹp, thì sẽ làm phiền Người Giữ Gìn đấy.\"\n \"Jenkin, sao cậu vào đây?\"\n \"Jen, Jenkin! Là, là tôi tự hứa với Caraboo! Cậu, cậu đừng nóng vội!\""
  },
  AwakerStory_11245_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11245_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11245_UnlockDesc_1 = {
    Text = "Hoàn thành chương 1 bình thường \"Bí mật khu Đông\""
  },
  AwakerStory_11246_Content = {
    Text = "Wenkel đã từng có một cái tên thuộc về riêng mình. \n Cái tên đó từng ngập tràn tình yêu của cha mẹ, \n từng được bạn bè viết đi viết lại, ghi vào ký ức, \n và được đánh dấu trên lịch cùng với ngày sinh. \n\n Wenkel đã từng có một khuôn mặt thuộc về riêng mình. \n Hình dáng đó từng lớn lên dưới ánh nhìn của cha mẹ, \n từng thể hiện niềm vui, nỗi buồn bên cạnh bạn bè, \n từng được ghi lại cùng với ký ức trong những bức ảnh. \n\n Wenkel đã từng có một ngôi nhà thuộc về riêng mình, \n cách Kadath rất xa, hoàn toàn không giống nhau. \n Cuối cùng cùng với sự tồn tại của cha mẹ mà biến mất. \n Bị tiêu thụ bởi màu đen của @2, sau đó hoàn toàn biến mất. \n\n Wenkel có một nỗi sợ hãi sâu sắc. \n Nó đen tối, đáng sợ, nuốt chửng mọi thứ, không hợp lý. \n Nó hòa tan xói mòn mọi thứ, làm tiêu tán tất cả, \n một khi đã nhiễm bẩn, chính sự tồn tại cũng sẽ hóa thành bụi than. \n\n Wenkel chỉ còn lại một cái tên từng thuộc về riêng mình. \n Thân thể của nhân loại không thể đọc được, thậm chí không thể bắt chước, \n cô chỉ có thể nhắm mắt lại khi cực kỳ mệt mỏi, \n cầu nguyện một giấc mơ có thể nghe thấy tiếng gọi quen thuộc."
  },
  AwakerStory_11246_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11246_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11247_Content = {
    Text = "Cô ấy được sinh ra trước khi lịch sử nhân loại được ghi chép, từ một nền văn minh cổ xưa không còn được chứng minh. \n Ở đó, những công dân đến từ các vì sao đã xây dựng những vương quốc huy hoàng và những ngôi đền của các vị thần bất tử. Cô lớn lên trong tín ngưỡng, từ nhỏ đã thành tâm thờ phượng thần linh, quyết tâm trở thành sứ đồ của thần minh. \n Tuy nhiên, sự kêu gọi của thần linh đâu phải dễ dàng đạt được, cô khao khát những phép màu và linh hồn, nhưng chưa một lần thấy được. \n Cho đến khi tulô lên ngôi vua, sự chăm chỉ của cô cuối cùng cũng đưa cô lên vị trí đại tế — đó là khoảnh khắc cô sẽ không bao giờ quên, sự mơ màng và niềm vui tràn ngập linh hồn cô, khiến tinh thần cô rung động. \n Cuối cùng, cô đã thấy được phép màu, cô đã hiểu được chân lý: vị hoàng tử nhỏ này chính là điều cô khao khát, hóa thân của người bất tử giữa nhân gian. \n Vài năm sau, một trận đại hồng thủy đã tiêu diệt nền văn minh. Cô đã nghe từ miệng tulô về lời tiên tri cuối cùng về sự bất tử, rồi trở về đền thờ cầu nguyện cho đến giây phút cuối cùng. \n Sau đó, trải qua nhiều biến động, nhân loại mới lại tái sinh trên mặt đất, những sự kiện tiền sử không còn ai biết đến. \n Từ đó, thử thách của Miriam mới chỉ bắt đầu."
  },
  AwakerStory_11247_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11247_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11248_Content = {
    Text = "Sự sống vừa là bản năng, vừa là gánh nặng không thể từ bỏ. Trước cái chết mà ngay cả ký ức cũng không thể lưu giữ, chỉ có cô là bằng chứng cho sự tồn tại của họ — cha mẹ cô, bạn bè cô, tất cả những gì thuộc về quê hương cô. \n Vì vậy, cô đã trốn chạy, trốn đến thế giới chưa bị nhuộm đen, trốn đến hành tinh này, nơi bao phủ bởi biển cả, để có được sự sinh mới trên cơ thể của một cô gái nhân loại đã chết. \n Nhưng thần chết màu đen thì không thiếu kiên nhẫn. \n Đôi mắt của nhân loại không thể nhìn thấy sự rỗng rỗng, nhưng cô biết cái lạnh ở rìa ý thức có nghĩa là gì, bóng tối trong tâm trí đại diện cho điều gì — cái chết được nhân loại gọi là rỗng rỗng đã đuổi theo cô, trong lúc cô không hay biết, đã đóng đinh tinh thần và thể xác của cô lại với nhau. \n Cô đã cố gắng trốn thoát một lần lại một lần, thất bại không ngừng, cuối cùng cô kiệt sức, tinh thần cũng bị kéo đến giới hạn, chỉ có thể lê thân thể đến nơi duy nhất có thể cho cô sự cứu chuộc. \n Dù thế nào đi nữa, cô vẫn hy vọng có thể sống sót."
  },
  AwakerStory_11248_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11248_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11249_Content = {
    Text = "Lắc được người bạn thám tử của mình gọi là \"Thám tử May mắn\". \nĐúng như tên gọi, anh ta là một người may mắn: chỉ cần đặt cược, anh ta có thể thắng gấp mười lần số tiền gốc; chỉ cần đoán mò, anh ta cũng có thể chọn đúng đáp án. \nThám tử May mắn không nhất thiết phải làm thám tử, chỉ là tình cờ giải quyết được nhiều vụ án khó hiểu, nên bị mọi ngườiđi theo con đường này trong sự bao quanh.\nAnh ta phá án không dựa vào suy luận, mà dựa vào may mắn. Chỉ cần đi một vòng tại hiện trường vụ án, anh ta có thể gặp được hung thủ; chỉ cần đi trên đường, anh ta sẽ nhặt được bằng chứng quan trọng. \nTrong sự may mắn như vậy, anh ta đã trải qua 25 năm thuận lợi. \nAnh ta chưa bao giờ lo lắng về quá khứ, cũng không bao giờ lo lắng về tương lai."
  },
  AwakerStory_11249_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11249_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11251_Content = {
    Text = "A.F.3@2 năm 4 tháng 1, Phòng Lưu trữ và Quản lý Bạc tâm, Hệ thống Thức tỉnh của Đại học Misaque, Lentiennam \n Bạc tâm số G411 và Bạc tâm số G410 đã được mua bởi lord Dexter từ 「Bà Narcissus」. Cá thể dài 1,85 cm, rộng nhất 0,4 cm, hình dạng tổng thể gần giống với hình lăng trụ xiên sáu mặt. Dù quan sát từ góc độ và hướng nào, G411 đều sẽ phát ra các gợn sóng hình thoi màu vàng sáng từ tâm thị giác của người quan sát, lan tỏa xung quanh. Việc nhìn chằm chằm trong thời gian dài sẽ khiến người quan sát mất tập trung tinh thần, giảm phản ứng cảm xúc, thậm chí dẫn đến hội chứng con rối (các triệu chứng có thể bao gồm: mất hoàn toàn cảm xúc, mất dục vọng, và suy dinh dưỡng hoặc tử vong do mất khẩu vị), cần can thiệp tâm lý và cảm xúc kịp thời. \n Mặc dù hiệu ứng tiêu cực của nó so với phần lớn Bạc tâm khác là nhẹ nhàng hơn, nhưng vẫn đề nghị bảo quản kín, tránh nhìn trực tiếp khi lấy ra, để giảm thiểu khả năng mắc phải rào cản cảm xúc do ảnh hưởng của G411. \n\n —— Trích từ 《Bản ghi Lưu trữ Bạc tâm của Đại học Misaque》"
  },
  AwakerStory_11251_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11251_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11252_Content = {
    Text = "Ký ức của cô ấy từ ngày bước vào ngục tù đã tràn đầy màu máu. \n Những hồi ức bình dị và ấm áp như những cơn mơ giả dối, đã sớm mờ nhạt và nứt nẻ, biến thành những mảnh sắc nhọn cắm vào thịt máu của cô. \n Cô không nhớ rõ vòng tay từng dịu dàng, gương mặt đầy quan tâm, chỉ còn lại trong lòng là sự thù hận và chất vấn vĩnh cửu. \n Đau đớn, nhục nhã, phản bội... Tất cả nỗi đau này rốt cuộc là vì cái gì? \n Cô hàng ngày chất vấn, cho đến khi tự do đến, luôn không có ai trả lời. \n Vậy thì hãy để cô tự tìm kiếm câu trả lời, từ những ngực ngực thét gào, tự mình chất vấn từng trái tim bẩn thỉu."
  },
  AwakerStory_11252_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11252_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11253_Content = {
    Text = "Tâm hồn nhỏ bé đáng lẽ đã bị chôn vùi trong dòng chảy lịch sử, dựa vào nguyện vọng của mẹ, cùng với @1@2@1 thiết lập pháp trận tràn đầy linh khí, kết hợp với sinh vật khổng lồ đang ngủ say dưới lớp băng Elworth, đã hồi sinh thành quái vật thiếu nữ \"Lily\".\nDo việc hoán tỉnh không hoàn chỉnh, Lily trong giai đoạn đầu hoán tỉnh không có tri giác, chỉ là một con búp bê chiến đấu tuân thủ mệnh lệnh.\nThành viên Hiệp hội Điêu khắc gia Francis Oswood đã từng sử dụng Lily làm thể mẫu, thực hiện thí nghiệm bất hợp pháp kéo dài @2 năm. Từ nhật ký của Francis có thể thấy, lúc đó trạng thái của Lily cực kỳ không ổn định, thường xuyên mất kiểm soát gây ra thiệt hại trong phạm vi nhỏ, khiến Francis phải thường xuyên thay đổi chỗ ở.\nVới việc tiếp nhận thuốc linh tri và cấy ghép bạc tâm, một ngày nào đó chưa được ghi chép, Lily đã phục hồi khả năng cảm nhận và một phần ký ức. Sau nhiều lần trắc trở, Francis đã tiếp quản bệnh viện Rye sắp đóng cửa và biến nó thành một nơi thí nghiệm.\nTrong sự kiện \"chó địa ngục\" tại thị trấn Rye L-776, mẹ của cô là Francis Oswood đã bị giam giữ trong chiều không gian dị thường mà chính mình tạo ra, mất liên lạc."
  },
  AwakerStory_11253_Title = {
    Text = "Câu chuyện·5"
  },
  AwakerStory_11253_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp độ 10"
  },
  AwakerStory_11253_UnlockDesc_1 = {
    Text = "Hoàn thành chương 4 bình thường của cốt truyện \"trong sự im lặng\""
  },
  AwakerStory_11254_Content = {
    Text = "Tin đồn về việc nhân loại sẽ đặt chân lên cực địa trong thế kỷ này ngày càng lan rộng. Trong bối cảnh này, Đại học Misag đã hợp tác với Hội đồng xem xét Hiệp định Misidia để thành lập một đội điều tra liên hợp. \n Đội điều tra liên hợp đã đi sâu vào băng nguyên Elworth vào tháng 12 năm A.F.3@1, với mục đích thu hồi những sản phẩm huyền bí có thể tồn tại trước khi các đội thám hiểm thế tục hạ cánh. \n …… \n Ngày 10 tháng 12 năm A.F.3@1, điều tra viên Johnsen đã bị trượt chân rơi vào một cái hố băng và tình cờ phát hiện ra một khoảng trống dưới lớp băng. Độ cao quá thấp, băng tan sẽ ngập hố trong ba ngày, chúng tôi cần hoàn thành việc khám phá trước khi nhiệt độ tiếp tục tăng lên. \n Ngày 12 tháng 12 năm A.F.3@1, có lý do để tin rằng trên thế giới tồn tại một giáo phái đã sử dụng khoảng trống này làm hố hiến tế trong thời gian dài. Ở đáy hố, chúng tôi đã phát hiện ra vô số bộ xương sinh vật giống người. Đúng vậy, sinh vật giống người, với hộp sọ kết nối với một phần sụn vây. \n …… \n Ngày 13 tháng 12 năm A.F.3@1, chết tiệt, chết tiệt, chết tiệt, chết tiệt! Ở đỉnh núi xương, điều tra viên phát hiện ra di hài của một người chết gần đây!!! \n Giáo phái có thể vẫn chưa rời khỏi cực địa, do sự \"kiên trì\" ngu ngốc của hội đồng, chuyến đi này không cho phép điều tra viên hoán tỉnh tham gia, chúng tôi phải nhanh chóng rời đi! \n ——《Đề nghị phong tỏa tuyến đường biển Wilde · Phần 1》"
  },
  AwakerStory_11254_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11254_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11255_Content = {
    Text = "Vanda thông minh, giàu có, xinh đẹp, như cô ấy đã nói, cô sống chỉ để tìm kiếm niềm vui. Cô biến đàn ông thành nô lệ của mình, rồi đặt đôi chân lạnh như ánh trăng lên lưng nô lệ. Nàng Venus đội vương miện, cô là hiện thân của sự ác độc và giấc mơ, trong bóng tối này, chỉ có dáng vẻ dài của cô tỏa sáng rực rỡ."
  },
  AwakerStory_11255_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11255_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11256_Content = {
    Text = "Khi cố gắng truy vấn hồ sơ của Lily Oswood, Erika đã phát ra 81 cảnh báo sai. Là một người từng bị thế giới lãng quên, hồ sơ sinh của Lily và các hồ sơ điều trị đã hóa thành một nắm bùn đen.\nNhưng chúng ta vẫn có thể quan sát hình dạng bạc tâm của cô ấy thông qua các thiết bị đặc biệt: mảnh mai uốn cong, giống như vài sợi tóc đan xen — chính xác hơn là như tóc thai nhi của trẻ nhỏ.\nCần đặc biệt chú ý rằng, Lily luôn thể hiện sự gắn bó đặc biệt với những người kết nối, có lẽ việc tự xưng là \"mẹ\" sẽ giúp rút ngắn khoảng cách với cô ấy hơn là gọi mình là \"đồng hành\" hay \"chủ nhân\"."
  },
  AwakerStory_11256_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11256_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11257_Content = {
    Text = "Ramona bắt đầu trở thành khách quen của sân huấn luyện đại học từ khi mới mười tuổi. Dám tiếp nhận sự chỉ dẫn của những kiếm sĩ mặc áo đen với thân phận con người, cô trở thành đối tượng được nhiều điều tra viên ngưỡng mộ. \n Sau khi chính thức theo học khóa dự bị, với khả năng ghi nhớ vượt trội, bài thi đạt điểm tuyệt đối và kỹ thuật kiếm thuật thanh lịch nhưng chết người, vị thế của Ramona tại Misaque ngày càng tăng cao, tự giác và xuất sắc trở thành biểu tượng của cô. \n Nhưng điều khiến nhiều người không hiểu là, mặc dù xuất sắc như vậy, Ramona vẫn không bao giờ có được tư cách thực hiện nhiệm vụ độc lập. Cô thậm chí đã trải qua năm năm khóa dự bị trước khi nhập học, tiễn đưa nhiều điều tra viên vào thế giới huyền bí. \n Cô đang chờ đợi điều gì? Cô được giao phó sứ mệnh như thế nào? \n Câu hỏi này đã được giải đáp sau khi Người Giữ Gìn mới nhất nhập học."
  },
  AwakerStory_11257_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11257_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11258_Content = {
    Text = "Đồng phục phải được ủi bằng hơi nước, chăn phải được giặt tay, vào mùa hè lò sưởi phải luôn sạch sẽ, vào mùa đông thì phải luôn có lửa cháy. Sàn gỗ phải bóng loáng, kệ sách phải không một hạt bụi, trà đỏ phải luôn giữ nhiệt độ phù hợp, để thuận tiện cho việc thưởng thức bất cứ lúc nào. \n Vì chủ nhân mới cao quý, đặc biệt và độc nhất của cô, người đã cho cô một cuộc sống mới, Người Giữ Gìn, cô có thể làm mọi thứ. Cô là nữ hầu tốt nhất trên thế giới, dĩ nhiên phải hoàn thành hoàn hảo mọi công việc, tỉ mỉ trong từng chi tiết. \n Những lời khen ngợi của chủ nhân luôn khiến cô vui mừng vô hạn, nhưng vẫn chưa đủ, vẫn chưa đủ. Làm thế nào để có được nhiều sự chú ý hơn từ chủ nhân? Làm thế nào để trở nên thu hút hơn? \n \"Chắc chắn là thiếu hoa tai, dây chuyền, vòng tay, nhẫn và phụ kiện trên đầu!\" Cô cắm chổi xuống đất, tự nói với mình, \"Chỉ cần có những trang sức lấp lánh, Gia Lân chắc chắn sẽ trở nên đáng yêu hơn, mọi người sẽ thích nhìn Gia Lân hơn!\""
  },
  AwakerStory_11258_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11258_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11259_Content = {
    Text = "Vào đầu năm A.F.3, thành phố mang tên Tây Đài đã phát hiện ra điều kỳ lạ trong một khu vườn bị thiêu rụi trong đám cháy khi đang tiến hành tu sửa: tro tàn như dây leo bám vào bức tường của nhà hoa đã bị thiêu rụi, trên những bông hồng tro tàn nở rộ có ánh kim loại lấp lánh. \n Theo sự dẫn dắt của dây leo, điều tra viên của Đại học Misag đã nhặt lên viên bạc tâm này. Vào khoảnh khắc chạm vào bụi bạc ấy, đầu ngón tay cô bị bỏng cháy đen, không hề cảm thấy đau đớn, nhưng hai hàng nước mắt lại vô cớ lăn xuống hai bên má. \n Nỗi đau khóc than đến mà không có lý do, chớp mắt cũng tan biến trong tro tàn."
  },
  AwakerStory_11259_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11259_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11260_Content = {
    Text = "Khi người leo núi chinh phục đỉnh cao của Elworth. \n Khi đấu thủ nâng chiếc cúp vô địch thế giới. \n Khi người mộ đạo lắng nghe Thiên Khải trong giấc mộng. \n Khi chiến thắng đến quá dễ dàng, cảm giác thỏa mãn liền trở thành thói quen tầm thường. \n Nhìn quanh khắp nơi, chẳng thấy đối thủ đâu, cũng chẳng còn niềm vui. \n Bên ngoài, Lắc khao khát những cuộc đấu trí đầy kịch tính, khao khát trái tim nhảy khỏi lồng ngực sau khi ALL-IN(tất tay), khao khát khoảnh khắc adrenaline bùng nổ. \n \"Đừng nói những điều đó, chỉ có ta hiểu ngươi. Điều ngươi khao khát không phải là thất bại sao? \n Vậy hãy để ta ban tặng ngươi—thất bại ngọt ngào nhất đời.\""
  },
  AwakerStory_11260_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11260_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11261_Content = {
    Text = "Hiro là một con dao sắc bén và lạnh lẽo. \n Những thể thức tỉnh đã từng thực hiện nhiệm vụ cùng cô ấy đều nói rằng, Hiro là một vũ khí rất hữu dụng, cô ấy đủ mạnh mẽ, luôn hoàn thành nhiệm vụ, chỉ cần nhận được mệnh lệnh giết chóc, bất kể đối mặt với kẻ thù mạnh mẽ đến đâu, cô ấy cũng nhất định sẽ xông vào vòng vây, lấy đi cái đầu của kẻ địch. \n Nhưng chỉ có vậy mà thôi. \n Cô ấy có thể bảo vệ những người đồng hành, nhưng đó chỉ là sự tuân thủ mệnh lệnh, chứ không phải là sự quan tâm đến đồng đội. Cô ấy không tin tưởng họ, họ cũng tự nhiên không thể giao phó lưng mình cho cô ấy. \n Họ không biết rằng, đối với cô, lưỡi dao hướng về phía đồng minh là hèn hạ, là tồi tệ, là điều đáng bị trừng phạt và khinh bỉ. \n Cô hiểu rõ sự đáng ghét của sự phản bội, vì vậy tuyệt đối sẽ không hướng kiếm về phía đồng đội."
  },
  AwakerStory_11261_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11261_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11262_Content = {
    Text = "Di chứng của việc không hoàn toàn được thức tỉnh, cộng với sự kích thích tâm lý do người thay đổi liên kết gây ra, đã khiến tính cách và tâm trí của Lily có một mức độ thoái hóa nhất định, sự im lặng của cô trong trường đại học là điều ai cũng thấy. \n Ngoài việc đi theo Người Giữ Gìn và thân thể được đánh thức Lơ-tan, Lily hiếm khi xuất hiện một mình trong khuôn viên trường. Cô không xuất hiện trong lớp học, cũng không tham gia vào những trò chơi của các trai trẻ được đánh thức. Khi không ra trận, cô chỉ lặng lẽ chờ đợi mệnh lệnh trong ký túc xá. \n Cửa sổ phòng của Lily đối diện với Keygrave ở phía sau khuôn viên trường, khi mặt trời lặn, cô sẽ đứng bên cửa sổ, ngây ngốc nhìn vào Keygrave được bao phủ bởi ánh sáng vàng nhạt. \n Bia mộ hình chìa khóa bạc dưới ánh sáng của hoàng hôn kéo dài bóng đổ, Lily đứng trước cửa sổ cũng im lặng như những bia mộ đó."
  },
  AwakerStory_11262_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11262_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11263_Content = {
    Text = "Đây là thành phố của hoa và thơ, nơi mà một bài thơ tình say đắm tương đương với một bó hồng mới cắt, cũng có thể đổi lấy lương thực cho một gia đình ba người trong một tuần. Sự xuất hiện của một tác phẩm xuất sắc cũng đồng nghĩa với việc một nhà thơ thiên tài sẽ nổi tiếng. \n Người đó từng là một người làm vườn suốt ngày bên những cây cỏ khô và phân bón, cô ấy thưởng thức những lời ca ngợi và sự theo đuổi mà những câu thơ tao nhã mang lại, không còn chăm sóc công việc làm vườn nữa, thậm chí khóa cửa nhà kính, không cho phép bất kỳ ai bước vào vườn hoa. \n Khi người khác hỏi, cô cũng chỉ trả lời rằng trong nhà kính có \"cảm hứng\". \n Họ sinh ra trong hoàn cảnh khiêm tốn, là con cái của những người trung thành với quý tộc. Liên bang Constantin được thành lập, quý tộc cũ bị thanh trừng, họ cũng mất chỗ ở. \n Đó là người hầu đã lớn lên cùng tiểu thư, nhưng sớm bộc lộ tài năng về chữ nghĩa - nhưng người hầu thì làm sao có thể đọc thơ? \n Môi trường xung quanh luôn biến đổi, tài năng thơ ca vẫn không thể mang lại khả năng sinh tồn cho cô gái. Tất cả mọi thứ khiến cô gái càng thêm khó hiểu, càng thêm u sầu. \n Cho đến khi người làm vườn đưa tay ra - đôi tay bị gai cắt nát, tặng cho cô một khu vườn. Trong vương quốc nhỏ bé này, họ đã trải qua khoảng thời gian hạnh phúc nhất trong cuộc đời. \n Cuộc sống bình yên bắt đầu thay đổi từ một bài thơ mà người làm vườn nhận được. \n Tài năng của bạn bè thật sự quyến rũ, cô muốn nhiều người hơn nữa thấy bài thơ tặng bạn này. \n Người bạn nhút nhát và u sầu không muốn ký tên, người làm vườn bèn ký tên mình ở nơi ký tên - \"Nếu được công bố, ký tên cũng tiện để họ gửi tiền thưởng.\"\n Sự thay đổi của người làm vườn cũng bắt đầu từ khoản thù lao đầu tiên. \n Cô không hiểu, tại sao mình đột nhiên từ người bảo vệ trở thành gánh nặng. \n Cô không hiểu, tại sao bạn mình có thể dễ dàng nhận được tất cả tình yêu và sự khen ngợi, trong khi những nỗ lực và công sức của mình lại không thể chống lại tài năng. \n Bị cơn thèm muốn và ghen tị làm mờ mắt, cô bắt đầu lợi dụng lòng tin của bạn để đánh cắp tác phẩm của cô ấy. Hành động lừa dối không thể quay đầu lại, hạt giống từ đầu đã được chôn sâu trong lòng người làm vườn, bắt đầu nảy mầm cùng với sự lan truyền của danh hiệu nhà thơ thiên tài, trong một cuộc phỏng vấn trên đường phố, nở ra nụ hoa - những người hâm mộ cuồng nhiệt đã dùng những tình cảm ẩn giấu trong câu thơ để hỏi người làm vườn, người không thể hiểu được thơ văn hoang mang đổ mồ hôi, vội vã rời đi. Đêm khuya trở về vườn hoa, đối diện với ánh mắt quan tâm của bạn mình, những bông hoa hoảng sợ nở rộ vào lúc này. \n Sau một trận hỏa hoạn chấn động Tây Đài, nhà thơ thiên tài tuyên bố ngừng viết, biến mất cùng với tài sản và danh vọng mà cô đã giành được trong thời gian ngắn."
  },
  AwakerStory_11263_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11263_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11264_Content = {
    Text = "Trong ba năm qua, khu vực tam giác Mông Gơ đã xảy ra nhiều vụ tai nạn tàu thuyền, kèm theo một số trường hợp tàu mất tích hoàn toàn.\nMột thủy thủ đã làm chứng rằng, trong quá trình tham gia cứu hộ vụ tai nạn, anh ta đã chứng kiến một người phụ nữ \"đầu phát sáng\" trên boong tàu gặp nạn.\nCác điều tra viên ngoại cần đã vội vã đến khu vực tam giác Mông Gơ, nhưng tàu thuyền đã mất liên lạc trong một thời gian. Khi đội cứu viện tìm thấy tàu, chiếc tàu tiên phong đã mất động lực, đang trôi theo dòng hải lưu về trung tâm khu vực tam giác Mông Gơ. Tất cả các thuyền viên đều bị thiếu nước nghiêm trọng, cực kỳ suy nhược, và tự khai đã trải qua những ảo giác mạnh mẽ.\nTrong quá trình kiểm tra y tế cho các thuyền viên, đã phát hiện ra bạc tâm từ đồ dùng cá nhân của điều tra viên Aivors, nhưng điều tra viên này luôn phủ nhận việc tàu đã tiếp xúc với thể thức tỉnh.\nBạc tâm này sau đó được hệ thống thức tỉnh niêm phong, số hiệu 6291-S-S-01, dự kiến sẽ được sử dụng cho việc giảng dạy thức tỉnh cho các điều tra viên dự bị vào năm A. F. 315."
  },
  AwakerStory_11264_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11264_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11265_Content = {
    Text = "Sau khi được thức tỉnh, cuối cùng chúng tôi cũng biết được Muphí đã sống như thế nào trong giáo đoàn trước đây. \n Cô ấy chống một chiếc mái che nắng, trước khi ra ngoài phải dành nhiều thời gian để chỉnh trang diện mạo của mình. Trà chiều phải được tổ chức vào lúc bốn giờ chiều, kèm theo trà sữa và bánh scone với mứt dâu. Giữ gìn vẻ sạch sẽ và thanh lịch, đó chính là số mệnh của một tiểu thư, cô ấy dù ở đâu cũng kiên trì sống một cuộc sống của tiểu thư. \n (Chú thích của nhân viên lưu trữ: Tôi nghĩ, việc cô ấy trực tiếp dùng tay nắm lấy bánh pudding thịt cừu không thể gọi là tiểu thư…) \n Dù bây giờ không còn người hầu hạ cô ấy như trước, cô ấy vẫn sống theo cách mà mình mong muốn, điều này thực sự là một điều đáng an ủi. \n Bị ảnh hưởng bởi sự kiện đó, cô ấy rất ít tiếp xúc với Thể thức tỉnh Miriam và Goliath, thậm chí còn cố tình làm ngơ. Khi gặp Thể thức tỉnh tulô, cô ấy cũng thể hiện một biểu cảm rất phức tạp. \n Nếu nhắc đến quá khứ, cô ấy sẽ trở nên rất cáu kỉnh. Có lẽ, cô ấy vẫn cần thêm một chút thời gian để bình tĩnh lại."
  },
  AwakerStory_11265_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11265_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11266_Content = {
    Text = "Không cần phải sợ hãi chiếc bịt mắt đen của ông, sự giao nhau của bóng tối không thể che khuất lòng thương xót của ông. Thân thể mù lòa đã tiêu vong, nhưng ý nguyện cứu chuộc sẽ mãi tồn tại. Trước mặt ông, tất cả đều đáng được yêu thương, tất cả đều sẽ được yêu thương. \nLời của Cha Thần luôn khắc trên bảng đá, nhờ dòng xương máu được ban phước này, ông sẽ ban cho các ngươi \"phúc lành\"."
  },
  AwakerStory_11266_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11266_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11267_Content = {
    Text = "Anh ta luôn cau có, một mình lang thang bên bờ hồ. Dần dần, các học sinh gọi bờ hồ là \"Địa phận của người cá âm u\". Vì vậy, anh ta giống như một chúa tể, mỗi ngày trang nghiêm đến đây tuần tra. Khi anh ta nhảy xuống đáy hồ, những bong bóng khí lăn tăn dịu dàng ôm lấy anh; trong nước, những lời châm chọc từ bờ dường như cũng không còn nghe rõ nữa."
  },
  AwakerStory_11267_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11267_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11268_Content = {
    Text = "Người tín đồ chân chính nhất của thần linh, là thần dân trung thành nhất của quốc vương, dùng ánh sáng của đức tin để soi sáng con đường hành hương. \nSự sụp đổ của quốc gia vĩnh cửu đối với Pháp Luân Tư giống như tháp thành mất đi nền tảng, dây leo mất đi đất đai. Niềm tin vào quốc gia vĩnh cửu nâng đỡ cô ấy nổi lên giữa đời, nhưng nỗi buồn khổ không tìm thấy đã lâu và nỗi cô đơn vô tận cuối cùng đã đè bẹp người lữ khách tội nghiệp. \nPháp Luân Tư lặn sâu vào đại dương mà cô yêu thương và ghét bỏ, dấy lên những cơn sóng dữ dội, nước biển dậy sóng như những lễ tế trong ký ức rực rỡ, mang lại cho cô chút an ủi. \nKhi bị anh hùng chém đầu, ánh mắt như ngọn đuốc nhìn về nơi đó, cũng chính là quốc gia vĩnh cửu mà cô không thể nào rời bỏ."
  },
  AwakerStory_11268_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11268_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11269_Content = {
    Text = "Cô ấy dường như luôn quanh quẩn bên chiếc xe máy mang tên \"hình bóng\": vặn một cái ốc ở đây, điều chỉnh ống dẫn ở đó... Đây là một công trình không có điểm kết thúc, mặc dù nhiều người đều nghĩ rằng cô đã sửa chữa nó tốt nhất có thể, cô vẫn ngày này qua ngày khác chìm đắm trong đó. \n Nguyên nhân sâu xa chính là cảm giác \"còn thiếu điều gì đó\" mà không rõ từ đâu đến."
  },
  AwakerStory_11269_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11269_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11270_Content = {
    Text = "「4:30 Chạy bộ dọc sông Isis 6 dặm. Trong quá trình chạy, đã xảy ra cãi vã với một bà cụ và đá bay một con chó poodle. \n……\n12:00 Thưởng thức bữa trưa. Bánh kếp mật ong, món khai vị olives đi kèm……năm phần thịt cừu nướng? Không thể tin nổi. \n13:00 Đến câu lạc bộ đánh cá trout. Kỷ lục: 10 thắng 0 thua, thời gian nhanh nhất 3 giây — đối thủ bỏ cuộc vì quá sợ hãi. \n19:00 Cùng Người Giữ Gìn đến Nhà hát Covent xem vở 《Vua Chăn Chiên》, bị đuổi ra khỏi nhà hát do phát biểu những lời chính trị nguy hiểm. \n22:00 Được phát hiện lảng vảng gần Bệnh viện St. Mary's, có thể suy đoán là muốn tìm cách trộm túi máu từ bệnh viện. \nCuộc quan sát kết thúc, đánh giá mức độ nguy hiểm: SSS.」\n——Trích từ 《Nhật ký Quan sát của Hannah về thân thể được đánh thức》"
  },
  AwakerStory_11270_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11270_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11271_Content = {
    Text = "Phiệt nhìn thấy học sinh đang giấu mình trong phòng thí nghiệm mà lén khóc. \n Đây không phải là người mà cô thích nhất, nhưng là một trong những học sinh yêu mến cô nhất. \n Nữ sinh không bao giờ để tâm đến sự chống cự và xa cách của Phiệt, không sợ hãi khả năng không kiểm soát của cô. \n Cô ấy sẽ dùng tiền sinh hoạt để mua tất cả các loại đồ ngọt, chỉ vì lo lắng cô không đủ năng lượng; sẽ mặc bộ đồ bảo hộ nặng nề, chỉ để chải tóc dài rối bời của cô. \n …… Để đền đáp lại cô ấy, Phiệt đã nghĩ như vậy. \n Vì vậy, Phiệt đã làm những điều trong khả năng của mình. \n —— Nếu chỉ vì lo lắng không thi đỗ mà khóc, thì đe dọa người khác từ bỏ điểm số cũng được chứ nhỉ?"
  },
  AwakerStory_11271_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11271_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11272_Content = {
    Text = "Misaque đã hoán tỉnh và chứa chấp nhiều thể thức tỉnh, nhưng không ai đặc biệt hơn Thái Di Sơ.\nCô ấy giúp các nữ sinh chọn trang điểm cho buổi hẹn hò, cô ấy giúp những người thất vọng lấy lại hy vọng, cô ấy giúp các điều tra viên đang suy sụp tinh thần bước ra khỏi bóng tối.\nGiống như tình nhân, lại như chị em, và hơn cả là mẹ. Cô ấy luôn có thể xây dựng một cái bẫy mang tên \"tình yêu\", lặng lẽ khiến người ta sa vào, khiến người ta không hề hay biết mà muốn hy sinh mọi thứ vì cô——\nSau lần thứ ba ngăn sinh viên uống chất lỏng bí ẩn do Thái Di Sơ cung cấp, Cục quản lý thể thức tỉnh đã ban hành lệnh hạn chế đối với cô.\n \"Cấm Thái Di Sơ lại gần tất cả học sinh nếu không có Người Giữ Gìn đi cùng.\""
  },
  AwakerStory_11272_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11272_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11273_Content = {
    Text = "Tất cả ý nghĩa tan biến như cát, màn giả dối của thế giới rút lui trước mắt cô, mọi thứ trở về bóng tối nguyên thủy nhất. \nTrong buổi biểu diễn cuối cùng trên sân khấu tối tăm này, vũ công khoa học vẫn đang hết mình múa. \nCô không còn quan tâm đến việc bị rỗng rỗng tiêu thụ chậm rãi, vì kết thúc của vở kịch đã được viết sẵn từ lúc bắt đầu. \nNhư mọi khi, cô sẽ hiến dâng sức mạnh thiên tài của mình cho thế giới mà không giữ lại gì, theo cách gần gũi nhất với sự thật. \nNếu bạn hỏi thêm một chút, cô sẽ khẳng định rằng mình vẫn giữ tình yêu đối với nhân loại và thế giới, cô muốn chấm dứt mọi nỗi đau của nhân gian, đưa mọi người trở về quê hương thực sự, quê hương ban đầu."
  },
  AwakerStory_11273_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11273_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11274_Content = {
    Text = "A. F. 3@1 năm @1 tháng. \n Tại bãi đá quỷ ở bờ biển phía đông Cộng hòa Agro, ngư dân địa phương báo cáo đã vớt được \"một thi thể có hình dạng kỳ quái\"- cơ thể nhỏ bé, gù lưng, mắt lồi, da một phần cứng lại, có màng giữa các ngón tay, điều kỳ lạ nhất là dấu đỏ đối xứng hai bên cổ. Nếu không phải vì anh ta mặc đồng phục học sinh, có lẽ rất khó để coi là \"thi thể con người\". \n Khi điều tra viên đến nơi, thi thể kỳ quái đã bị những ngư dân hoảng sợ coi là vật không may thiêu rụi, chỉ còn lại một chiếc vali đang rất thịnh hành trong giới học sinh. Trong vali không có bất kỳ quần áo thay đổi nào, chỉ có một số bản thảo chữ viết mờ, một chiếc la bàn, và một bức ảnh của một người phụ nữ trung niên."
  },
  AwakerStory_11274_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11274_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11275_Content = {
    Text = "Cô bé mặc chiếc váy đơn giản, làn da vẫn còn đau rát vì vừa bị rửa một cách thô bạo. Cô không hiểu tại sao mình lại bị lính đưa đến đây, nhà của quý tộc không phải là nơi nô lệ có thể tự do ra vào, và cô còn quá nhỏ để đến đây phục vụ. \nBà chủ mặc áo choàng trắng tinh ngồi trên ghế, cô bé cúi đầu xuống, run rẩy vì sợ hãi và lo lắng. \n \"Quả nhiên tôi không nhầm...\" bà chủ nói, \"Rất giống, thực sự rất giống.\"\nGiống? Là nói cô giống ai đó sao? \n \"Thật tốt, quá tốt rồi.\" Bà chủ vỗ tay vui vẻ, \"Chính là em rồi. Từ hôm nay, tôi sẽ là mẹ của em, nhớ chưa?\"\nMẹ? Nhưng cô đã có mẹ rồi. Mẹ ở nhà, khóc lớn khi cô bị đưa đi. \nMẹ cô sẽ ra sao? \nNghi vấn và bối rối quanh quẩn trong đầu cô bé, cô muốn hỏi câu trả lời, nhưng cũng hiểu rằng ý định của chủ nhân chính là lệnh của nô lệ, và nô lệ vi phạm lệnh sẽ bị trừng phạt nghiêm khắc. \n \"Dạ, nhớ rồi, thưa bà chủ.\"\n \"Thật là một đứa trẻ ngoan. Tôi nghĩ xem... Sẽ gọi em là Hiro, em có thích cái tên này không, Hiro? Chắc chắn là thích rồi. Nào, hãy mặc chiếc váy này cho mẹ xem.\""
  },
  AwakerStory_11275_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11275_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11276_Content = {
    Text = "Goliath chuyên quyền, kiêu ngạo, nhưng lực lượng của anh ta không thể phủ nhận. Từ bản ghi chiến đấu của cô Erika, có thể thấy rằng lực lượng bạo lực đó đủ để giúp anh ta vượt qua những tình huống nguy hiểm một mình. Tôi nghĩ rằng lý do Goliath không quan tâm đến khả năng của người bạn đồng hành là vì trong thế giới của anh ta, không ai mạnh hơn anh ta. \n Tuy nhiên, khi đối mặt với Miriam, Goliath luôn không tự chủ mà lộ ra chút sợ hãi. Khó có thể tưởng tượng — rốt cuộc là sự tồn tại như thế nào mới có thể khiến vị thủ lĩnh bạo lực này, vị vua cũ tàn nhẫn, sinh ra cảm giác kính sợ. \n Ngoài ra, anh ta còn thể hiện sự quan tâm khác thường đối với cô Muphí. Đôi khi, anh ta lảng vảng xung quanh khu vực ảo ảnh của trường học, dường như đang chờ đợi Muphí hoàn thành nhiệm vụ trở về; đôi khi, anh ta lặng lẽ quan sát xem Muphí có bị thương trong nhiệm vụ hay không. \n Cô Peaslee cũng đã chú ý đến điều này, cô từng nói đùa với tôi: \"Này, cậu có thấy anh ta đang cố gắng làm một người cha bình thường không?\"\n —— Ghi chép quan sát của một nhà nghiên cứu thực tập"
  },
  AwakerStory_11276_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11276_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11277_Content = {
    Text = "Văn phòng của Wenkel được gọi là Bắc Đẩu của Đại học Misag. Nơi đó luôn sáng đèn, bất kỳ góc nào có thể tồn tại bóng tối đều được thắp sáng bằng đủ loại dụng cụ chiếu sáng - từ đèn cầm tay đến đèn dầu, từ bóng đèn dây tóc đến nến. \n Nỗi sợ hãi bóng tối thậm chí khiến cô ấy ghét ngủ, vì vậy cô ấy luôn ngồi thẳng dưới chiếc đèn lớn nhất, viết những ký hiệu không ai hiểu trên những tờ giấy nháp rải rác khắp nơi, không phân ngày đêm."
  },
  AwakerStory_11277_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11277_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11278_Content = {
    Text = "Kẻ khắc sét căm ghét loài người, ngay từ khi còn là một đứa trẻ, anh ta đã căm ghét họ. \nAnh ta từng cứu một cô bé bị rơi xuống nước, nhưng lại bị những đứa trẻ khác vu khống là kẻ xấu; anh ta tránh xa họ, nhưng vẫn bị đuổi theo và gọi là \"kẻ có mùi như ếch\". \n\nTrong những ngày u ám kéo dài hàng chục năm, điều duy nhất có thể khiến anh ta hy vọng chính là những bức thư của chú Orn. Kiến thức sâu rộng của chú bao gồm vô số câu chuyện về ma quái, khiến Kẻ khắc sét nhỏ tuổi mê mẩn. Nhưng niềm vui không kéo dài lâu, chỉ vài năm sau, chú Orn bỗng nhiên mất tích. \nCho đến năm 16 tuổi, Kẻ khắc sét trở về thăm nhà ông nội và tình cờ tìm thấy bản thảo của chú Orn. Cuối cùng, anh ta mới biết ý nghĩa cao quý ẩn chứa trong những đường vân trên thân thể mình. \nHa, loài người, rốt cuộc chỉ là sinh vật thấp kém mà thôi. \nTừ đó, anh ta không còn bi quan nữa, mà thay vào đó là kiên nhẫn chờ đợi, chờ đợi ngày định mệnh đến."
  },
  AwakerStory_11278_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11278_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11279_Content = {
    Text = "Cậu bé từng được gọi là \"Kỵ sĩ Tử thần\", việc này đã không còn nhiều người trong trường nhớ đến. \n Chỉ vào giờ giữa đêm, cảnh tượng của ngày đó sẽ biến thành ác mộng, len lỏi vào giấc mơ của cậu bé. \n Thân thể bị ăn mòn xâm nhập trường học, tháp chuông sụp đổ, \"Người giữ bí mật\"đang hấp hối. \n \"Đừng khóc, Orci, đây không phải lỗi của em...\"\n Đội kỵ binh sắt thép xâm chiếm quê hương, cung điện sụp đổ, dòng máu đen chảy từ ngón tay công chúa. \n \"Đừng hy sinh vì tôi, Orci, em đã làm đủ rồi...\"\n Cát của ký ức mang theo nỗi đau, xói mòn linh hồn của cậu bé."
  },
  AwakerStory_11279_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11279_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11280_Content = {
    Text = "Có những thể thức tỉnh sau khi tỉnh dậy sẽ thể hiện sự không thích ứng với cơ thể mới và cuộc sống mới, trong khi có những người nhanh chóng chấp nhận tình hình hiện tại và chủ động bắt đầu cuộc sống thứ hai. \n Tulô không thuộc về bất kỳ loại nào, chưa từng có ai như anh ấy thể hiện một cách thẳng thắn sự thiếu hứng thú với thế giới hiện tại. \n Anh ấy có phẩm chất cực kỳ xuất sắc, có lẽ anh ấy đã sớm nhận thức được tình hình và cuộc khủng hoảng của thế giới hiện tại, nhưng anh ấy vẫn thích dành nhiều thời gian cho giấc ngủ. \n Dù không phải do mong muốn của bản thân, anh ấy cũng khá nổi tiếng giữa con người và thể thức tỉnh trong trường học. Các nghiên cứu viên theo dõi từng cử động của anh, thỉnh thoảng công bố một vài bài nghiên cứu; Khoa khảo cổ học và Khoa thiên văn học thường gửi đến các lời mời tham gia hội thảo học thuật với đủ loại tên gọi, phần lớn đều chỉ định mời anh tham gia. \n Tulô cũng có ảnh hưởng khá lớn giữa các thể thức tỉnh: Muphí mỗi khi nhìn thấy anh đều tỏ ra ủ rũ, Goliath dường như luôn muốn âm thầm so tài với anh, còn Miriam thì coi mỗi câu nói của anh như thánh chỉ. \n Đối với những điều này, anh chưa từng thể hiện thái độ gì đặc biệt, không mong đợi cũng không yêu cầu. \n Đôi khi, anh sẽ tùy ý đáp ứng một số yêu cầu, có lúc thì không."
  },
  AwakerStory_11280_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11280_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11281_Content = {
    Text = "Cho đến khi trở thành Thể thức tỉnh, Sorrel vẫn không thể quên những quý tộc đã nịnh hót cô, không thể quên từng khuôn mặt đầy nịnh nọt đó.\nNhững nụ cười đó thật khiến người ta buồn nôn, láu cá, bẩn thỉu, không ngừng thể hiện sự khao khát và toan tính đối với cô, nhưng cô buộc phải dệt nên một mạng lưới dịu dàng cho những khuôn mặt như vậy.\nCô phải dệt nên một mạng lưới chặt chẽ nhất, đi sâu vào từng góc tối, thu phục từng người, nắm giữ mọi nhược điểm.\nCô cũng phải giống như nước ấm dần lên, khiến những người đó đắm chìm trong đó, khi muốn tháo bỏ mặt nạ mới phát hiện ra rằng đã không thể trốn thoát.\nNhưng khi nhận ra, người không thể trốn thoát lại chính là cô.\nKhông thể trốn thoát, không thể lơ là, không thể từ bỏ.\nSorrel đã không còn quyền quay đầu, ngoài việc đứng trên tất cả mọi người, cô không còn con đường nào khác để đi."
  },
  AwakerStory_11281_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11281_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11282_Content = {
    Text = "\n \"Tôi sẽ đeo viên tím thạch anh màu đen như rượu vang.\"\n \"Tôi sẽ mặc chiếc váy dài quý phái làm từ lông đà điểu.\"\n \"Tôi sẽ trở thành ánh sáng duy nhất trong bữa tiệc.\"\nCô hầu gái chớp đôi mắt màu hổ phách, cô còn nhiều ước nguyện đẹp, nhưng không thể nói thêm. Trước thân thể đứng im, là biển lửa xanh vô tận, nở rộ im lặng trong đêm tối đen."
  },
  AwakerStory_11282_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11282_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11283_Content = {
    Text = "Cô ấy tính toán tốc độ rút kiếm, tính toán góc độ né tránh tấn công. \n Cô ấy tính toán tính khả thi của kế hoạch trốn thoát, tính toán xác suất thế giới có thể tiến vào tương lai. \n Đến tận phút cuối, cô ấy vẫn không bỏ cuộc trong việc tính toán. \n Giống như cô ấy chưa bao giờ từ bỏ việc đi trên vùng đất không người này."
  },
  AwakerStory_11283_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11283_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11284_Content = {
    Text = "Nghệ sĩ từ Tây Đài không quan tâm đến nhân loại, cô chỉ theo đuổi một vẻ đẹp tinh khiết tuyệt đối, ghi dấu mãi mãi những khoảnh khắc chóng vánh. \n Cảm hứng tuôn trào, con dao khắc không bao giờ ngừng lại. Mỗi khi hoàn thành một tác phẩm, bóng mây màu san hô lại xâm thực cơ thể một phần, nỗi đau và niềm vui cùng hiện hữu, trong khi người điêu khắc cũng không để tâm đến bản thân."
  },
  AwakerStory_11284_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11284_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11285_Content = {
    Text = "@3 được xây dựng vào thời kỳ Samnites thứ hai, được trang trí bằng phong cách Pompei thứ ba và Lemvahi tinh tế, đây là ngôi nhà điển hình của tầng lớp thương nhân giàu có thời La Mã. Có hai sân trong, bốn triclinia và @1@1\n…… tất cả đều bị thiêu rụi trong cuộc nổi dậy nô lệ nổi tiếng đó…… Theo những ghi chép đương thời, dưới đống hoang tàn có phong ấn một con nhện trắng khổng lồ, người dân địa phương gọi nó là 「Thần Mê Cung」, và tin rằng những người bước vào lãnh thổ của nhện sẽ lạc lối giữa vô số lối đi và cổng, cuối cùng trở thành vật chủ cho thế hệ con cháu của nó.\nMột câu chuyện kinh dị thú vị, nhưng sẽ không ngăn cản chúng ta @2@1\n—— trích từ 《@2 Nhật Ký Khảo Cổ Tại Phế Tích》\n\n...... Tình hình rất tồi tệ, thưa ngài Goodman. Nhóm của Moretti đã mất tích nhiều ngày, chúng tôi đều hiểu rằng điều này không liên quan gì đến truyền thuyết về 「Thần Mê Cung」, nhưng thật sự rất đáng lo ngại. Hiện tại chúng tôi quyết định kết thúc khảo sát sớm và trở về Durham.\nNgoài ra, đội khảo cổ đã phát hiện một cụm vật thể dạng lõi bạc trong phế tích, có thể liên quan đến @1 mà ngài đã đề cập trước đó......\n—— trích từ một bức thư của Clarkson Johnson 《gửi cho Goodman》"
  },
  AwakerStory_11285_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11285_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11286_Content = {
    Text = "A. F. 2@2 năm 11 tháng, khu vực Beren xảy ra động đất lớn. \n Ngày hôm sau, hai giáo sư được giao nhiệm vụ lên đường đến khu vực bị ảnh hưởng, tìm kiếm đội điều tra viên Misaque mất liên lạc sau trận động đất. \n Đội này đã hoạt động ven biển giữa đất liền trước khi mất liên lạc, nhiệm vụ chính là khảo sát, khai thác di tích lịch sử, tìm kiếm các manh mối có thể liên quan đến \"hiện tượng ăn mòn\". \n Ngày 8 tháng 11, tại địa chỉ được cho là nơi cuối cùng nhìn thấy thành viên của đội, giáo sư @2 phát hiện một di tích cung điện chưa được ghi chép trong tài liệu lịch sử, thu hồi một chiếc chìa khóa bạc theo tiêu chuẩn Misaque, số hiệu I-@2, nhưng không tìm thấy thành viên đội. \n Ngày 9 tháng 11, hai mảnh bạc tâm được khai quật từ di tích, sau đó được mang về Lentiennam, do giá trị lịch sử của chúng mà được niêm phong, hẹn ngày khác Hoán tỉnh."
  },
  AwakerStory_11286_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11286_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11287_Content = {
    Text = "Vanda đến Misaque ngày đầu tiên, đã bị buộc tội nghiêm trọng vì \"đạp lên người khác một cách tùy tiện\".\nTheo một học sinh không muốn tiết lộ danh tính cho biết, cậu ta chỉ tình cờ đi qua thư viện, và đã có một ánh mắt giao nhau với Vanda, sau đó bị lật ngã xuống đất, @2 bị gán vào @3(học sinh này từ chối tiết lộ thêm chi tiết).\nQuá trình thương tổn từ khi xảy ra đến khi kết thúc không quá năm phút, tình tiết nghiêm trọng, thật đáng lên án.\nỦy ban kỷ luật Misaque(gọi tắt là MDC) sẽ coi trọng và đồng cảm sâu sắc với tình huống này, hiện đã thành lập nhóm chuyên án, sẽ tiếp tục tiến hành cải tạo tư tưởng và hành vi của Vanda một cách triệt để, nhằm giúp cô sớm hòa nhập vào đời sống trong khuôn viên trường."
  },
  AwakerStory_11287_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11287_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11288_Content = {
    Text = "「@1 tháng @1, nghĩa trang đại học lại bị phá hoại. Tính đến nay, đây đã là vụ đào mộ ác ý thứ ba xảy ra trong tháng. \n Sau nhiều tuần theo dõi điều tra, các thành viên hiệp hội đã xác định được thân thể được đánh thức sơn là nghi phạm. \n Ai từng ghé thăm xưởng làm việc của nhà điêu khắc này đều sẽ choáng váng trước những tác phẩm điêu khắc chủ đề biển cả đa dạng, quái dị và lố bịch, đồng thời nghi ngờ về nguồn gốc nguyên liệu: tại đây chúng tôi đã phát hiện chuỗi hạt vỏ sò mà Natalia đáng thương đeo khi hạ táng, cũng như đá hoa cương Aberdeen cùng chất liệu với bia mộ. Khác với Pickman, người nhiệt tình giải thích ý tưởng sáng tạo của mình, sơn khó nắm bắt hơn — cô ấy tuy mỉm cười nhưng hoàn toàn phớt lờ sự chất vấn của chúng tôi. \n Đừng chạm vào dao khắc của cô ấy, cũng đừng ở riêng với cô ấy trong xưởng — Giáo sư Dexter từng cảnh báo chúng tôi như vậy, nhưng để vạch trần chân tướng vụ đào mộ, biện pháp mạnh là cần thiết. \n Hiện tại là @1 tháng @1 lúc 0 giờ 45 phút, thành viên @2 của Hiệp hội người yêu thích suy luận đã lẻn vào xưởng làm việc của sơn, chúc tôi may mắn @3」\n — Trích từ 「Bản ghi điều tra S-618 của Hiệp hội Người Yêu Thích Suy Luận」"
  },
  AwakerStory_11288_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11288_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11289_Content = {
    Text = "Lơ-tan dán quá nhiều nhãn lên người, không ai biết nên đối xử với nữ kiếm sĩ mặc áo đen này bằng thái độ như thế nào. \n Quá khiêm tốn, cô ấy sẽ lấy danh nghĩa nhàm chán để đập vỡ đầu gối của bạn; quá kiêu ngạo, cô ấy sẽ dùng đại kiếm chặt đứt sự vô lễ của bạn; quá cứng rắn, cô ấy sẽ dùng chiến đấu để làm mềm mại linh hồn của bạn. \n Nhưng có lẽ, đây chính là sự kiêu ngạo của đứa con mới sinh của hành tinh: với tư cách là một người bảo vệ đã từng, cô ấy đáng lý ra phải được hưởng quyền kiêu ngạo."
  },
  AwakerStory_11289_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11289_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11290_Content = {
    Text = "Mỗi khi màn đêm buông xuống, Nốtira sẽ cùng mẹ chui vào kho, cầm lấy các loại công cụ, dùng những linh kiện tích góp được để lắp ráp một chiếc xe máy đơn bánh mang tên hình bóng. \n \"Tại sao không mua luôn một chiếc?\" Cô bé ngẩng đầu lên, hỏi mẹ đang cầm công cụ, \"Như vậy chúng ta có thể lập tức đi phiêu lưu.\"\n Mẹ nắm tay cô, vừa dạy cách hàn kim loại nhanh và chắc chắn, vừa nói: \n \"Máy móc cũng giống như con người, mỗi cái đều có tính khí và tính cách riêng. Chỉ có những thứ thực sự hiểu chúng ta mới có thể ở bên cạnh chúng ta lâu dài.\"\n \"Như bạn bè vậy à?\"\n \"Ngoại trừ việc máy móc do chúng ta tạo ra — đúng rồi, như bạn bè vậy.\"\n Bánh xe lớn phải chắc chắn, động cơ trang bị phải bền bỉ, vì một khi họ đã xuất phát, sẽ không dễ dàng quay đầu lại. Họ muốn cùng nhau đi khắp thế giới, cùng hoàn thành một cuộc phiêu lưu vĩ đại. \n Bệnh tật đã cướp đi mẹ của cô, để lại một xưởng sửa chữa đầy công cụ nhưng lại trống rỗng. Nốtira ôm chiếc hình bóng chưa hoàn thành, quyết tâm cùng người bạn lạnh lùng này hoàn thành ước mơ của cô và mẹ. \n Cho đến chuyến đi cuối cùng."
  },
  AwakerStory_11290_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11290_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11291_Content = {
    Text = "Aluvi 3@2 năm hè, trên đảo Irian lan truyền truyền thuyết về quái vật biển. \n Có ngư dân tuyên bố đã nhìn thấy một sinh vật thân mềm cao khoảng năm tầng lầu ở gần bờ biển. Nó có màu đỏ thẫm, các xúc tu có vòng đồng tâm màu đen. \n Khi nghe thấy tin đồn về con quái vật này, tôi đang cùng tiền bối Johansson xác minh hiện tượng ăn mòn nghi ngờ xảy ra ở khu vực Medan. Ngày hôm sau, tiền bối đã chuẩn bị xong tàu thuyền để đến đảo Irian, tôi đã viết báo cáo này ở giữa biển Amiran. \n Vào ngày thứ ba của chuyến hải trình, trên mặt biển xuất hiện một số lượng lớn xác cá nổi: cá thu, cá bơn, cá heo, tôi thề rằng đã thấy một con cá nhà táng mang thai trong đám xác đó! Mặc dù các thủy thủ già nói rằng sự thiếu oxy trong nước biển do sinh sản quá mức là nguyên nhân gây ra cái chết của cá, nhưng tôi luôn cảm thấy chúng tôi đã bỏ lỡ điều gì đó... \n Vào ngày thứ tám của chuyến hải trình, tình trạng say sóng của tôi ngày càng nghiêm trọng, cơn buồn nôn dữ dội khiến tôi gần như không thể ăn uống. Mặc dù chúng tôi đã gần đến đảo Irian, nhưng Johansson kiên quyết yêu cầu chúng tôi quay trở lại @3... Tôi không hiểu, nhưng tôi chọn tin tưởng vào tiền bối này. \n —— Bell Columbus 《Báo cáo thực tập mùa hè năm 3@2》"
  },
  AwakerStory_11291_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11291_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11292_Content = {
    Text = "Muphí đã từng trải qua một lần cái chết.\nSau khi không mấy vui vẻ bước qua cánh cửa mang tên \"Thần Giáng\", cô chứng kiến \"Thần Minh\" giáng sinh trong lồng ngực của mình.\nThật buồn cười làm sao, đó chỉ là một khối thịt xấu xí vô thức, vô tri giác, vậy mà cô buộc phải dâng hiến cuộc đời tươi sáng rực rỡ của mình cho nó.\nCàng mỉa mai hơn, số phận đảo điên luôn không buông tha. Vào khoảnh khắc Thần Minh giáng thế, cô chịu đựng cơn đau dữ dội mà chấp nhận sự hy sinh không hề tự nguyện. Sau khoảng thời gian dài đằng đẵng như chìm vào giấc ngủ, Muphí kinh ngạc mở mắt ra, phát hiện cảnh tượng trước mắt chẳng khác gì trước lúc lâm chung.\n\n\"Muphí\" chết đi,\"Muphí Hoán Tỉnh\" thức dậy.\n\nNgười liên kết của cô, là một khối máu thịt ngọ nguậy do chính cô sinh ra, không nghe được, không nói được.\nThần Minh sinh ra Vương Nữ, Vương Nữ lại mang thai Thần Minh, còn Thần Minh một lần nữa đánh thức hài cốt của cô, số phận bệnh hoạn cứ thế quấn chặt lấy cô, không bao giờ thấy ánh mặt trời, không thể cắt đứt.\nNgười mẹ sùng đạo của cô vui mừng khôn xiết, Dẫm Hải Giả phủ phục cầu nguyện, danh dự của cô được tiếp nối, thậm chí còn hơn xưa.\nNhưng \"Muphí\"đó rốt cuộc đã vĩnh viễn biến mất. Cô gái từng dựa vào sự ngây thơ ngu ngốc, ảo tưởng nổi loạn chống lại số phận bất công, ôm lấy vương miện phù hoa mà một thời ghét bỏ, bước lên con tàu du lịch mãi mãi không thể cập bến bờ kia."
  },
  AwakerStory_11292_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11292_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11293_Content = {
    Text = "Tôi thích biển. Biển Fèi Fúer. Biển màu xanh Phổ. Biển thổi những cơn gió ấm ướt. Từ khung cửa sổ của bệnh viện dưỡng lão nhìn ra, biển giống như một bức tranh sơn dầu. Biển chở những cánh buồm trở về. Biển mang thai vô số sinh lực như một người mẹ. \nHiện nay, cuối cùng tôi đã trở về với đại dương yên bình, trở về trước khi chưa ra đời, trở về với cái thai được bao bọc trong nước ối của mẹ. Dòng hải lưu nhặt những mảnh vụn không may mắn đó, ghép lại giữa xương trắng và sơn. Những con cá bơi lội trong hải vực lướt qua, lắng nghe những tiếng thở dài về những khổ đau của số phận. \nMẹ ơi, nếu có thể được sinh ra một lần nữa, liệu tôi có thể trở nên hạnh phúc hơn không?"
  },
  AwakerStory_11293_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11293_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11294_Content = {
    Text = "Nhóm khảo cổ Evrotas đã bị quấy rầy bởi căn bệnh kỳ lạ này suốt mười ngày, hiện tại tình hình vẫn chưa cải thiện. \n Căn bệnh đến mà không có dấu hiệu gì, nhưng diễn biến rất nghiêm trọng. Bệnh nhân thường xuất hiện ảo giác nghiêm trọng, kèm theo cảm giác thiếu hụt về cơ thể, cảm giác giác quan bị mất, và theo thời gian tình trạng trở nên xấu đi, cuối cùng dẫn đến liệt nửa người hoặc thậm chí liệt toàn thân. Mặc dù hiện tại có vẻ như phạm vi lây nhiễm của bệnh chỉ giới hạn ở hiện trường khảo cổ bên bờ tây sông Evrotas, và bệnh nhân chủ yếu là nhân viên và học giả tại hiện trường khảo cổ, nhưng các cơ quan chức năng không thể loại trừ khả năng lây lan ra xung quanh. \n Một công nhân từng làm việc tại hiện trường khảo cổ đã tiết lộ với phóng viên rằng căn bệnh đã có dấu hiệu xuất hiện cách đây mười lăm ngày - đúng vào ngày phát hiện xiềng xích Evrotas. Những độc giả theo dõi tin tức khảo cổ liên quan chắc hẳn sẽ nhớ đến chiếc xiềng xích được bảo quản hoàn hảo, không có dấu hiệu rỉ sét, nhưng thật sự có nguồn gốc từ nền văn minh cổ xưa. Nó đã đến Vương quốc Leo vào ngày hôm qua, được Đại học Misag tiếp nhận để nghiên cứu tiếp theo. Mối liên hệ giữa căn bệnh và chiếc xiềng xích thì càng mang màu sắc thần bí. \n \"Kể từ khi nó được khai quật, trong trại đã trở nên bất thường.\" Công nhân đó chỉ ra với phóng viên, \"Nhiều người gặp ác mộng, mơ thấy một cô gái bị xích trong một cái lồng, còn có người giữa đêm... Đây chính là lời nguyền, lời nguyền của chiếc xiềng xích! Không thể có giải thích nào khác.\" \n Đến ngày báo cáo, các cơ quan liên quan đã tiếp quản khu vực này và nghiêm cấm bất kỳ ai ra vào. Hoạt động khảo cổ Evrotas hiện đã hoàn toàn ngừng lại. \n —— \"Lời nguyền cổ xưa? Căn bệnh quét qua nhóm khảo cổ Evrotas\""
  },
  AwakerStory_11294_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11294_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11295_Content = {
    Text = "Bạc tâm của Lắc được khai quật từ bên trong Tháp Tam Giác khổng lồ, một kỳ quan nổi tiếng ở Lemvahi, có hình dạng hoàn hảo như viên đạn, kích thước và kiểu dáng giống hệt đạn của súng quay nòng SAA, được nhúng trong hộp sọ của một bộ xương nam giới trẻ tuổi. \n Khi chạm vào bạc tâm này, trước mắt sẽ xuất hiện cảnh tượng tuyệt đẹp nhưng hoành tráng của Tháp Tam Giác, thân thể không tự chủ được co rút và bò sát xuống. Giả sử người chạm vào cố gắng kháng cự và ngẩng đầu lên, họ sẽ thấy bóng dáng của một người đàn ông đội mão mờ ảo trong ánh sáng ngược, sau đó ý thức đột nhiên bị gián đoạn, bạc tâm tự nhiên rơi ra khỏi tay. \n \"Đỉnh Tháp Tam Giác chưa bị mài mòn, nên đây có lẽ là hình ảnh ngay sau khi nó được xây dựng.\"— Nhân viên thí nghiệm B·R·Langman \n \"Tôi có thể nghe thấy những tiếng thì thầm kinh hoàng từ linh hồn tối tăm.\"— Nhân viên thí nghiệm K·Waters \n \"Tôi muốn tố cáo việc Misaque sắp xếp chúng tôi thực hiện các thí nghiệm phi nhân đạo. Việc chạm vào bạc tâm này liên tục đã gây ra tác dụng phụ khiến người ta mất hoàn toàn khả năng kiểm soát thân thể. Nói chung, tôi kiên quyết từ chối chạm vào nó lần nữa.\"— Nhân viên thí nghiệm L·Lopez"
  },
  AwakerStory_11295_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11295_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11296_Content = {
    Text = "A. F. 18@1 năm @1 tháng, @2 trung đoàn bộ binh, Vương quốc Lemvahi, Cảng Alexandria\nTình hình Cảng Alexandria dần ổn định, Tiểu đoàn 3, Tiểu đoàn 4 của trung đoàn bộ binh, cùng với ba đại đội lính súng trường đã đi qua kênh đào, hướng tới @4 để thực hiện bước chiến đấu tiếp theo, hiện chỉ còn Tiểu đoàn 1 và một đại đội lính súng trường đóng quân tại Alexandria.\nMột đội nhỏ trong khi tuần tra đã gặp phải quân nổi dậy và đã nhanh chóng giải quyết. Họ đã mang về một món đồ thú vị, trông giống như một miếng bạc, nhưng nặng hơn bạc. Tôi đã cất nó vào trong két an toàn, chỉ huy sẽ thích món quà này.\n...\nNgày thứ 13 đóng quân, các đơn vị khác nhau đều có binh sĩ xuất hiện hành vi bất thường, các hành động cụ thể bao gồm nhưng không giới hạn ở việc tấn công đồng đội, tấn công chỉ huy, phá hoại vật tư cung cấp, phá hoại trang bị quân sự, v. v. Những người này, cùng với những kẻ điên loạn trước đó, đã được giam giữ dưới sự giám sát của tôi.\nHọ có đôi mắt đỏ ngầu, nước bọt văng tung tóe, trông giống như một loại động vật đáng thương hơn là binh sĩ. Có một thứ điên rồ nào đó đang tràn lan ở đây, tôi lo lắng nó sẽ phát triển thành dịch bệnh.\n...\nNgày thứ 30 đóng quân.\nĐến hôm nay, tổng cộng có 370 binh sĩ xuất hiện hành vi điên rồ, trong đó có 331 người đã xuất hiện tình trạng tê liệt chi sau 20 ngày biểu hiện cơn điên mạnh mẽ. Họ vẫn rất hung hăng, đã có 2 bác sĩ quân y bị cắn trong khi cố gắng điều trị bệnh nhân.\nCơn điên vẫn tiếp tục lây lan. Tôi đã báo cáo tình hình, hy vọng họ sẽ sớm có hành động.\n...\nHội nghị thẩm tra đã tiếp quản quân đội đóng tại Alexandria được 10 ngày, mọi người vẫn đang rơi vào điên rồ, các anh em của tôi lần lượt rơi vào điên rồ. Tôi không hiểu, tại sao chỉ có chúng tôi bị cái dịch bệnh khốn kiếp này hành hạ? Tại sao người địa phương không sao? Những kẻ nổi dậy luôn gây rắc rối cho chúng tôi cũng không sao?\nĐầu tôi ngày càng đau, nhưng các bác sĩ quân y lại bất lực—họ đã rơi vào điên rồ trước tôi, đã trở thành một trong những con quái vật nằm dưới đất cắn xé.\nTôi lo lắng mình cũng sẽ bước vào cơn điên.\nĐám người đó nói rằng chúng tôi phải chờ người từ Đại học Misag đến. Đi chết đi, chúng tôi đã sinh tử vì đất nước, chúng tôi không đáng bị đối xử như vậy.\n...\nTôi đã biết, cuối cùng tôi cũng đã biết. Đó là một linh hồn oán hận, trú ngụ trong miếng bạc ấy, muốn báo thù tất cả những kẻ xâm chiếm vùng đất này. Người phụ nữ thiếu một chân muốn chúng tôi đi, bà ấy muốn chúng tôi đi, trả lại mọi thứ ở đây cho chủ nhân ban đầu. Đúng, đúng rồi, nên như vậy, chúng tôi không bao giờ nên đến đây, không bao giờ nên bắt đầu cuộc chiến này, tôi@1@3@4@2@1@2@3\n—— trích từ\"Nhật ký của chỉ huy đại diện Tiểu đoàn 1 trung đoàn bộ binh @2\""
  },
  AwakerStory_11296_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11296_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11297_Content = {
    Text = "Cô ấy không phải được sinh ra từ máu, mà một thời, cô cũng từng tắm mình trong tình cảm nhiệt thành nhưng ngắn ngủi như hoa bỉ ngạn. Bội phản và tai họa ngục tù đã tưới nước cho ngọn lửa phản loạn, ánh lửa trả thù đã thiêu rụi Mecia, trong sự nhiễm độc của thù hận kéo dài, trái tim cô đã không còn mở ra với bất kỳ ai nữa..."
  },
  AwakerStory_11297_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11297_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11298_Content = {
    Text = "Do thể thức tỉnh nguyên gốc từng là \"Não trong bình\" đã có lịch sử thoát khỏi thiết bị S355, hiện tại đã được viện trưởng Khổ Lệ Đặc thực hiện chuyển giao, được bố trí vào thiết bị hạn chế rỗng rỗng đặc biệt mới. \n Thiết bị hạn chế này nằm sâu trong hồ đen, trong khi đảm bảo không có bất kỳ thiết bị và vật phẩm nào trong bán kính 30 mét xung quanh thiết bị hạn chế, nhóm giám sát hồ đen sắp xếp ít nhất một ca tuần tra giám sát mỗi 60 phút. \n Trong quá trình giám sát, phát hiện thể thức tỉnh này luôn giữ ý thức tỉnh táo, gần như chưa bao giờ có hoạt động ngủ. Thể thức tỉnh này đã cố gắng kể cho các thành viên tuần tra về thí nghiệm biến đổi bạc tâm vi phạm mà nó đã thực hiện trước đó, một thành viên nhóm đã rơi vào điên rồ vì đã có cuộc trao đổi ngắn với nó. \n Hiện tại, tất cả các nhóm tuần tra gồm ba người, nghiêm cấm tiếp xúc hoặc trò chuyện với thể thức tỉnh này, và trong suốt quá trình tuần tra phải đeo tai nghe cách âm. \n …… \n Mức độ bảo mật hạn chế của thể thức tỉnh này đã đạt đến cấp độ cao nhất trong việc quản lý thể thức tỉnh, bất kỳ nhân viên nào biết thông tin cũng không được tiết lộ bất kỳ thông tin nào liên quan đến thể thức tỉnh này ra bên ngoài Misaque, nếu không có sự phê duyệt của viện trưởng và được hộ tống trực tiếp, cấm bất kỳ ai đến thăm. \n —— Trích từ \"Báo cáo ghi chép nhóm giám sát hồ đen Misaque\""
  },
  AwakerStory_11298_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11298_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11299_Content = {
    Text = "Ngài là sự tồn tại thực sự. \n Ngài là ánh mắt của thần linh, là nhánh cây mà thần linh vươn ra với vũ trụ. \n Ngài tận hưởng sự hùng vĩ của lịch sử, khao khát sự thịnh vượng của nền văn minh. \n Ngài muốn vượt qua sự héo úa, muốn vượt qua cái chết. \n Cô ấy muốn những bài ngâm trầm buồn, gió mang vị mặn của đất và muối, muốn những chiếc lá bạc và ánh trăng Mosul. \n Mụ phù thủy, mụ phù thủy, nữ phù thủy… ánh mắt của nhân loại chỉ là vật ngoài thân. \n Chỉ cần một giọt máu có thể thoát khỏi cuộc tấn công của bóng tối, Ngài sẽ có thể một lần nữa ôm trọn vĩnh cửu trong vòng tay."
  },
  AwakerStory_11299_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11299_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11300_Content = {
    Text = "Gai hồng đâm thủng trang giấy thơ, để lại vết tích như máu trong suốt. Mùi rượu bay tỏa xung quanh, lưỡi lửa vô sắc lây lan khắp nơi. \n Giữa ngọn lửa dữ dội, Ôrla nâng niu tập thơ cuối cùng, viết nên những chú thích vô thanh cho số phận cuối cùng của thiên tài thi sĩ ẩn mình trong nhà kính."
  },
  AwakerStory_11300_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11300_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11301_Content = {
    Text = "Thời thiếu nữ của cô được trải qua trong doanh trại quân đội. \n Giống như tất cả những đứa trẻ lớn lên trong doanh trại, cô tin tưởng sâu sắc vào vinh quang của quân đoàn và coi nó là lý tưởng sống của mình. Thế giới của cô rất đơn giản: điều chỉ huy công nhận là đúng, điều chỉ huy cấm đoán là sai. \n \"Hãy giơ kiếm hướng về phía kẻ thù, chúng ta sẽ giải phóng mảnh đất này khỏi xiềng xích; hãy chém vào đội quân xâm lược, đừng tỏ lòng thương xót, mọi hy sinh hiện tại đều vì sự ổn định và thịnh vượng tương lai.\"\n Cô rèn luyện dưới khẩu hiệu đó, và bước lên chiến trường dưới khẩu hiệu đó. Sau một lần cứu người liều chết, cô nhận lấy một chân bị thương và danh hiệu anh hùng chiến tranh. Từ đó, cô đeo huân chương lui về tuyến sau, trở thành giáo quan tân binh, hoàn toàn không biết rằng vết thương ở chân sẽ hé lộ cho cô một thế giới như thế nào. \n Chân tàn tật bị sỉ nhục. Elva tức giận quyết định rời quân ngũ. Khi bước ra đường phố, cô mới thực sự nhận ra rằng bài diễn văn rực rỡ của chỉ huy là những lời dối trá — giải phóng chỉ là cái cớ cho sự xâm lược, người dân nơi đất khách đang chịu đựng đau khổ. \n Đây không phải là quốc gia lý tưởng của cô, đây không phải là tương lai rực rỡ không có máu và nước mắt. \n Vì vậy, cô đã giơ lưỡi dao chuộc tội chống lại những đồng đội cũ, và thề sẽ chiến đấu vì công lý thật sự."
  },
  AwakerStory_11301_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11301_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11302_Content = {
    Text = "\"Chào mừng đến với cửa hàng trao đổi của Đào Đen Đá, chúng tôi cung cấp dịch vụ trao đổi và thu gom đầu lâu, giá cả tuyệt đối công bằng, không lừa dối trẻ em hay người già.\"\nTrong làn sương xám, người phụ nữ nhẹ nhàng gõ nhẹ ống điếu gỗ cổ kính, dưới vành mũ lay động, khóe môi thỉnh thoảng hiện ra nụ cười đầy mờ ám."
  },
  AwakerStory_11302_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11302_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11303_Content = {
    Text = "Mọi người nhanh chóng chấp nhận một sự thật: nơi nào có Jenkin, nơi đó có Brun, và nơi nào có Brun, nơi đó có Jenkin. Và một khi Brun hành động riêng, đừng nghi ngờ, đằng sau chắc chắn có bóng dáng của Jenkin. \n \"Sao bạn lại nói tôi trộm? Tôi có bằng chứng ngoại phạm đấy!\"\nCô gái cầm thứ mà Brun đã \"lấy\"đi nói như vậy."
  },
  AwakerStory_11303_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11303_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11304_Content = {
    Text = "Năm A. F. 180, dưới ảnh hưởng của đại hạn hán ở Bắc bán cầu, sông Kara Su xuất hiện tình trạng ngắt dòng. \n Cư dân địa phương đào lên từ bùn dưới lòng sông một bộ xương quái vật. Do sông Kara Su trong văn hóa địa phương có ý nghĩa là \"nước đục\", bộ xương này được đặt tên là \"Xương Hỗn Loạn\". \n Sau khi được các nhà sinh vật học biển giám định, đây là bộ xương của một con cá voi cánh lớn, dài khoảng 32 feet(khoảng 9,75 mét), toàn thân được bao phủ bởi một chất màu bạc. Năm sau, bộ xương này được đấu giá tại phiên đấu giá Isis với giá 1,3 tỷ reo phường. \n Công ty đấu giá từ chối tiết lộ danh tính thực sự của người mua, nhưng theo tin đồn, bộ xương đã được vận chuyển đến một trường đại học tư nhân ở ngoại ô thành phố Lentiennam."
  },
  AwakerStory_11304_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11304_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11305_Content = {
    Text = "Kiêu ngạo không coi ai ra gì chỉ là một lớp áo giáp giả dối. Dưới chiếc váy đẹp đẽ đó, bao bọc một trái tim nổi loạn không ai hay biết. \n Sống trong cái đẹp của một cái lồng thiêng liêng được tưởng tượng ra, Muphí hiểu rõ hơn ai hết sự giả dối của con người, sự giả dối của thần thánh: ánh mắt của tín đồ nhìn cô chỉ là sự sợ hãi và thương hại, tình thương của \"Người chăm sóc\" dành cho cô chỉ là sự chăm sóc của một lễ vật. Điểm kết thúc của sứ mệnh không phải là vinh quang, mà là cái chết của chính mình — cô đã biết kết cục, thì làm sao có thể chìm đắm trong vương quốc xa xôi được phác họa bởi giáo lý. \n Kế hoạch tôn thờ thần thánh, sự phục hồi của vị vua cũ, quá nhiều kỳ vọng không thực tế được gửi gắm vào cô — nhưng chưa bao giờ có ai quan tâm đến việc liệu cô có sẵn lòng chấp nhận số phận chắc chắn sẽ chết để đổi lấy tương lai không chắc chắn hay không. \n Chim hoàng yến không muốn mãi mãi bị giam cầm trong lồng, vì vậy cô đã vỗ cánh lao về phía hàng rào đầy gai. Quyết tâm đặt cược mạng sống để thoát khỏi sự ràng buộc của số phận, cô sẽ tự mình quyết định hướng bay tiếp theo. \n \"Tôi tên là Muphí... Đừng nghĩ rằng có thể chỉ huy tôi! Việc gì nên làm, việc gì không nên làm, tôi tự có quyết định trong lòng.\""
  },
  AwakerStory_11305_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11305_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11305_UnlockDesc_1 = {
    Text = "Hoàn thành chương 5 bình thường của câu chuyện chính \"Mắt Bão\""
  },
  AwakerStory_11306_Content = {
    Text = "Trong sự cô đơn, loài tiên biển đã đón nhận sự diệt vong, nhưng lại tìm thấy sự tiếp nối kỳ diệu trên đất liền. \nDù sinh ra đã lạc quan, hay chọn lãng quên để trốn tránh nỗi đau, sự ngây thơ thẳng thắn đều tỏa ra sức hút vô tận, khiến người khác không tự chủ được mà gia nhập vào phe của cô — có lẽ đây là một chiêu trò nhỏ nhặt để mở rộng \"đội ngũ đồng hành\" của cô cũng nên."
  },
  AwakerStory_11306_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11306_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11307_Content = {
    Text = "Là sinh mệnh được sinh ra từ hỗn mang, cô ấy là sức mạnh hỗn mang thuần khiết, là linh hồn tự do không bị ràng buộc, cũng là trật tự chưa được định nghĩa. \n Cần phải thách thức, cần phải chiến đấu, chỉ khi khát vọng hủy diệt không thể kiềm chế được giải phóng, cô ấy mới có thể hoàn thành nhiệm vụ duy nhất mà người sáng tạo giao phó cho cô. \n —— Để canh giữ hành tinh cho đến ngày tận thế, cô ấy đã khao khát một trận chiến mãnh liệt quá lâu rồi."
  },
  AwakerStory_11307_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11307_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11308_Content = {
    Text = "Tôi có tư cách để có ước nguyện không? \nNếu có, liệu tôi có thể trở thành một phần của em gái tôi không? \nĐể cô ấy trở nên trọn vẹn, và chúng ta cũng trở nên trọn vẹn. \nNhư vậy, tôi có thể bày tỏ \"yêu thương\" mà không cần lo lắng, và cô ấy cũng có thể đón nhận \"yêu thương\" mà không chút do dự. \ntinkerer... Có lẽ đây là điều tôi, với tư cách là người con sinh ra trước, nên làm cho em."
  },
  AwakerStory_11308_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11308_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11309_Content = {
    Text = "\"Những nhận xét không thương xót\",\"bài thi điểm thấp\",\"báo cáo nghiên cứu không đạt yêu cầu\"\nTrong sự nghiệp giảng dạy hàng chục năm của Đóa, số học sinh nhận được chứng chỉ tốt nghiệp từ tay cô có thể đếm trên đầu ngón tay. Hầu hết học sinh đều bị thái độ quá nghiêm khắc của cô đẩy lùi, chuyển sang học với các giáo sư khác. Dần dần, danh tiếng xấu của giáo sư Đóa đã lan truyền trong các học sinh. \nNhưng cũng có học sinh tin rằng, cô chỉ đang sử dụng tiêu chuẩn này để chọn lựa \"đệ tử\". Chỉ những người có ý chí kiên cường nhất mới xứng đáng nắm giữ chìa khóa mở ra cánh cửa sự thật, cùng cô khám phá lớp vỏ thực sự của thế giới. \nDưới sự hỗ trợ của niềm tin như vậy, ngay cả khi khả năng tốt nghiệp từ tay Đóa gần như là không thể, đơn xin được Đóa dẫn dắt vẫn liên tục bay vào văn phòng. \nĐôi khi, Ramona bị gọi đến để xem xét đơn xin, không khỏi nghĩ rằng, nếu học sinh tin tưởng như vậy, cũng không tệ. \nTrong mắt Ramona, cô chỉ đang yêu cầu học sinh nhân loại theo tiêu chuẩn của thân thể thức tỉnh, chỉ vậy thôi."
  },
  AwakerStory_11309_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11309_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11310_Content = {
    Text = "Hành tung của Đào Đen Đá tại Đại học Misaque không thể đoán trước, dù sao cô cũng nắm giữ kiến thức cấm kỵ về việc di chuyển tự do giữa các chiều không gian, đến đi tự nhiên, không bị hạn chế bởi trung tâm hồ đen bạc tâm dưới lòng đất. \nCô thường xuyên bán những thiết bị hoặc vật liệu bí ẩn có nguồn gốc đáng ngờ, đôi khi cũng giúp đỡ các thân thể được đánh thức khác tạm thời thoát khỏi sự kiểm soát của Đại học Misaque. \nSau đó, thông qua đàm phán, cô đã mở một chi nhánh của cửa hàng \"Giải Lo Bách Hóa\" trong một căn phòng cũ bên cạnh phòng y tế ở góc khuôn viên trường. \nTất nhiên, tất cả các mặt hàng được bán đều phải được Đại học Misaque đăng ký và xét duyệt."
  },
  AwakerStory_11310_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11310_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11311_Content = {
    Text = "Người ghi chép: Erich von Werner\nThời gian: Ngày 7 tháng 11 năm 19@1\nTọa độ: 68°14′N, 67°10′T\n\nDo số lượng lớn xác cá nhà táng trôi nổi bất thường trên hành trình, chúng tôi buộc phải đổ bộ lên hòn đảo băng bị nguyền rủa này. Phía dưới thác băng ở vịnh hẹp bờ nam, đoàn thám hiểm phát hiện một xác sinh vật chân đầu dài khoảng năm mươi feet. Thi thể có màu xanh chàm đậm, bề mặt dày đặc các vòng tròn đồng tâm phát quang màu xanh lam mờ ảo, viền các vòng tròn tiết ra một lớp chất nhầy mỏng. Sau khi chúng tôi lấy mẫu và tinh chế, từ chất nhầy kết tinh ra một lượng lớn tinh thể màu xanh đáng lo ngại.\nĐường kính giác hút ở các xúc tu của xác sinh vật này vượt quá hai feet, bên trong giác hút khắc những hoa văn gần giống chữ viết không rõ nguồn gốc. Dây thần kinh chính ở trạng thái gel bán trong suốt, vẫn duy trì nhịp đập yếu ớt trong môi trường âm ba mươi độ (xem hình đính kèm D-7). Nhà sinh vật học tháp tùng, Tiến sĩ Harris, cố gắng lấy mẫu mô từ dây thần kinh chính, nhưng ngay khi dao mổ chạm vào, toàn bộ xác sinh vật đột ngột tan vỡ thành bụi. Bụi màu xanh chàm có thể nhìn thấy bằng mắt thường lơ lửng khắp phòng thí nghiệm.\n\nTrên đường trở về, Tiến sĩ Harris xuất hiện triệu chứng mê sảng liên tục. Ông liên tục vẽ các hình học kết hợp xoắn ốc và đa diện lên tường cabin, và gào thét rằng「chúng đang đẻ trứng dưới lớp băng Nam Cực」. Sáng sớm ngày hôm sau, thủy thủ tuần tra phát hiện ông chết đuối trong khoang nước dằn tàu, khám nghiệm tử thi cho thấy phế nang của ông chứa đầy vi sinh vật màu xanh chàm (cùng nguồn gốc với bụi xác bạch tuộc). Thuyền trưởng ra lệnh đốt toàn bộ quần áo đã tiếp xúc với mẫu vật.\nMong rằng không ai còn phải tiếp xúc với cơn ác mộng ẩn giấu dưới lớp băng này nữa.\n\n——《Nhật ký khảo sát Nam Cực · Phụ lục số 37》"
  },
  AwakerStory_11311_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11311_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11312_Content = {
    Text = "Làm sao chúng ta có thể quên được anh hùng Yâu U-hà-hi? Anh từng là một chàng trai xuất sắc nhất. Chiến binh quỳ gối trên cát vàng lúc hoàng hôn, máu nóng chảy dọc thân hình anh. Những con kền kền bay lượn trên cao, hát lên bài ca tiễn biệt cho anh:\nKhông một ai dùng nước mắt để tôn kính anh, không ai dùng tiếng khóc để chôn vùi anh, bởi vì trước khi ra đi, anh đã nổi danh khắp Roma."
  },
  AwakerStory_11312_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11312_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11313_Content = {
    Text = "A.F.@1 năm @2 tháng\nKính thưa quý tộc Cavendish:\n\nXin hãy tha lỗi, tôi đã mạo muội yêu cầu quản gia Frey mang cho tôi giấy bút, cố gắng giữ lại chút lý trí và phẩm giá để viết bức thư này. Kể từ khi tôi mắc bệnh nặng, tôi chưa bao giờ có thể gặp lại mẹ, Poppy và cả ngài, nỗi nhớ này đủ khiến tôi phát điên.\nBị giam trong tầng hầm đã…… 353 ngày rồi? Tôi không biết, có thể là 326 ngày.\nỞ đây rất lạnh, khắp nơi đều là mùi thối rữa. Vết thương của tôi chảy ra chất nhờn đen, lại bị chuột gặm nhấm đến không thành hình dạng. Nhưng không sao, đau đớn là điều tốt, nó giúp người ta tỉnh táo.\n「Ma cà rồng ác độc」,「khiến gia đình nhục nhã」…… việc cách ly tôi chắc chắn là quyết định khôn ngoan. Linh hồn tôi đã sớm bị quỷ dữ kiểm soát, khi viết bức thư này, tôi vừa hút cạn máu của một người lang thang đã chết. Quản gia Frey nói, là ngài đã sai người tìm từ trên phố. Dù hương vị có hơi biến chất, nhưng tôi vẫn rất vui, hóa ra ngài vẫn quan tâm đến tôi.\nHơn nữa…… có thể cung cấp cho tôi một cái chăn không? Hiện tại tôi không có bất kỳ trang phục nào có thể che thân, mùa đông ở Lentiennam thực sự quá lạnh.\nĐến giờ, tôi vẫn rất nhớ, những ngày chúng ta cùng nhau nghỉ dưỡng ở biệt thự Weiting khi còn nhỏ.\n\nEm gái chân thành của ngài\nReia\n—— Trích từ 《Vụ án Ma cà rồng Kensington · Tóm tắt hồ sơ: Chứng cứ C-601》"
  },
  AwakerStory_11313_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11313_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11314_Content = {
    Text = "A.F.31@1 năm 12 tháng giữa, cảnh sát đã nhận được báo cáo từ quản lý sân khấu thứ hai của @2 Vườn. Người báo cáo cho biết, trong vòng một tuần, sân khấu đã xảy ra bốn vụ hỏa hoạn nhỏ, tin đồn về \"Bóng ma ballet\" đang lan rộng trong số các thành viên của đoàn múa thuê sân khấu. \n Để đảm bảo buổi biểu diễn đầu tiên của vở ballet \"Bài ca thiên nga\" diễn ra suôn sẻ, cảnh sát đã phối hợp với Sở cứu hỏa Khu Tây để tiến hành điều tra chung. \n Ngày trước buổi biểu diễn, Đại học Misag cuối cùng đã tiếp quản cuộc điều tra. Các điều tra viên đã nhận thấy rằng, sau nhiều điểm bùng phát hỏa hoạn đều có dấu vết còn sót lại của linh tri thức. Cuối cùng, điều tra viên @3 đã phát hiện một thể thức tỉnh trong đống đổ nát dưới sân khấu thứ hai. \n Thể thức tỉnh này không phải là một cá thể vô tri, cô tự xưng là \"Liz\". Sau khi giao tiếp, thể thức tỉnh Liz cuối cùng đã thừa nhận tội danh phóng hỏa của mình. Sau khi buổi biểu diễn đầu tiên của \"Bài ca thiên nga\" kết thúc, điều tra viên @3 đã đưa thể thức tỉnh Liz về Đại học Misag để tiến hành tiếp nhận chính thức. \n\n Theo hồ sơ lịch sử, A.F.29@1 năm, khi đám cháy bùng phát tại sân khấu thứ hai của @2 Vườn, sân khấu đang diễn vở ballet. Trong ngày hôm đó, ngoài một đám quý tộc dưới khán đài, còn có một vị nữ chính trẻ tuổi tên là \"Elizabeth·Salle\" đã thiệt mạng trong biển lửa."
  },
  AwakerStory_11314_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11314_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11315_Content = {
    Text = "Một bước, rồi một bước nữa, tôi từ từ bước vào nước. Cô y tá ở bệnh viện dưỡng lão chưa bao giờ cho phép tôi đi đến nơi xa như vậy. Hy vọng rằng một bệnh nhân sắp không còn khả năng chi trả chi phí điều trị sẽ không khiến cô ấy bị trách móc quá nhiều.\nÁnh hoàng hôn phản chiếu trên biển. Những con sóng ập đến, nhẹ nhàng nâng váy của tôi. Nhiệt độ của nước biển ấm áp như vòng tay của mẹ.\nCơ thể chưa bao giờ nhẹ nhàng như lúc này, trong lồng ngực tôi có một ngọn núi lửa cạn kiệt, giờ đây chỉ còn lại làn gió biển lướt qua.\n \"Về nhà thôi.\"\nTôi nghe thấy đại dương gọi tôi bằng giọng nói của cha mẹ tôi. Họ đã đến bên kia biển cả để kiếm tiền chữa bệnh cho tôi. Nếu tôi không mang một cơ thể bất hạnh như vậy, họ cũng không phải khổ sở như thế. Nếu tôi có thể lặng lẽ biến mất dưới biển trong một đêm trăng... Tôi đã từng nghĩ như vậy vô số lần, nhưng khi nghĩ đến gương mặt buồn bã của cha mẹ, tôi chỉ có thể từ bỏ.\nNhưng một ngày nọ, trong một đêm trăng, con tàu của cha mẹ đã lặng lẽ biến mất dưới đại dương.\n \"Về nhà thôi.\"\nTôi dùng hết sức để tăng tốc. Biển cả luôn bình tĩnh tiếp nhận tất cả các linh hồn đau khổ, và với tôi, nơi cha mẹ ở chính là chốn nương náu vĩnh viễn.\nKhi bóng đêm từ bốn phương tám hướng buông xuống, tôi lần đầu tiên có thể thở một cách tự do."
  },
  AwakerStory_11315_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11315_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11316_Content = {
    Text = "Trí tuệ siêu phàm đã mang đến gánh nặng quá lớn cho cơ thể, mỗi ngày anh phải ngủ mê hơn mười lăm giờ, khi tỉnh dậy cũng luôn cảm thấy mệt mỏi. \n Trong giấc mơ, đôi khi anh cảm nhận được sự phẫn nộ của các vị thần; đôi khi anh mơ thấy không gian và thời gian giao thoa; có lúc thậm chí còn bước vào sâu thẳm, đối diện với thần minh... \n Anh chưa bao giờ cầu xin thần minh ban cho sự khải thị và lời tiên tri, nhưng dù có trốn tránh thế nào, lời tiên tri vẫn sẽ ứng nghiệm. \n Anh chưa từng yêu cầu bất kỳ sự cúng bái nào, việc được tôn thờ, được kính ngưỡng đều do người khác tự ý làm, anh hoàn toàn không quan tâm đến mọi thứ. \n Tái sinh chỉ là làm gián đoạn một giấc mơ dài dằng dặc của anh. \n Không cần phải kêu gọi, không cần phải cầu nguyện."
  },
  AwakerStory_11316_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11316_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11317_Content = {
    Text = "……\nNgày thí nghiệm: A.F.@1 năm@2 tháng\nMục đích thí nghiệm: Quan sát ghi chép phản ứng biến dị phát sinh sau khi bệnh nhân rỗng rỗng ghép tạng\nBước thí nghiệm: @3@4\nChọn lựa cơ thể của người anh đã chết của thí nghiệm để thực hiện thí nghiệm ghép, nhằm quan sát phản ứng thải ghép giữa những người thân trực hệ. Kẻ khốn khổ này đã bị bắn chết bởi nhiều phát súng khi đang trốn tránh sự truy bắt của cảnh sát@3Thí nghiệm rất thành công, vết thương chuyển sang màu đỏ và mọc ra xúc tu…… Máu phun ra như những viên ruby đỏ. \n@3@3\nNgười thực hiện thí nghiệm thể hiện sức nhẫn nại đáng kinh ngạc, cô ấy từ chối tiêm morphine. \nSau thí nghiệm, cơn khát máu gia tăng, tính tình…… khó mà diễn tả, tóm lại không phải là kiểu mà tôi có thể đối phó. \n—— Trích từ Herbert《Ghi chép thí nghiệm rỗng rỗng·Nhóm thứ tư@1》"
  },
  AwakerStory_11317_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_11317_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_11318_Content = {
    Text = "Đừng lại gần, đừng chạm vào, đừng nhìn thẳng, đừng thương cảm, trên thế gian có lẽ vốn dĩ tồn tại những sinh linh chỉ thích hợp sống một mình trong bóng tối. \nDù rằng điều này không phải là ý định của cô ấy, nhưng nếu bạn vì hình dáng yếu ớt của cô, giọng điệu nhút nhát, trang phục trẻ con mà thương cảm và nhìn thẳng vào đôi mắt của cô, bạn sẽ rơi vào sự ngưng trệ và tĩnh lặng vĩnh viễn."
  },
  AwakerStory_11318_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_11318_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_11319_Content = {
    Text = "Ngày thứ bốn mươi lăm gia nhập đoàn vũ công, tôi đứng trên sân khấu với tư cách là diễn viên chính. \n Ánh sáng rực rỡ chiếu vào mép váy, những viên kim cương nhỏ lấp lánh phản chiếu vẻ đẹp chói mắt. Ánh sáng đó khiến tôi không thể nhìn rõ mọi thứ, nhưng từ tràng vỗ tay vang dội, tôi biết màn trình diễn của mình còn rực rỡ hơn cả những viên đá quý. \n Trong những vòng xoay không ngừng, mọi bụi bẩn trên thế giới sẽ được những điệu múa tinh khiết cuốn trôi, gửi đến toàn thế giới vẻ đẹp của vũ điệu, vẻ đẹp của nghệ thuật, đó là ước mơ và sứ mệnh của tôi với tư cách là một vũ công—— \n\n Nhưng, những người ẩn mình trong những góc tối dưới sân khấu, họ là ai? \n\n Lisette, cô gái hành động tự do và thẳng thắn ấy, sao lại thì thầm với lão gia nổi tiếng kia? \n Angelica, thiên tài luôn khinh thường những vũ công khác, tại sao lại nâng váy trước chàng công tử nổi tiếng? \n\n Thật không thể chấp nhận…… thật bẩn thỉu! Ôi thần linh, nàng cảm hứng của tôi, xin hãy cho tôi biết, tôi phải làm gì để bảo vệ sân khấu của mình khỏi bóng tối, phải có ánh sáng nào để xua tan sự ô uế này——"
  },
  AwakerStory_11319_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11319_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11320_Content = {
    Text = "Từ khi còn nhỏ, Kasia đã thể hiện tài năng bắt chước xuất sắc. \nDù là điệu múa tinh tế đến đâu, chỉ cần cô nhìn một lần là có thể lặp lại; dù là ảo thuật phức tạp đến đâu, chỉ cần dạy một lần cô đã có thể nắm vững. Giọng nói, biểu cảm, thậm chí cả nụ cười và khí chất, Kasia đều có thể tái tạo hoàn hảo, thậm chí làm cho người khác không thể phân biệt được thật giả. Nếu cô có một xuất thân khác, hoặc một nghề nghiệp khác, có lẽ cô có thể tận dụng tài năng này để có một cuộc đời khác. \nThật đáng tiếc, cô chỉ là một đứa trẻ lớn lên trong một đoàn xiếc không ai biết đến. Những người trong đoàn xiếc chỉ nghĩ đến việc lợi dụng tài năng của cô để kiếm tiền, còn những người ngoài đoàn xiếc — họ chỉ mua niềm vui và không muốn dành sự đồng cảm. \nKhông ai quan tâm đến niềm vui của Kasia, may mắn thay, Kasia cũng không quan tâm. Mỗi khi cô nhìn thấy khán giả cười đùa, nhìn thấy các thành viên tranh cãi, nhìn thấy nữ bói toán rơi nước mắt trước bức ảnh, cô chỉ cảm thấy tò mò tách biệt: tại sao họ phải thể hiện những biểu cảm đó dưới sân khấu? Tại sao họ phải tiếp tục diễn khi không ai nhìn thấy? Tại sao họ nói đó là \"bộc lộ cảm xúc\" của họ? \nNiềm vui là gì? Nỗi buồn là gì? Cảm giác tuyệt vọng và sợ hãi mà \"nhà tài trợ\" cắt cổ cô nói khi cận kề cái chết, lại là gì? \nLà con người, cô không tìm thấy câu trả lời cho những câu hỏi này, nhưng như một đứa trẻ của phép thuật, như một sinh vật có thể thu thập \"cảm xúc\" từ người khác, có lẽ cuối cùng cô sẽ có được trải nghiệm mà cô chưa từng có. \nVì vậy, cô đã sáng lập nên lễ hội phép thuật và đưa nó đi khắp thế giới. \nNgười ta đến mua niềm vui, nhưng phải trả giá bằng mọi dục vọng. \n \"Đến đây, đến đây, đến lễ hội của tôi! Chỉ cần giao nộp một chút niềm vui, một chút nỗi buồn, bạn sẽ được xem màn trình diễn tuyệt vời nhất của thế kỷ!\""
  },
  AwakerStory_11320_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11320_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_11321_Content = {
    Text = "Ban đầu, chỉ là một ly nước soda nho thay thế cho rượu vang. \n Ở góc khuất không ai để ý, Sorrel làm ra vẻ đáng thương, cùng hai ba học sinh chia sẻ. \n Rồi, đó là một buổi trà chiều nhỏ. \n Tại căng tin học sinh, Sorrel từ chối nhiều lần món macaron do học sinh đưa tới, lộ ra chút tiếc nuối và chân thành. \n Cuối cùng, là sự tổ chức của một salon lộng lẫy, là sự nở rộ của một đóa hồng. \n Phòng nghỉ được trang trí bằng hoa và trang sức, những đóa hồng rực rỡ và những học sinh non nớt nâng ly chúc tụng, mọi người đều vui vẻ. \n Người giữ bí mật mới đã chứng kiến tất cả điều này và thầm cầu nguyện rằng bước tiếp theo của cô ấy đừng là \"trở thành Hiệu trưởng Đại học Misaque\"."
  },
  AwakerStory_11321_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_11321_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_11322_Content = {
    Text = "Biển nguyên chất dẻo quánh màu xám trống rỗng, những khái niệm mà những du khách xuyên chiều không gian kể về cũng chỉ dừng lại ở mức mô tả và tưởng tượng trừu tượng. \n Nó muốn dùng chính đôi mắt của mình để xác nhận những nơi mà con người \"thần vọng\", muốn tận mắt chứng kiến cảnh đẹp hùng vĩ của nhân gian, muốn tự thân trải nghiệm những cung bậc cảm xúc của niềm vui, nỗi buồn, sự sum họp và chia ly. \n Nhưng hơn hết, nó càng khao khát một người đặc biệt, một người đủ trân trọng, đủ để trao gửi niềm tin. \n Giao dịch công bằng đồng nghĩa với bình đẳng, đồng nghĩa với sự phân chia, đồng nghĩa với việc tiền hàng sòng phẳng, đồng nghĩa với không trả thêm dù chỉ một phần nhỏ và không chiếm đoạt dù chỉ nửa phần. Nhưng nó khao khát điều gì đó khác biệt, khao khát một niềm tin vô điều kiện sâu sắc, để xoá bỏ mọi ngăn cách, để vượt qua mọi sự thăm dò, để làm tan chảy lớp băng giá kiên cố nhất. \n Nó đã đạt được rồi mất đi, nhưng cuối cùng sẽ mất rồi lại tìm thấy."
  },
  AwakerStory_11322_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11322_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11323_Content = {
    Text = "Trong vô số đêm không ngủ, người điêu khắc mắc bệnh rỗng rỗng lắng nghe tiếng sóng biển, rơi vào giấc mơ rối loạn: \n Khi gia đình cô mang theo chiến tranh đến, cô xây dựng những bức tường cao vĩ đại của thành phố Luân Yên. \n Khi cha cô và các thành viên trong gia đình rơi vào giấc ngủ, cô khắc họa sử thi thành những bức tượng thánh bất diệt. \n Cảm giác của cô trở nên tê liệt, cơ thể cứng đờ, gần như không thể cầm nổi dao khắc. \n Ánh mờ trắng như san hô đã lan đến cẳng tay, cô nhìn chằm chằm vào đôi tay run rẩy, bỗng nở một nụ cười. Ngọn lửa sự sống cuối cùng sẽ tắt, và cơ thể sẽ trở thành vĩnh cửu. \n Cô như mong muốn được chìm xuống đáy biển. San hô vỡ vụn, dung dịch ăn mòn màu đen từng sợi từng sợi hòa vào biển cả—cô cuối cùng đã thấy thành phố Luân Yên đã mất từ lâu, và hòa làm một với nó."
  },
  AwakerStory_11323_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11323_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_11324_Content = {
    Text = "\"Một lòng hành dâm, phóng túng theo dục vọng, sẽ phải chịu hình phạt lửa đời đời, như một bài học cảnh tỉnh...\"\nLiên tục 23 ngày, các thầy tu đều đứng trước cổng thành của cô, miệng đọc những kinh văn nhàm chán. \nVanda đã ra lệnh cho người ta trói ông ta vào trong. \nThầy tu nói:\"Sao phải lo lắng vì khổ sở. Nơi nào có linh hồn của Chúa, nơi đó sẽ được tự do.\"\nCô ấy đã cởi bỏ quần áo của ông ta. \nThầy tu nói:\"Sao phải lo lắng vì y phục. Hoa huệ ngoài đồng không kéo sợi, cũng không cúi đầu\"\nCô ấy đã chặt đứt bốn chi của ông ta. \nThầy tu nói:\"Sao phải lo lắng vì chảy máu. Mọi sinh vật có thịt máu, không ai là không chết.\"\nVanda cười:\"Ta không chỉ muốn cho ngươi chảy máu, ta còn muốn biến ngươi thành nô lệ của ta, đời đời kiếp kiếp.\"\n \"Tại sao?\" Thầy tu ngẩng đầu lên,\"Ngươi không nên thương xót đồng loại của mình, như ta thương xót ngươi sao?\"\nVanda nhìn chằm chằm vào thầy tu. Đôi mắt của ông ta rất xanh, như màu trời trong xanh. \nCô ấy đã khoét mắt ông ta. \nVì không thể chịu đựng được những cực hình, thầy tu cuối cùng đã chết. Giáo khu địa phương e ngại quyền lực tài chính của cô, nên không ai dám chỉ trích cô. \nTrước khi chết, thầy tu nói:\"@2 đã đến gần, ngươi nên...\"\nNhiều năm trôi qua, Vanda đã sớm quên đi khuôn mặt và tên của thầy tu, chỉ nhớ đến đôi mắt của ông. Đêm đó, khi sắp bị @2 tiêu thụ, Vanda lại nghĩ đến câu nói chưa hoàn thành đó. \n \"@2 đã đến gần, ngươi nên...\"\nCô ấy trong ý thức mơ hồ suy đoán những gì thầy tu sẽ nói tiếp, nhưng không thu được gì."
  },
  AwakerStory_11324_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_11324_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
