  AwakerStory_11325_Content = {
    Text = "\"Ngươi là sự tồn tại mang sứ mệnh vinh quang, là hy vọng của Người tái hiện trên thế gian.\"\n \"Hãy là một đứa trẻ ngoan, nghe lời... Khi Người thức dậy lần nữa, mọi người đều có thể sống trong vương quốc bất tử vĩnh hằng.\"\nCô gái bí mật không thể công khai ra đời, vì một số lý do đã trở thành báu vật của chủ tế dẫm biển. Từ một đứa trẻ đáng thương mà không ai quan tâm, cô ấy đã biến thành nữ thánh liên kết với số phận và nền văn minh huyền bí. \nVị thánh mẫu khổ hạnh đã đích thân nuôi dưỡng cô lớn lên, sự tôn sùng và thờ phụng luôn bao quanh cô từ nhỏ, chỉ cần cô muốn, mọi thứ sẽ được dâng lên bằng hai tay. \nNếu hiện tượng rỗng rỗng chưa từng xuất hiện, \"thần minh\" chưa từng suy yếu, thì tương lai của cô chỉ là kế thừa chức chủ tế, đứng trên các tín đồ theo đúng trình tự. \nTuy nhiên, tất cả những gì cô nhận được, vào một ngày nọ đã đòi hỏi cô phải trả giá đắt – số phận mà cô chưa bao giờ mong muốn, đã được sắp xếp cho cô một kết cục không thể kháng cự. \nTrở thành mẹ của thần linh, sinh hạ đứa con tiên tri – sự hy sinh vinh quang của nữ thánh, chỉ là yêu cầu cô vui vẻ dâng hiến cơ thể và mạng sống của mình. \nKhi trái tim thứ hai bắt đầu đập trong lồng ngực cô, linh hồn của cô đã trở thành dòng sông cuộn chảy, định mệnh sẽ biến mất trong thời gian."
  },
  AwakerStory_11325_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_11325_UnlockDesc = {
