  AwakerStory_95007_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_95008_Content = {
    Text = "(Viết ở đầu hồ sơ)\nĐáng chết, bạn đã tìm thấy hồ sơ này như thế nào, tôi rõ ràng đã cấm bất kỳ ai xem thứ này... Thôi được, vì bạn có thể nhìn thấy hồ sơ này, điều đó có nghĩa là quyền hạn của bạn vượt xa tôi, điều này có nghĩa là bạn là một trong số những người đó, tôi tự nhiên không có quyền ngăn cản bạn biết những điều này.\n\nNhưng xin bạn hãy nhớ, hồ sơ này lẽ ra không nên tồn tại ở bất kỳ nơi nào, nội dung dưới đây cũng không phải là bất kỳ cuộc điều tra chính thức nào, mà là sản phẩm không chính thức được hình thành từ những suy luận thứ cấp của cá nhân dựa trên một số tình huống thực tế.\n\nTôi phải nhấn mạnh với bạn rằng, trong quá trình ghi chép hồ sơ này có chứa rất nhiều phương pháp điều tra không thể mô tả chi tiết, những phán đoán chủ quan từ suy nghĩ cá nhân và hành vi nhận hối lộ từ đối tượng điều tra. Nếu bạn không quan tâm đến những hành vi trên của tôi, xin hãy tiếp tục đọc, tôi đảm bảo với nhân cách của mình rằng, nội dung dưới đây có sự thật rõ ràng.\n\n■Số hồ sơ:■■■■-A■■-SSS\n■Mã hiệu thể thức tỉnh: Chúa của Lửa Nổ\n\"Thực ra tôi không thích tranh đấu.\"\nTôi rất ngạc nhiên khi nhận được câu trả lời như vậy, bởi vì trong tất cả các báo cáo, nhân viên điều tra đều thêm vào những từ như\"điên rồ\"\"vui vẻ\"\"hưng phấn\" khi mô tả cô ấy chiến đấu.\nTôi đã nghĩ rằng quan điểm của cô ấy về chiến đấu là\"không chủ động, không chán ghét, không từ chối\", không ngờ cô ấy lại cảm thấy ghê tởm với điều này.\nKhi cuộc trò chuyện tiếp tục sâu hơn, tôi dần hiểu ra một số điều, khi tôi hỏi liệu có thể ghi lại những nội dung này không, Katie Gula đã hào phóng đồng ý với hành động của tôi.\n\n\"Bạn phải biết rằng, đối với phần lớn mọi người trên thế giới, sống sót là một điều xa xỉ.\"\nTôi đồng ý với quan điểm này, mặc dù tôi và phần lớn những người tôi tiếp xúc đều sống một cuộc sống tốt đẹp, tôi thậm chí có thể đến nhà hát lớn nhất ở Lendienni để thưởng thức biểu diễn bất cứ lúc nào, nhưng tôi biết rõ bộ mặt thật của thế giới này, và có bao nhiêu người đang gánh nặng phía sau cuộc sống tốt đẹp của tôi.\n\n\"Vì vậy, trong nhiều trường hợp, khao khát đấu tranh mãnh liệt là phần thưởng bạn phải trả để sống sót.\"\n\"Chúng ta không thể chọn cách sống, một khi bạn đã bước vào bùn lầy, thì gần như không thể rút lui.\"\nTôi định phản bác quan điểm này, nhưng khi tôi nhớ lại một số trường hợp, tôi nhận ra họ đều không phải là người bình thường, và những kẻ vô danh, phần lớn chỉ tồn tại trong hồi ký của họ.\n\"Có thể một số người ngây thơ sẽ nói, nếu vậy, thì ngay từ đầu đừng làm điều đó, không phải sao? Suy nghĩ này rất tốt, tôi từng khắc nó lên một ngôi mộ nào đó, để tưởng niệm một người đã thực hiện nguyên tắc này.\"\n\"Để bảo vệ mọi người trong thế giới tàn nhẫn này, tôi phải thể hiện sự mạnh mẽ và điên rồ đủ để khiến những ác ý vô hình phải dè chừng.\"\n\"Tất nhiên, những cảm xúc mà tôi thể hiện trong chiến đấu không phải là giả dối, tôi thực sự đang tận hưởng cảm giác mà chiến đấu mang lại cho tôi.\"\n\"Có thể hơi khó hiểu, nhưng giống như bạn có thể thích nội dung công việc của mình, nhưng không thích công việc bản thân vậy.\"\nKhi nghe được lời giải thích này, tôi lập tức hiểu được ý nghĩa trong lời cô ấy. Thực sự, tôi rất thích việc dòm trộm đời sống riêng tư của người khác để thỏa mãn sự tò mò tội lỗi của mình, nhưng điều đó không có nghĩa là tôi thích phải dậy từ giường vào lúc tám giờ mỗi sáng, nghe lệnh đến một nơi nào đó và ở lại cả ngày.\n\n\"Khi tôi vừa bị bỏ rơi, tôi giống như nhiều cô gái khác, mơ hồ, do dự, không biết phải làm gì.\"\n\"Tôi hy vọng nhận được sự giúp đỡ từ người khác, nhưng thế giới đã cho tôi, chỉ có những sự phản bội và đau đớn không đếm xuể.\"\n\"Dần dần, tôi bắt đầu xây dựng một lớp giáp chống lại ác ý bằng sự tàn nhẫn và điên rồ, thích ứng với mọi thứ của thế giới như một người uống thuốc độc để giải khát.\"\n\"Cho đến cuối cùng, chúng tan chảy trong ngọn lửa không ngừng nghỉ, hòa vào máu thịt của tôi.\"\nNhư thể để xác nhận những gì vừa phát biểu, Katie Gula đột nhiên hiện ra một nụ cười cực kỳ tàn nhẫn, ác độc và điên rồ, khiến tôi sợ hãi đến nỗi làm đổ chất lỏng màu vàng nhạt trong cốc lên người mình.\nÔi, có lẽ đây là điều tốt, vì như vậy có thể tránh được nếu tôi thực sự không kiểm soát được cơ bắp của mình dẫn đến việc rò rỉ một số chất lỏng, có thể giải thích một cách tự nhiên rằng đó là đồ uống vừa đổ lên người.\nVào cuối cuộc rời đi, Katie Gula vẫn không trả lời thẳng thắn câu hỏi của tôi, nhưng tôi nghĩ rằng, phán đoán trước đó của tôi là đúng, cô ấy thực sự không nên tồn tại trong DIOL.\n—— Nhân viên ghi chép Karapolis Trak\n\n\"Mong ước ban đầu của tôi, chỉ đơn giản là muốn có một gia đình.\"\n\"Một gia đình không có phản bội, không có đau đớn, đầy tiếng cười và niềm vui.\"\n\"Đáng tiếc, cho đến ngày đó tôi mới hiểu.\"\n\"Đó là một ảo tưởng xa xỉ nhất trong thế giới tàn nhẫn này.\"\n—— Katie Gula"
  },
  AwakerStory_95008_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_95008_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_95009_Content = {
    Text = "Katie Gula thành thạo sử dụng nụ cười biểu tượng của mình, khiến tất cả những người đang chú ý cảm nhận được sự lạnh lẽo thấu xương, tỏa ra từ sâu thẳm ý thức, đầy tàn nhẫn và điên cuồng. \n Hai khẩu súng luôn bên cạnh nhau, dùng bụi thuốc súng cuộn quanh nòng súng, cảnh báo tất cả những kẻ ngu ngốc có ý định mờ ám rằng sự hy sinh của những kẻ vô danh là nền tảng vĩ đại của mọi điều. \n Nhưng bất cứ ai đã từng giao tiếp với cô ấy đều hiểu rằng, việc săn lùng những người bình thường không được ánh sáng mặt trời chiếu rọi, chỉ là một thú vui trong những lúc cô ấy cảm thấy nhàm chán. \n Dù sao, khi cô ấy thực sự mở súng, nòng súng sẽ không có thuốc súng."
  },
  AwakerStory_95009_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_95009_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_95010_Content = {
    Text = "■ Mã hồ sơ: DIOL-A3-9 \n■ Mã thức tỉnh: ■■■■ \n\nDựa trên quan sát liên tục, phát hiện ra rằng thức tỉnh thể này không tỏ ra quan tâm đặc biệt đến Mễ Tát Cách, thậm chí có thể nói là không hứng thú. Cô ấy chỉ tới trường khi nhận nhiệm vụ, sau đó nhanh chóng rời đi. \nMặc dù theo báo cáo điều tra được gửi về, thức tỉnh thể này thực sự có vài lần lưu lại trong khuôn viên trường trong thời gian dài. \n\nTuy nhiên, theo điều tra tiếp theo, lý do chính của việc lưu lại là để giúp học sinh giải quyết một số vấn đề. Được xác định là không tồn tại nguy cơ an toàn, không cần can thiệp. \n\nĐiều cần chú ý là thức tỉnh thể này dường như có sự quan tâm nhiều hơn bình thường đối với Người giữ bí mật. Cô ấy đã nhiều lần mang tới Người giữ bí mật những vật phẩm bị liệt kê là hàng cấm @3, và mời Người giữ bí mật tham gia các bữa tiệc tối mà danh tính những người tham gia không được biết. Xét đến tầm quan trọng của Người giữ bí mật đối với Mễ Tát Cách, nếu thức tỉnh thể này có ý định thực hiện hành động nguy hiểm đối với Người giữ bí mật, cần sắp xếp ít nhất 4 nhân viên vũ trang cấp γ để đảm bảo Người giữ bí mật có thể rút lui an toàn. \n\nNgười ghi chép: K. Trắc \n\n(Chữ nhỏ viết phía sau hồ sơ) \nNày, bạn à, có thể cũng là chị, chuyện đó không quan trọng. \nTay xui xẻo trước đó đã bỏ cuộc rồi, giờ thì tôi chịu trách nhiệm cái dự án chết tiệt này đây. \nNếu bạn đang đọc cái này, điều đó có nghĩa là bạn không phải kiểu người chỉ biết ăn không ngồi rồi, mà là một người có óc quan sát tốt. Bạn nên tự vỗ tay tán thưởng chính mình. \n\nNghe này, mặc dù chúng ta luôn nói rằng chúng ta \"giám sát trong bóng tối\", nhưng tôi cảm thấy cô ấy đã phát hiện ra chúng ta từ lâu, chỉ là không thèm để ý mà thôi. \nTôi không hiểu tại sao chúng ta phải giám sát một người như cô ấy. Mặc dù lần tiếp xúc đầu tiên giữa chúng tôi có chút hiểu lầm, nhưng chuyện đó vốn là do lũ tà đạo gây ra, không liên quan gì đến cô ấy cả. \nHuống chi mối quan hệ của cô ấy với những học sinh, đặc biệt là với Người giữ bí mật, nếu dùng phép ẩn dụ mà nói, thì giống như là bà ngoại mua kẹo cho cháu vậy! Không thể nào có người mỗi ngày cho rằng bà ngoại mình muốn hiến tế mình cho những kẻ tà đạo chứ... à không, chờ đã, có thể ở đâu đó đúng là như vậy, nhưng chuyện đó không quan trọng! \nQuan trọng là, nếu cô ấy thực sự có ý đồ gì đó, tôi đảm bảo mọi chuyện đã xảy ra một cách âm thầm, chứ không đợi đến khi ủy ban nghiên cứu ra cái đối sách chết tiệt nào đó. \n\nPhù, chửi xong thấy thật sảng khoái. Tóm lại, tôi đã lên kế hoạch xóa tên cô ấy khỏi danh sách này, trước khi ủy ban thực sự làm gì đó mà cô ấy không thể tha thứ được. \nNếu đám ủy ban đó thực sự chọc giận cô ấy, tôi đảm bảo, sẽ không chỉ dừng lại ở hai tòa nhà đâu. Hy vọng lúc đó tôi đã chết rồi, nếu không tôi sẽ chết rất đau đớn. \n\nNếu bạn là người sắp sửa giám sát cô ấy, nhớ kỹ, đừng có làm điều gì quá đáng. Nếu bạn không ưa cô ấy, hãy coi cô ấy như một người lính đánh thuê xử lý công việc bẩn thỉu cho trường học là được. Trừ khi cô ấy thể hiện rõ trạng thái không ổn định, bằng không tuyệt đối đừng đối đầu trực diện với cô ấy! \nDĩ nhiên, nếu bạn muốn chút quà nhỏ... cô ấy có lẽ cũng sẽ không bận tâm việc bạn từng theo dõi cô ấy. Hãy mạnh dạn mà xin đi, thật lòng mà nói, mấy món bánh kẹo trong túi cô ấy thực sự rất ngon đấy. \n—— Karapolis Trắc, người bạn tốt luôn chửi rủa ủy ban cùng bạn."
  },
  AwakerStory_95010_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_95010_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_95094_Content = {
    Text = "Cuộc đời của anh sống dưới những sợi dây bị thao túng, kịch bản đã được viết sẵn từ sớm là một lời nói dối nực cười, khiến anh liên tục mất mát, quên lãng và bỏ lỡ. \n Khi còn trẻ, điều anh khao khát nhất là có thể tự do vẫy vùng đôi cánh, bay đến thế giới bên ngoài hồ nước đó để khám phá. \n Đến khi anh mất hết vì mong muốn đó, anh đã không còn có thể coi cuộc sống nhẹ nhàng, không lo âu ấy là toàn bộ ước mơ. \n Cơn thịnh nộ vô tận đã thắp sáng trái tim đen tối, nỗi đau và thù hận tích tụ thành máu, phải dùng cái chết của những kẻ giả dối đó mới có thể rửa sạch và đền bù."
  },
  AwakerStory_95094_Title = {
    Text = "Câu chuyện·bốn"
  },
  AwakerStory_95094_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 9"
  },
  AwakerStory_95095_Content = {
    Text = "Dựa trên sự xem xét về mối quan hệ có thể tồn tại giữa \"Trái Tim Thánh\" của Pollux và Lễ triệu hồi thần linh của Hội Giáo đèn lồng, Misaque đã thành lập một nhóm nghiên cứu để thực hiện một loạt kiểm tra và thí nghiệm đối với \"Trái Tim Thánh\".\n Đáng tiếc cho Pollux, \"Trái Tim Thánh\" này đã hoàn toàn thay thế chức năng của trái tim ban đầu của anh, hòa nhập vào cơ thể của anh, không thể trực tiếp lấy ra hoặc thay thế.\n Trong quá trình quan sát thí nghiệm, các nhà nghiên cứu phát hiện rằng \"Trái Tim Thánh\" có hình dạng giống như con mắt thường xuyên phát sinh những cử động nhẹ nhàng và xoay chuyển không theo ý chí của Pollux, giống như một con mắt thực sự.\n Tuy nhiên, sau khi kiểm tra nguồn sáng, đã chứng minh rằng \"Trái Tim Thánh\" không có chức năng tương tự như thị lực, mà hoạt động này giống như là do cảm ứng từ các sinh vật hoặc vật phẩm khác.\n Trong các thí nghiệm đối chứng với các vật phẩm khác nhau, sự gần gũi với các vật phẩm liên quan đến rỗng rỗng và bạc tâm dễ dàng kích hoạt hoạt động của \"Trái Tim Thánh\", đặc biệt là khi ở trước các sinh vật bị rỗng rỗng và thể thức tỉnh, hoạt động của \"Trái Tim Thánh\" càng trở nên rõ ràng hơn.\n Sau khi Pollux chủ động sử dụng sức mạnh của \"Trái Tim Thánh\", tính chất vật lý và hóa học của các vật phẩm thông thường không có bất kỳ thay đổi nào, nhưng trước các vật phẩm và sinh vật bị rỗng rỗng, hiện tượng rỗng rỗng mở rộng với tốc độ đáng kinh ngạc đã xuất hiện. Những động thực vật ban đầu ở giai đoạn sớm của quá trình rỗng rỗng có thể thấy rõ mắt thường đã tăng tốc qua giai đoạn phát triển, nhanh chóng chuyển sang trạng thái giai đoạn cuối của rỗng rỗng. Khi mức độ rỗng rỗng mà động thực vật chịu đựng càng nghiêm trọng, sự lan tỏa này càng nhanh chóng.\n Trong thí nghiệm thể thức tỉnh với các biện pháp bảo vệ nghiêm ngặt, khi đối mặt với sức mạnh của \"Trái Tim Thánh\", thể thức tỉnh đã cảm nhận được một mối nguy hiểm nào đó từ bóng tối đang tiến đến, do đó thí nghiệm đã bị gọi ngừng ngay lập tức. Pollux cũng đã đảm bảo với sự giải thích nghiêm túc từ phía nhà trường rằng sẽ không sử dụng sức mạnh của \"Trái Tim Thánh\" đối với thể thức tỉnh.\n Nhờ thái độ hợp tác cực kỳ của Pollux và khả năng tự kiểm soát tốt, Misaque không yêu cầu Pollux đeo các dụng cụ kiểm soát bắt buộc, chỉ định kỳ sắp xếp kiểm tra sức khỏe và đào tạo sử dụng sức mạnh cho Pollux.\n Được cho là sau khi nghe kết quả thí nghiệm, thể thức tỉnh Wenkel đã hét lên đến mức suýt ngất xỉu, và đã dán thông báo cấm Pollux lại gần lên cửa phòng thí nghiệm và ký túc xá của mình, nhà trường đã nhiều lần thuyết phục nhưng không có kết quả, Pollux thì một cách hào phóng đã nói rằng sẽ tôn trọng yêu cầu của Wenkel."
  },
  AwakerStory_95095_Title = {
    Text = "Câu chuyện·1"
  },
  AwakerStory_95095_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 3"
  },
  AwakerStory_95096_Content = {
    Text = "Trong ý tưởng ban đầu của thần số phận, có lẽ ông không nên được sinh ra trên thế gian. \n Ban đầu, chỉ có Cas-tơ-lơ được sinh ra từ thí nghiệm sinh đôi nhân tạo, ngay khi cái phôi thai vô tri vô giác này sắp bị xử lý và vứt bỏ, Pollux đã vật lộn và từ thịt máu của anh trai mình mà ra đời. Anh ta đã hút lấy sinh lực của anh mình, cũng cứu lấy sinh mạng của anh, máu thịt, linh hồn và số phận của họ từ đó đã giao thoa. \n Trong những ngày tu hành khô khan của giáo hội, cuộc sống và số phận của cả hai vốn không có gì khác biệt, cho đến khi bắt đầu nghi thức \"Cải tạo thánh\"đau đớn và tàn nhẫn đã đánh thức Pollux khỏi số phận của Con Thánh. Hai đứa trẻ đã thực hiện một hành động táo bạo nhất trong cuộc đời, họ cầm một cuốn sách lỗi thời vẽ nên một bản đồ thế giới, rồi từ một thế giới giả tạo trốn thoát sang một thế giới tưởng tượng khác. \n Giấc mơ mong manh và ngắn ngủi đã tan vỡ, nhưng hình phạt tàn nhẫn không thể đánh gục linh hồn của họ, nhưng nhánh rẽ tàn nhẫn của số phận đã khiến họ bị chia cắt. \n Yu Li-ét ra lệnh tách hai người ra để cung cấp, Cas-tơ-lơ trong Ao Tội không biết rằng những hình phạt mà họ tưởng tượng không hề được thực hiện trên Pollux, Yu Li-ét gần như nhân từ kết thúc hình phạt còn lại, thậm chí rất nhanh chóng thả Pollux ra khỏi phòng giam tối tăm, rồi chuyển sang giáo dục thần học nghiêm ngặt và khắc nghiệt. \n Sự kiên cường và nghi ngờ trong Pollux khi đối diện với ánh mắt bình tĩnh tuyệt đối của Yu Li-ét đã biến thành một loại bất an và sợ hãi, cô ấy chắc chắn nắm giữ một cách nào đó mà anh không thể chống lại, nên mới có thể thảnh thơi như vậy. \n Anh đã vật lộn, giả vờ, chưa bao giờ từ bỏ. Anh dường như đã làm nhiều điều... nhưng anh đã làm gì? Trong gương chỉ còn lại một linh hồn xa lạ, trung thành đội chiếc vương miện của Con Thánh. \n Anh và những ký ức của họ, đã hoàn toàn bị lãng quên."
  },
  AwakerStory_95096_Title = {
    Text = "Câu chuyện·thứ ba"
  },
  AwakerStory_95096_UnlockDesc = {
    Text = "Tỷ lệ đồng điều ở cấp 7"
  },
  AwakerStory_95097_Content = {
    Text = "Hắn là thịt máu sinh ra từ dị thể, cấu thành từ những làn da bị xé toạc và khâu lại, lồng ngực trống rỗng, trái tim bẩn thỉu và những chiếc xích vô hình. \n Hắn được nâng lên bệ cao, mọi người quỳ lạy dưới chân hắn, tuyên bố rằng hắn sở hữu linh hồn trong sạch. \n Hắn rốt cuộc là gì? Hắn mơ hồ hỏi trong vô số giấc mơ, giữa hồ nước xanh đậm và sương mù trống rỗng, chỉ có tiếng nói của hắn vang vọng cô đơn."
  },
  AwakerStory_95097_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_95097_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_95098_Content = {
    Text = "So với thái độ học hỏi nhiệt tình như Castor, phong cách tiếp xúc với thế giới của Polyxenes cẩn thận hơn nhiều.\nQuan sát, suy nghĩ, nghi ngờ, những suy nghĩ và cẩn trọng đủ làm cho anh ta có thể thành công chạy trốn cùng Castor dưới sự kiểm soát chặt chẽ của giáo hội.\nTừ thuở nhỏ, anh ta đã học cách thấu hiểu suy nghĩ của người khác, học cách nói dối, học cách giấu đi những suy nghĩ thật sự bằng nụ cười. Ngay cả trước mặt người anh em thân thiết, anh ta vẫn vô thức dùng nụ cười nhẹ nhàng để an ủi đối phương.\n\"Không sao đâu.\"\n\"Nhất định sẽ được.\" \nDưới bàn tay to lớn đó, người yếu đuối cần phải nỗ lực hết sức để tìm kiếm một chút hy vọng khả dĩ.\nSau khi trải qua thời gian dài quên lãng và lừa dối, giờ đây, anh ta càng không cho phép sự hiện diện của bất kỳ mối nguy hiểm và sai sót nào. Ngay cả khi lần theo lời khuyên của Thais tới gặp Mythag, trong một thời gian dài, anh ta vẫn giữ được cảnh giác đáng kể.\nTrong mắt các người đánh thức khác, Polyxenes là một người ít nói, nhưng rất kiên nhẫn, thường mỉm cười với người khác. Nhưng những người cao tuổi dày dạn kinh nghiệm khi thấy anh ta, đều cảm thán về sự khác biệt giữa hai anh em.\nTheo lời Thais, ngay cả trước mặt cô, Polyxenes cũng có ý thức che chở Castor ở phía sau——kể từ khi anh ta lấy lại ký ức, anh ta không còn muốn để Castor bảo vệ anh ta liên tục.\nJenkin cũng từng nghiêm túc phàn nàn với người giữ gìn về sự không nhất quán giữa Polyxenes, tuyên bố rằng khi mình vô tình nhặt được đồ của Castor, đã thấy gương mặt đột ngột trở nên u ám của Polyxenes. \"Gã đó chắc chắn là đang làm bộ tốt bụng! Thực tế hắn là loại người ăn thịt trẻ con!\"\nTuy nhiên, sau khi đối mặt với sức mạnh của người giữ gìn, thái độ của Polyxenes đối với người giữ gìn đã thay đổi 180 độ, dưới phản ứng mãnh liệt của \"Thánh Tâm\", anh ta tuyên bố đã thấu hiểu sự thật của thế giới từ linh hồn vĩ đại đó và đã chân thành tôn sùng người giữ gìn như một tín ngưỡng mới."
  },
  AwakerStory_95098_Title = {
    Text = "Câu chuyện·2"
  },
  AwakerStory_95098_UnlockDesc = {
    Text = "Cấp độ tỷ lệ đồng điều đạt cấp 5"
  },
  AwakerStory_96418_Content = {
    Text = "Người sáng lập thành phố di hài, vua xác sống vĩnh cửu. \n Bữa tiệc của ông xứng đáng được mong chờ nhất — nhà hàng lộng lẫy, những bước nhảy thanh lịch, cùng với những món ăn tao nhã được chế biến từ xác chết mà ông tự tay làm ra, chắc chắn sẽ khiến bạn không bao giờ quên."
  },
  AwakerStory_96418_Title = {
    Text = "Dữ liệu cơ bản"
  },
  AwakerStory_96418_UnlockDesc = {
    Text = "Cấp độ thân thể được đánh thức đạt cấp 1"
  },
  AwakerStory_96419_Content = {
    Text = "Rời khỏi Thành Phố Mộ Bia, Dulecain đã thể hiện khả năng thích ứng mạnh mẽ trong xã hội loài người. Đây là điều tất yếu, xã hội loài người đối với hắn không phải là một khởi đầu mới, mà là một sự trở về.\n Cách nói, cử chỉ, khí chất, lễ nghi... Tất cả của Dulecain đều không có gì đáng chê, vừa giữ lại khí chất của một vị quân chủ, lại không hề có sự kiêu ngạo của kẻ ở vị trí cao lâu dài.\n Dulecain không bài xích giao tiếp xã hội, nhưng hắn lại thiếu hứng thú với các chủ đề chính trị, kinh tế, học thuật, lý do duy nhất thu hút hắn đến những nơi này chỉ có một - ẩm thực.\n Ngoài việc thưởng thức, Dulecain cũng đam mê tham gia vào việc chuẩn bị thực phẩm liên quan đến bếp núc. Từ việc chọn nguyên liệu đến phương pháp chế biến, từ việc sử dụng gia vị đến kiểm soát độ chín, kiến thức uyên thâm và gu ẩm thực xuất sắc của Dulecain đã chinh phục mọi người mà hắn trò chuyện, họ nhận ra, trước đây hàng chục năm ăn uống của họ chỉ là để tồn tại, không khác gì một con thú ăn để sinh tồn. Ngay cả những kẻ đáng thương bẩm sinh không có vị giác, cũng có thể trải nghiệm nghệ thuật ẩm thực qua sự miêu tả của hắn, đạt được sự tái sinh về vị giác.\n Điều này tất nhiên liên quan đến phép tắc của Dulecain, hắn rõ ràng biết sự khác biệt về khẩu vị giữa loài người và xác sống. Dulecain tôn trọng sự khác biệt giữa các loài, không có ý định áp đặt khẩu vị của mình lên tất cả mọi người.\n \"Luôn có người thích coi cái khác biệt là dị giáo, trong thành bang của tôi, đây là hành vi rất không tao nhã. Tôi tôn trọng sự khác biệt giữa người với người. Trong sự khác biệt này, chúng ta mới có thể thấy nhiều khả năng về vẻ đẹp của thực phẩm.\"\n \"Nhưng ngươi thì khác, Người Giữ Gìn. Là một tồn tại đặc biệt như thế trên thế gian này... Tôi nghĩ, ngươi nhất định có thể như tôi, trải nghiệm vẻ đẹp vô song trong bữa ăn này...\"\n Khi nói câu này, nụ cười của Dulecain lấp lánh trong làn sương tím, giống như một con rắn độc duyên dáng thì thầm bên tai bạn, chờ đợi ngày đưa bạn ra ngoài, hoặc dụ dỗ bạn vào Vườn Địa Đàng."
  },
  AwakerStory_96419_Title = {
    Text = "Câu chuyện·2"
